export const ABILITIES = {"Aatrox":{"title":"the Darkin Blade","passive":{"name":"Deathbringer Stance","desc":"Innate: Periodically, Aatrox empowers his next basic attack to gain 50 bonus range and deal bonus magic damage equal to 4%–12% (based on level) of the target's maximum health, capped at 100 against monsters. Aatrox heals for 80% of the post-mitigation bonus damage dealt, reduced to 25% against minions.","img":"Aatrox_Passive.png"},"Q":{"name":"The Darkin Blade","desc":"Aatrox can activate The Darkin Blade three times before the ability goes on cooldown, with a 1-second static cooldown between casts. If Aatrox does not recast the ability within 4 seconds of the previous cast, it goes on cooldown.","img":"AatroxQ.png","cd":"14/12/10/8/6","cost":"0","range":"25000"},"W":{"name":"Infernal Chains","desc":"Active: Aatrox sends a chain in the target direction that deals magic damage to the first enemy hit, doubled against minions, and slowing them for 1.5 seconds. If this hits an enemy champion or large monster, a tether is formed between the target and the ground beneath them for 1.5 seconds, during which they are revealed.","img":"AatroxW.png","cd":"20/18/16/14/12","cost":"0","range":"825"},"E":{"name":"Umbral Dash","desc":"Passive: Aatrox heals for 16% (+ 0.9% per 100 bonus health) of non-persistent post-mitigation damage he deals against enemy champions. Active: Aatrox dashes in the target direction. Umbral Dash resets Aatrox's basic attack timer and can be cast during his other abilities without cancelling them and vice versa.","img":"AatroxE.png","cd":"9/8/7/6/5","cost":"0","range":"25000"},"R":{"name":"World Ender","desc":"Active: Aatrox unleashes his true form for 10 seconds, fearing nearby enemy minions and monsters for 3 seconds, during which they are gradually slowed by up to 99% over the duration. He also gains ghosting and bonus movement speed that decays by 10% of the current bonus every 0.25 seconds, lasting until World Ender has ended. Whenever Aatrox scores a champion takedown, he extends the duration by 5 seconds and becomes unleashed again.","img":"AatroxR.png","cd":"120/100/80","cost":"0","range":"25000"}},"Ahri":{"title":"the Nine-Tailed Fox","passive":{"name":"Essence Theft","desc":"Innate: Ahri generates a stack of Essence Fragment whenever she kills a minion or monster. At 9 stacks, she consumes them to heal herself for 35–95 (based on level) (+ 20% AP). Additionally, whenever Ahri scores a champion takedown within 3 seconds of damaging them, she brings their essence to her to consume it to heal herself for 75–165 (based on level) (+ 30% AP).","img":"Ahri_SoulEater2.png"},"Q":{"name":"Orb of Deception","desc":"Active: Ahri sends her orb in the target direction that deals magic damage to enemies it passes through. Upon reaching maximum range, it returns to her to deal the same amount in true damage to enemies it passes through. Enemies can be hit only once per pass.","img":"AhriQ.png","cd":"7","cost":"55/65/75/85/95","range":"970"},"W":{"name":"Fox-Fire","desc":"Active: Ahri gains 40% bonus movement speed that decays over 2 seconds and conjures three flames which orbit her clockwise for up to 2.5 seconds. After 0.25 seconds of the cast, each flame targets a visible enemy based on priority, or after 0.4 seconds, simply targets the closest visible enemy in range. Each flame deals magic damage, with subsequent flames against a target dealing 30% damage.","img":"AhriW.png","cd":"9/8/7/6/5","cost":"30","range":"700"},"E":{"name":"Charm","desc":"Active: Ahri blows forth a kiss in the target direction that deals magic damage to the first enemy hit, knocking them down and charming and slowing them by 65% for a duration.","img":"AhriE.png","cd":"12","cost":"60","range":"975"},"R":{"name":"Spirit Rush","desc":"Active: Ahri dashes to the target location and then fires essence bolts to up to 3 nearby visible enemies, each dealing magic damage. Spirit Rush can be recast twice more within 15 seconds of the activation at no additional cost, with a 1-second static cooldown between casts. Consuming a champion's essence with Essence Theft while Spirit Rush is active extends the recast duration by and up to 10 seconds, and grants an additional recast, storing up to 3 recasts at a time.","img":"AhriR.png","cd":"140/120/100","cost":"100","range":"450"}},"Akali":{"title":"the Rogue Assassin","passive":{"name":"Assassin's Mark","desc":"Innate: When Akali damages an enemy champion with an ability, she creates a ring around them for 4 seconds, refreshing on subsequent damaging abilities against champions. For 2 seconds, she gains 30 / 40 / 50 / 60% (based on level) bonus movement speed while moving away from the center of the ring. Only one ring may be active at a time.","img":"Akali_P.png"},"Q":{"name":"Five Point Strike","desc":"Active: Akali unleashes kunai in a cone in the target direction, dealing magic damage to enemies hit. Targets beyond a certain range are also slowed by 50% for 0.5 seconds.","img":"AkaliQ.png","cd":"1.5","cost":"110/100/90/80/70","range":"550"},"W":{"name":"Twilight Shroud","desc":"Active: Akali restores 100 energy over 0.4 seconds and gains bonus movement speed that decays over 2 seconds. She also detonates a smoke bomb a fixed distance away in the target direction, creating a circular shroud that expands over the next 5 seconds into a ring. The shroud does not permeate terrain, and will expand toward nearby enemy champions. While the shroud is active, Akali's maximum energy is increased by 100.","img":"AkaliW.png","cd":"20/19/18/17/16","cost":"0","range":"350"},"E":{"name":"Shuriken Flip","desc":"Active: Akali flips backward and, after the cast time, throws a shuriken in the target direction that deals magic damage to the first enemy hit. The shuriken marks and reveals the enemy or the last smoke section hit for 3 seconds, during which Shuriken Flip can be recast to consume the mark. Recast: Akali dashes towards the marked target or smoke section. Against enemies she deals magic damage upon arrival.","img":"AkaliE.png","cd":"16/14.5/13/11.5/10","cost":"30","range":"825"},"R":{"name":"Perfect Execution","desc":"Active: Akali dashes 750 units in the direction of the target enemy champion, dealing magic damage to enemies she passes through. If this hits an enemy, she flips over them to continue the dash up to the normal range but for at least another 150 units. Perfect Execution can be recast after a 2.5-second static cooldown within 10 seconds of the first activation.","img":"AkaliR.png","cd":"120/90/60","cost":"0","range":"675"}},"Akshan":{"title":"the Rogue Sentinel","passive":{"name":"Dirty Fighting","desc":"Innate: Whenever Akshan uses a basic attack, he fires an additional shot after a delay that deals 50% AD physical damage, increased to 100% AD against minions. Issuing an attack order on a different target before the additional shot has been launched causes Akshan to fire it at the new target. If the second shot is cancelled instead, he gains 20–75 (based on level) × (1 + 100% bonus attack speed) bonus movement speed decaying over 1 second.","img":"akshan_p.png"},"Q":{"name":"Avengerang","desc":"Active: Akshan throws a boomerang in the target direction that briefly grants sight around its trajectory and deals physical damage to enemies hit, revealing them for 1 second and extending its range each time it hits a target. If this hits an enemy champion, Akshan gains 20% (+ 5% per 100 AP) bonus movement speed that decays over 1 second.","img":"AkshanQ.png","cd":"9/8/7/6/5","cost":"60/65/70/75/80","range":"850"},"W":{"name":"Going Rogue","desc":"Passive: Akshan marks enemy champions that kill allied champions as Scoundrels for 60 seconds. If Akshan scores a takedown against a Scoundrel while alive and within 3 seconds of damaging them, he receives an additional 100 and resurrects all dead allied champions that they have slain after 1 second.","img":"AkshanW.png","cd":"18/14/10/6/2","cost":"40/30/20/10/0","range":"5500"},"E":{"name":"Heroic Swing","desc":"Active: Akshan can activate Heroic Swing three times before the ability goes on cooldown, and can use the third cast only after 0.5 seconds of the second cast. Akshan may input an attack or movement command to use the second and third casts.","img":"AkshanE.png","cd":"18/16.5/15/13.5/12","cost":"70","range":"800"},"R":{"name":"Comeuppance","desc":"Active: Akshan locks onto the target enemy champion and begins channeling for 2.5 seconds, revealing them as well as revealing himself. He gradually stores bullets into his weapon over the duration. Comeuppance will recast after the duration, or can be recast early after 0.5 seconds. Comeuppance is placed on a 5-second cooldown if the channel is cancelled.","img":"AkshanR.png","cd":"100/85/70","cost":"100","range":"2500"}},"Alistar":{"title":"the Minotaur","passive":{"name":"Triumphant Roar","desc":"Innate: Alistar generates a stack of Triumph for each enemy champion he stuns or displaces with his abilities, and each time a nearby enemy minion or non-epic monster dies. He generates 7 stacks if a nearby enemy champion or epic monster dies. At 7 stacks, Alistar consumes them all to heal himself for 5% of his maximum health and nearby allied champions for 7% of his maximum health.","img":"Alistar_E.png"},"Q":{"name":"Pulverize","desc":"Active: Alistar smashes the ground beneath him, dealing magic damage to nearby enemies and stunning and knocking them up simultaneously for 1 second.","img":"Pulverize.png","cd":"14/13/12/11/10","cost":"50/55/60/65/70","range":"365"},"W":{"name":"Headbutt","desc":"Active: Alistar dashes to the target enemy's location. If they are within 400 units upon arrival, he deals them magic damage and knocks them back 700 units over 0.5 seconds while also stunning them for 0.75 seconds.","img":"Headbutt.png","cd":"14/13/12/11/10","cost":"50/55/60/65/70","range":"650"},"E":{"name":"Trample","desc":"Active: Alistar tramples the ground around him every 0.5 seconds over 5 seconds, becoming ghosted and dealing magic damage to nearby enemies. Each time this damages at least one enemy champion, he generates a stack of Trample that lasts for the remaining duration, stacking up to 5 times.","img":"AlistarE.png","cd":"12/11.5/11/10.5/10","cost":"50/55/60/65/70","range":"350"},"R":{"name":"Unbreakable Will","desc":"Active: Alistar cleanses himself of all crowd control. For the next 7 seconds, he reduces incoming damage taken.","img":"FerociousHowl.png","cd":"120/100/80","cost":"100","range":"1"}},"Ambessa":{"title":"Matriarch of War","passive":{"name":"Drakehound's Step","desc":"Innate: During the lockout of Ambessa's abilities, inputting an attack or movement command causes her to dash to or towards the target or location, respectively, after the lockout ends. This dash cannot pass through terrain.Ambessa cannot dash while immobilized or grounded.","img":"Icon_Ambessa_Passive.png"},"Q":{"name":"Cunning Sweep / Sundering Slam","desc":"Active: Ambessa enters a 0.225-second lockout, at the end of which she slashes with her twin drakehounds in a cone in the target direction, dealing physical damage to enemies hit. The damage is doubled against enemies hit by the outer edge. Drakehound's Step's dash may be buffered during the lockout or initiated within 0.275 seconds of the lockout ending, and Ambessa will perform the dash after her slash completes.","img":"AmbessaQ.png","cd":"14/13/12/11/10","cost":"70","range":"650"},"W":{"name":"Repudiation","desc":"Active: Ambessa braces herself for up to 0.5 seconds, during which in the first 0.225 seconds she is unable to act. After Ambessa finishes bracing, she smashes the ground beneath her, dealing physical damage to nearby enemies. Drakehound's Step's dash may be buffered during the lockout or initiated within 0.25 seconds of the lockout ending.","img":"AmbessaW.png","cd":"18/17/16/15/14","cost":"70","range":"325"},"E":{"name":"Lacerate","desc":"Active: Ambessa enters a 0.225-second lockout and spins her twin drakehounds around her to deal physical damage to nearby enemies and slow them by 99% decaying over 1 second. Drakehound's Step's dash may be buffered during the lockout or initiated within 0.275 seconds of the lockout ending; in either case, she will spin a second time at the end of the dash to apply the same effects at no additional cost.","img":"AmbessaE.png","cd":"13/12/11/10/9","cost":"70","range":"325"},"R":{"name":"Public Execution","desc":"Passive: Ambessa gains armor penetration and heals herself for a percentage of the post-mitigation damage she deals to enemies with her active abilities. The healing effectiveness is reduced to 25% against minions and 40% against monsters.","img":"AmbessaR.png","cd":"130/115/100","cost":"0","range":"1250"}},"Amumu":{"title":"the Sad Mummy","passive":{"name":"Cursed Touch","desc":"Innate: Amumu's basic attacks and Curse of the Sad Mummy are empowered to mark enemies with Curse for 3 seconds, refreshing on subsequent applications and Despair's per-tick damage. Cursed targets receive 10% bonus true damage from all incoming pre-mitigation magic damage.","img":"Amumu_Passive.png"},"Q":{"name":"Bandage Toss","desc":"Active: Amumu throws a bandage in the target direction that deals magic damage to the first enemy hit, stunning them for 1 second and pulling him to them, during which they are revealed. Amumu periodically stocks a Bandage Toss charge, up to a maximum of 2. Despair can be cast during the dash.","img":"BandageToss.png","cd":"3","cost":"50","range":"1100"},"W":{"name":"Despair","desc":"Toggle: Amumu cries a continuous pool of tears, dealing magic damage every 0.5 seconds to nearby enemies.","img":"AuraofDespair.png","cd":"1","cost":"8","range":"300"},"E":{"name":"Tantrum","desc":"Passive: Amumu reduces every instance of pre-mitigation physical damage taken, capped at 50% of the damage instance. Active: Amumu releases his anger, dealing magic damage to nearby enemies. Tantrum's current cooldown is reduced by 0.75 seconds whenever Amumu is hit by a basic attack on-hit.","img":"Tantrum.png","cd":"9/8/7/6/5","cost":"35","range":"350"},"R":{"name":"Curse of the Sad Mummy","desc":"Active: Amumu entangles nearby enemies in bandages, dealing magic damage as well as knocking down and stunning them for 1.5 seconds.","img":"CurseoftheSadMummy.png","cd":"150/125/100","cost":"100/150/200","range":"550"}},"Anivia":{"title":"the Cryophoenix","passive":{"name":"Rebirth","desc":"Innate: Periodically, upon taking fatal damage, Anivia enters resurrection for 6 seconds and restores all of her health. While under resurrection, Anivia is unable to act and gains -40–20 (based on level) bonus armor and bonus magic resistance. If Anivia remains alive by the end of the duration, she is revived with her current health.","img":"Anivia_P.png"},"Q":{"name":"Flash Frost","desc":"Active: Anivia launches a chunk of ice in the target direction that deals magic damage to enemies hit and slows them by 20%–40% (based on Glacial Storm's Rank) for 3 seconds. Flash Frost can be recast while the ice is in flight after its cast time, and does so automatically at maximum range. Recast: Anivia shatters the ice, dealing magic damage to nearby enemies and stunning them for a duration, as well as refreshing the slow.","img":"FlashFrost.png","cd":"11/10/9/8/7","cost":"80/85/90/95/100","range":"1075"},"W":{"name":"Crystallize","desc":"Active: Anivia summons a wall of ice at the target location perpendicular to her facing, knocking all units away from it, though not through terrain. The wall lingers as impassable terrain for 5 seconds.","img":"Crystallize.png","cd":"17","cost":"70","range":"1000"},"E":{"name":"Frostbite","desc":"Passive: Enemies hit by Flash Frost or a fully formed Glacial Storm become Chilled for 3 seconds, refreshing on subsequent hits. Active: Anivia blasts a freezing wind at the target enemy that deals magic damage, doubled if they were Chilled.","img":"Frostbite.png","cd":"4","cost":"50","range":"650"},"R":{"name":"Glacial Storm","desc":"Active: Anivia calls forth a driving rain of ice and hail at the target location, dealing magic damage every 0.5 seconds to enemies within and slowing them for 1 second, refreshing every 0.5 seconds while they remain inside.","img":"GlacialStorm.png","cd":"4/3/2","cost":"60","range":"750"}},"Annie":{"title":"the Dark Child","passive":{"name":"Pyromania","desc":"Innate - Pyromania: Annie generates a stack of Pyromania whenever she hits an enemy with Disintegrate or casts her other abilities, stacking up to 4 times, at which she gains Energized. Energized: Annie empowers her next cast of Disintegrate, Incinerate, or Summon: Tibbers to consume all Pyromania stacks to stun enemies hit for 1.25 / 1.5 / 1.75 (based on level) seconds.","img":"Annie_Passive.png"},"Q":{"name":"Disintegrate","desc":"Active: Annie hurls a fireball at the target enemy that deals magic damage. If this kills the target, Disintegrate's cooldown is reduced by 50% and its mana cost is refunded.","img":"AnnieQ.png","cd":"4","cost":"60/65/70/75/80","range":"625"},"W":{"name":"Incinerate","desc":"Active: Annie releases fire in a cone in the target direction, dealing magic damage to enemies hit.","img":"AnnieW.png","cd":"7","cost":"70/75/80/85/90","range":"600"},"E":{"name":"Molten Shield","desc":"Active: Annie grants herself or the target allied champion and Tibbers a shield for 3 seconds and 20%–50% (based on level) bonus movement speed that decays over 1.5 seconds. While Molten Shield is active, enemies that deal damage to it take magic damage. This may only occur once per enemy per cast for each active Molten Shield.","img":"AnnieE.png","cd":"10","cost":"60/65/70/75/80","range":"800"},"R":{"name":"Summon: Tibbers","desc":"Passive: Annie gains magic penetration. Active: Annie summons Tibbers to the target location in a burst of flame, dealing magic damage to enemies near him. Summon: Tibbers can be recast at any time while Tibbers is alive. Tibbers then remains on the field as a controllable pet for up to 45 seconds. Recast: Annie directs Tibbers to the target location.","img":"AnnieR.png","cd":"130/115/100","cost":"100","range":"600"}},"Aphelios":{"title":"the Weapon of the Faithful","passive":{"name":"The Hitman and the Seer","desc":"Innate: Aphelios has access to an arsenal of 5 Moonstone Weapons, created by his sister Alune. He equips two weapons at any one time, one as his main weapon and one as his off-hand. Each weapon has a unique basic attack and passive effect.","img":"ApheliosP.png"},"Q":{"name":"Weapon Abilites","desc":"The active effect of Aphelios' varies based on his current main weapon. The individual actives do not share a cooldown.","img":"ApheliosQ_ClientTooltipWrapper.png","cd":"9","cost":"60","range":"1450"},"W":{"name":"Phase","desc":"Active: Aphelios switches between his main weapon and off-hand weapon over 0.25 seconds.","img":"ApheliosW.png","cd":"0.8","cost":"0","range":"250"},"E":{"name":"Weapon Queue System","desc":"The icon of this ability reflects the next weapon that is in reserve. Active: Aphelios receives a text prompt of the weapon Alune will create next.","img":"ApheliosE_ClientTooltipWrapper.png","cd":"0","cost":"0","range":"1000"},"R":{"name":"Moonlight Vigil","desc":"Active: Aphelios casts forth a lunar spotlight in the target direction that briefly grants sight of the area along its path and stops upon illuminating an enemy champion. Alune smites the area centered on the illuminated target, dealing 125 / 175 / 225 (based on level) (+ 20% bonus AD) (+ 100% AP) physical damage to enemy champions struck and locking-on to each target hit, as well as granting sight of the area for 2 seconds.","img":"ApheliosR.png","cd":"120/110/100","cost":"100","range":"1300"}},"Ashe":{"title":"the Frost Archer","passive":{"name":"Frost Shot","desc":"Innate: Ashe's basic attacks deal bonus physical damage equal to (75% + 40%) critical strike chance. Critical strikes do not deal any additional damage. Innate - Frost Shot: Ashe's basic attacks and ability hits apply Frost to enemies for 2 seconds, which slows them by 20%–30% (based on level) for the duration.","img":"Ashe_P.png"},"Q":{"name":"Ranger's Focus","desc":"Passive: While Ranger's Focus is inactive, Ashe's basic attacks on-attack generate a stack of Focus for 4 seconds, which refreshes on subsequent attacks and stacks up to 4 times. Stacks expire by one every 1 second. Active: Ashe gains bonus attack speed for 6 seconds and empowers her basic attacks to fire a flurry of five arrows.","img":"AsheQ.png","cd":"0","cost":"30","range":"400"},"W":{"name":"Volley","desc":"Active: Ashe shoots a volley of arrows in a cone in the target direction, each dealing physical damage to the first enemy hit, and applying Critical Slow to enemy champions hit. Enemies can intercept multiple arrows but do not take damage from any beyond the first.","img":"Volley.png","cd":"18/14.5/11/7.5/4","cost":"75/70/65/60/55","range":"1200"},"E":{"name":"Hawkshot","desc":"Active: Ashe sends a hawk spirit toward the target location, granting sight of the area along its path[ repeatedly for 0.5 seconds after every 100 units traveled ][ for effectively up-to 1.8 seconds at any location ]and at its destination for 5 seconds. Ashe periodically stocks a Hawkshot charge, up to a maximum of 2.","img":"AsheSpiritOfTheHawk.png","cd":"5","cost":"0","range":"25000"},"R":{"name":"Enchanted Crystal Arrow","desc":"Active: Ashe fires a massive arrow of ice in the target direction, granting sight of the area it flies through each for 1 second. The arrow shatters upon hitting an enemy champion, dealing them magic damage, stunning them for 1–3.5 (based on distance traveled) seconds, and granting sight of the area around them for 1 second. Enemies surrounding the primary target are dealt the same damage and afflicted with Frost Shot.","img":"EnchantedCrystalArrow.png","cd":"100/80/60","cost":"100","range":"25000"}},"AurelionSol":{"title":"The Star Forger","passive":{"name":"Cosmic Creator","desc":"Innate: Aurelion Sol's damaging abilities against enemies generate him permanent stacks of Stardust, which gradually augments his abilities. Breath of Light: Bursts deal bonus magic damage based on the target's maximum health. Astral Flight: Range is increased equal to 62.5% Stardust. Singularity: Outer and inner radius increased equal to 15% Stardust, and the execution threshold is increased. Falling Star/ The Skies Descend: Impact radius increased equal to 15% Stardust.","img":"AurelionSolP.png"},"Q":{"name":"Breath of Light","desc":"Active: Aurelion Sol charges for up to 3.25 seconds to exhale a beam of starfire, during which he can steer the beam in the target direction. The beam collides with the first enemy hit to reveal them and deal magic damage every 0.125 seconds, reduced to 50% for other surrounding enemies hit by the beam.","img":"AurelionSolQ.png","cd":"3","cost":"30/35/40/45/50","range":"750"},"W":{"name":"Astral Flight","desc":"Active: Aurelion Sol dashes in the target direction and resets Breath of Light's cooldown. During flight, he has unobstructed vision and Breath of Light has no cooldown and maximum channel duration and its flat damage is increased, but Astral Flight's dash speed is reduced by 50% during its channel. Aurelion Sol will be knocked down by any immobilizing crowd control during the dash.","img":"AurelionSolW.png","cd":"22/20/18/16/14","cost":"50/55/60/65/70","range":"1500"},"E":{"name":"Singularity","desc":"Active: Aurelion Sol conjures a black hole at the target location after a 0.5-second delay that lasts for 5 seconds, granting sight of the area and dealing magic damage every 0.25 seconds to enemies within.","img":"AurelionSolE.png","cd":"12","cost":"90","range":"750"},"R":{"name":"Falling Star / The Skies Descend","desc":"Active: Aurelion Sol calls down a star that strikes the target location after 1.25 seconds, dealing magic damage to enemies hit and stunning them for 1 second. This generates 5 Stardust for each enemy champion hit. Once Falling Star has been learned, gathering 75 Stardust causes the next cast of Falling Star to transform into The Skies Descend, empowering the impact with new effects.","img":"AurelionSolR.png","cd":"120/110/100","cost":"100","range":"1250"}},"Aurora":{"title":"the Witch Between Worlds","passive":{"name":"Spirit Abjuration","desc":"Innate: Aurora's damaging basic attacks and abilities apply a stack of Spirit Abjuration to enemies for 4 seconds, refreshing on subsequent applications and stacking up to 3 times. The third stack against a target consumes them all to deal bonus magic damage equal to 2.5% (+ 2% per 100 AP) of the target's maximum health, capped at 100–180 (based on level) against monsters.","img":"AuroraPassive.png"},"Q":{"name":"Twofold Hex","desc":"Active: Aurora fires a bolt of energy in the target direction that deals magic damage to enemies hit and marks them with a curse for 3.5 seconds. Twofold Hex can be recast after 0.1 seconds while at least one target is marked, and does so automatically at the end of the mark's duration.","img":"AuroraQ.png","cd":"9/8.5/8/7.5/7","cost":"60","range":"900"},"W":{"name":"Across the Veil","desc":"Active: Aurora hops in the target direction inside a portal to the Spirit Realm. Upon completing the dash, she becomes invisible for a duration and gains Realm Hopper for 4 seconds. Realm Hopper: Aurora becomes ghosted and gains bonus movement speed for the duration. Scoring a takedown against an enemy champion within 3 seconds of damaging them will reset Across the Veil's cooldown.","img":"AuroraW.png","cd":"22/21/20/19/18","cost":"80","range":"700"},"E":{"name":"The Weirding","desc":"Active: Aurora blasts energy in a line in the target direction and recoils 250 units in the opposite direction. The blast deals magic damage to enemies hit and slows them by 80% for 1 second decaying after the first 0.15 seconds.","img":"AuroraE.png","cd":"15/14/13/12/11","cost":"80","range":"825"},"R":{"name":"Between Worlds","desc":"Active: Aurora leaps in the target direction with displacement immunity over 0.4 seconds. She then gains Realm Hopper for 3.5 seconds and unleashes a shockwave from 425 units in front of her, expanding over 0.75 seconds to deal magic damage to enemies hit and slow them by 30% for 2 seconds.","img":"AuroraR.png","cd":"140/120/100","cost":"100","range":"250"}},"Azir":{"title":"the Emperor of the Sands","passive":{"name":"Shurima's Legacy","desc":"Innate: Whenever a turret outside the enemy team's base is destroyed, a marker is placed above its ruins which can be targeted by Azir. Innate - Disc of the Sun: Azir can select a marker to construct the Sun Disc above the ruins after a 0.5-second cast time. The Sun Disc will activate after being assembled over 5 seconds.","img":"Azir_Passive.png"},"Q":{"name":"Conquering Sands","desc":"Active: Azir orders all Sand Soldiers to dash toward the target location, dealing magic damage to all enemies they pass through as well as those in front of them upon arrival, and slowing them by 25% for 1 second. Enemies hit by subsequent soldiers take no additional damage and are instead slowed by an additional 25% per soldier. Conquering Sands will cast at max range if cast beyond that.","img":"AzirQWrapper.png","cd":"14/12/10/8/6","cost":"70/80/90/100/110","range":"740"},"W":{"name":"Arise!","desc":"Active: Azir summons a Sand Soldier at the target location that is untargetable, lasts 10 seconds, and grants sight of its surroundings. The Sand Soldier expires twice as fast while within range of an enemy turret, and does so instantly if Azir is too far away.Azir periodically stocks a Sand Soldier, up to a maximum of 2.","img":"AzirW.png","cd":"1.5","cost":"40/35/30/25/20","range":"525"},"E":{"name":"Shifting Sands","desc":"Active: Azir grants himself a shield for 1.5 seconds and dashes to the target Sand Soldier, dealing magic damage to enemies within his path. If Azir dashes into an enemy champion, he stops and gains a charge of Arise!. Azir can cast of any of his abilities during the dash.","img":"AzirEWrapper.png","cd":"22/20.5/19/17.5/16","cost":"60","range":"1100"},"R":{"name":"Emperor's Divide","desc":"Active: Azir calls forth a phalanx of soldiers from 175 units behind him, catching enemies from up to 325 units behind him and charging forward 575 units in the target direction. Enemies impacted by the charge are dealt magic damage and knocked away over 1 second to a line 650 units in front of Azir.","img":"AzirR.png","cd":"120/105/90","cost":"100","range":"250"}},"Bard":{"title":"the Wandering Caretaker","passive":{"name":"Traveler's Call","desc":"Innate - Ancient Chimes: Bard's presence causes sacred Chimes to appear at random locations on the map, lingering for up to 10 minutes. Collecting a Chime restores 12% maximum mana and grants Bard 20 + (1 per minute after 5 minutes) experience, as well as 24% bonus movement speed out of combat for 20 seconds, which stacks up to 10 times. Each Chime collected beyond the first instead grants an additional 14% bonus movement speed, up to a total of 150% bonus movement speed. Bard empowers his Meeps each time he collects 5 Chimes.","img":"Bard_Passive.png"},"Q":{"name":"Cosmic Binding","desc":"Active: Bard fires an energy bolt in the target direction that deals magic damage to the first enemy hit and slows them by 60% for a duration. After Cosmic Binding hits an enemy, the bolt continues behind them for 300 units. If the bolt hits terrain or a second enemy, it stuns both targets for the same duration, dealing the same damage to the secondary target.","img":"BardQ.png","cd":"11/10/9/8/7","cost":"60","range":"25000"},"W":{"name":"Caretaker's Shrine","desc":"Active: Bard conjures a shrine at the target location that gathers power over 5 seconds and grants sight of its surroundings for 1.8 seconds. Shrines last until they are consumed by champions moving over them. Up to 3 shrines may be active at a time. If the champion was an ally or Bard himself, they are healed for an amount based on the shrine's power and gain stacking bonus movement speed for each Shrine that decays over 1.5 seconds.","img":"BardW.png","cd":"0","cost":"70","range":"800"},"E":{"name":"Magical Journey","desc":"Active: Bard opens a one-way magical corridor through a piece of terrain in the target direction for 10 seconds. A champion can pass through the corridor by selecting it, becoming revealed during the travel. Bard and allies travel through the portal at 33% increased speed. A nearby valid piece of terrain is required to cast this ability. Magical Journey cannot be taken while immobilized or grounded.","img":"BardE.png","cd":"22/20.5/19/17.5/16","cost":"30","range":"900"},"R":{"name":"Tempered Fate","desc":"Active: Bard sends magical energy arcing to the target location, granting sight of the area during travel. Upon impact, it puts all units within into stasis for 2.5 seconds, as well as stunning all enemy champions, minions, and turrets struck for the same duration. Enemies hit are revealed for the duration. Epic monsters and turrets are affected by Tempered Fate despite being immune to crowd control.","img":"BardR.png","cd":"110/95/80","cost":"100","range":"3400"}},"Belveth":{"title":"the Empress of the Void","passive":{"name":"Death in Lavender ","desc":"Innate: Bel'Veth attacks 36% faster than the median champion and her attack speed cap is modified to 9999.0, but all sources of damage (including on-hit damage) dealt by her basic attacks are reduced to 75%. Her attack speed does not increase through growth (per level).","img":"Belveth_Passive.png"},"Q":{"name":"Void Surge","desc":"Active: Bel'Veth dashes in the designated direction, though not through terrain, dealing physical damage to enemies she passes through. Against the first target, Void Surge can critically strike for (175% + 40%) damage and applies on-hit effects, with on-hit damage reduced to 75% effectiveness, and life steal at 100% effectiveness. Void Surge deals bonus physical damage to monsters and modified damage against minions.","img":"BelvethQ.png","cd":"4/3.25/2.5/1.75/1","cost":"0","range":"450"},"W":{"name":"Above and Below","desc":"Active: Bel'Veth slams her tail down in the target direction that deals magic damage to enemies hit, knocks them up for 0.75 seconds, and slows them by 50% for a duration. If this hits an enemy champion, it resets Void Surge's dash cooldown of the target direction.","img":"BelvethW.png","cd":"12/11/10/9/8","cost":"0","range":"715"},"E":{"name":"Royal Maelstrom","desc":"Active: Bel'Veth enters a defensive stance for 1.5 seconds, during which she is unable to move, but gains damage reduction and 20% (+ 100% life steal) life steal.","img":"BelvethE.png","cd":"24/21/18/15/12","cost":"0","range":"500"},"R":{"name":"Endless Banquet","desc":"Passive: Bel'Veth's basic attacks on-hit apply a mark to the target for 5 seconds, refreshing on subsequent hits. Every second attack on-hit against the marked target deals bonus true damage and generates a stack of Endless Banquet that increases this damage by the same value. This effect stacks infinitely, but is capped at 5 stacks against epic monsters. The mark and stacks expire upon attacking a new target.","img":"BelvethR.png","cd":"1","cost":"0","range":"450"}},"Blitzcrank":{"title":"the Great Steam Golem","passive":{"name":"Mana Barrier","desc":"Innate: Periodically, when damaged to 30% maximum health, Blitzcrank generates a shield equal to 35% of maximum mana, lasting for up to 10 seconds.","img":"Blitzcrank_ManaBarrier.png"},"Q":{"name":"Rocket Grab","desc":"Active: Blitzcrank fires their right hand in the target direction that catches the first enemy hit, dealing them magic damage, stunning them for 0.65 seconds, and pulling them towards Blitzcrank, during which they are revealed. Blitzcrank is unable to move or attack while Rocket Grab is in flight.","img":"RocketGrab.png","cd":"20/19/18/17/16","cost":"100","range":"1079"},"W":{"name":"Overdrive","desc":"Active: Blitzcrank shifts into overdrive, gaining bonus attack speed for 5 seconds and bonus movement speed that decays to 10% over the first 2.9 seconds. When Overdrive ends, Blitzcrank is slowed by 30% for 1.5 seconds.","img":"Overdrive.png","cd":"15","cost":"75","range":"1"},"E":{"name":"Power Fist","desc":"Active: Blitzcrank empowers their next basic attack within 5 seconds to have an uncancellable windup, deal 100% AD (+ 25% AP) bonus physical damage and knock up the target for 1 second. This damage is affected by critical strike modifiers. Power Fist resets Blitzcrank's basic attack timer.","img":"PowerFist.png","cd":"7/6.5/6/5.5/5","cost":"25","range":"300"},"R":{"name":"Static Field","desc":"Passive: While Static Field is not on cooldown, Blitzcrank's basic attacks apply a stack to the target on-hit. After every 1 second, one stack is consumed to deal them magic damage. Active: Blitzcrank detonates a static field that destroys the damage-mitigating shields of all nearby enemies, excluding the shields of monsters, and then deals them magic damage and silences them for 0.5 seconds.","img":"StaticField.png","cd":"60/40/20","cost":"100","range":"600"}},"Brand":{"title":"the Burning Vengeance","passive":{"name":"Blaze","desc":"Innate: Brand's abilities apply a stack of Ablaze to enemies hit for 4 seconds, stacking up to 3 times and refreshing the duration of all stacks with each application. Subsequent abilities used against a target with Ablaze are empowered. Killing an enemy afflicted with Ablaze or any enemy with an ability restores 20–40 (based on level) mana.","img":"BrandP.png"},"Q":{"name":"Sear","desc":"Active: Brand launches a fireball in the target direction that deals magic damage to the first enemy hit. Ablaze Bonus: The target is stunned for 1.5 seconds.","img":"BrandQ.png","cd":"8/7.5/7/6.5/6","cost":"70","range":"1050"},"W":{"name":"Pillar of Flame","desc":"Active: After a 0.627 seconds delay, Brand erupts a pillar of flame at the target location that deals magic damage to enemies hit. Ablaze Bonus: The target takes 25% increased damage.","img":"BrandW.png","cd":"10/9.5/9/8.5/8","cost":"60/70/80/90/100","range":"900"},"E":{"name":"Conflagration","desc":"Active: Brand sets the target enemy aflame, which creates a blast that deals magic damage to them and causes the flame to spread from the target to nearby enemies, dealing them the same damage. Ablaze Bonus: Conflagration's spread range is doubled.","img":"BrandE.png","cd":"13/12/11/10/9","cost":"90","range":"625"},"R":{"name":"Pyroclasm","desc":"Active: Brand launches a fireball at the target enemy that bounces between nearby enemies and Brand up to four times, dealing magic damage to enemies each time. Pyroclasm prioritizes ablazed enemy champions, then other enemy champions, then any valid bounce target, then Brand. Ablaze Bonus: The target is slowed for 0.25 seconds. This can affect the same enemy more than once.","img":"BrandR.png","cd":"100/90/80","cost":"100","range":"750"}},"Braum":{"title":"the Heart of the Freljord","passive":{"name":"Concussive Blows","desc":"Innate: Braum's basic attacks and Winter's Bite each apply a stack of Concussive Blows to their target for 4 seconds, refreshing on subsequent applications and stacking up to 4 times. Once the first stack has been applied, any allied champion's basic attack applies an additional stack to the target on-hit.","img":"Braum_Passive.png"},"Q":{"name":"Winter's Bite","desc":"Active: Braum propels ice from his shield in the target direction, dealing magic damage to the first enemy hit and slowing them by 70% decaying over 2 seconds.","img":"BraumQ.png","cd":"8/7.5/7/6.5/6","cost":"45/50/55/60/65","range":"1000"},"W":{"name":"Stand Behind Me","desc":"Active: Braum dashes to put himself between the target ally and the closest visible enemy champion within 1500 units, and upon arrival grants himself and the ally bonus armor and bonus magic resistance for 3 seconds. Stand Behind Me can be self cast to instantly grant Braum the bonus resistances. Unbreakable can be cast during the dash.","img":"BraumW.png","cd":"12/11/10/9/8","cost":"40","range":"650"},"E":{"name":"Unbreakable","desc":"Active: Braum sets his shield in the target direction for a duration, creating a barrier in front of him that intercepts all incoming hostile projectiles and reduces the damage Braum takes through it. The first instance of damage dealt by a champion from this direction is reduced by 100%. Unbreakable does not affect turrets. While his shield is raised, Braum also gains 10% bonus movement speed and ghosting.","img":"BraumE.png","cd":"16/14/12/10/8","cost":"30/35/40/45/50","range":"25000"},"R":{"name":"Glacial Fissure","desc":"Active: Braum leaps into the air and slams his shield into the ground, creating a fissure from the impact that travels forth in the target direction, dealing magic damage to enemies within its path as well as those around Braum. The first target hit is knocked up for at least 0.6 seconds, increased if they are further away from Braum. All other enemies hit are knocked up for 0.6 seconds.","img":"BraumRWrapper.png","cd":"130/115/100","cost":"100","range":"1250"}},"Briar":{"title":"the Restrained Hunger","passive":{"name":"Crimson Curse","desc":"Innate: Briar's basic attacks and abilities inflict a bleed against enemies for 5 seconds, refreshing on subsequent applications, stacking up to 9 times and dealing 25% damage for stacks beyond the first. The bleed deals[ 10–50 (based on level) (+ 50% bonus AD) total physical damage over the duration, increased by 2.5–12.5 (based on level) (+ 12.5% bonus AD) for each subsequent stack and up to a maximum of 30–150 (based on level) (+ 150% bonus AD). ][ 1–5 (based on level) (+ 5% bonus AD) physical damage every 0.5 seconds, increased by 0.25–1.25 (based on level) (+ 1.25% bonus AD) for each subsequent stack and up to a maximum of 3–15 (based on level) (+ 15% bonus AD) per tick. ]Briar heals herself equal to 25% of the pre-mitigation damage dealt. If a target dies while bleeding, she will heal herself equal to 125% of the remaining bleed damage.","img":"BriarP.png"},"Q":{"name":"Head Rush","desc":"Active: Briar leaps to the target unit. If the target is an enemy, she deals magic damage, applies on-hit effects, triggers on-attack effects, stuns them for 0.85 seconds, and reduces their armor and magic resistance for 5 seconds. Head Rush resets Briar's basic attack timer.","img":"BriarQ.png","cd":"13/12/11/10/9","cost":"0","range":"475"},"W":{"name":"Blood Frenzy / Snack Attack","desc":"Active: Briar dashes to the target location. If there is a nearby enemy upon her arrival, she gains Blood Frenzy for 5 seconds, during which she can cast Snack Attack.","img":"BriarW.png","cd":"14/13/12/11/10","cost":"0","range":"350"},"E":{"name":"Chilling Scream","desc":"Active: Briar prepares to unleash a scream in the target direction, charging for up to 1 second, during which she increases Chilling Scream's damage and range, and gains 35% damage reduction and heals herself every 0.25 seconds. Chilling Scream can be recast within the duration, and does so automatically afterwards. Chilling Scream's charge cannot be interrupted by crowd control.","img":"BriarE.png","cd":"16","cost":"0","range":"400"},"R":{"name":"Certain Death","desc":"Active: Briar kicks her pillory's hemolith in the target direction, briefly granting sight of its surroundings as it travels and marking the first enemy champion hit as her prey. The mark's application disrupts the target's ongoing channels. While the target is marked, they are revealed.","img":"BriarR.png","cd":"120/100/80","cost":"0","range":"12000"}},"Caitlyn":{"title":"the Sheriff of Piltover","passive":{"name":"Headshot","desc":"Innate: Caitlyn's basic attacks generate a stack of Count on-attack, doubled if she is within brush. At 5 stacks, or 4 while in brush, her next basic attack consumes all stacks on-attack to become a Headshot.","img":"Caitlyn_Headshot.png"},"Q":{"name":"Piltover Peacemaker","desc":"Active: Caitlyn fires a piercing shot in the target direction that deals physical damage to the first enemy it passes through, after which it expands in width but deals only 60% damage to enemies it hits thereafter. Enemies revealed by Yordle Snap Trap always take full damage from Piltover Peacemaker.","img":"CaitlynQ.png","cd":"10/9/8/7/6","cost":"55/60/65/70/75","range":"1250"},"W":{"name":"Yordle Snap Trap","desc":"Active: Caitlyn sets a visible trap at the target location that is untargetable and arms after 1 second, lasting for a duration. The trap grants sight of the area for 1 second after being placed. Caitlyn periodically stocks a Yordle Snap Trap charge, up to a maximum amount. Deploying traps beyond the maximum destroys the oldest one.","img":"CaitlynW.png","cd":"0.5","cost":"20","range":"800"},"E":{"name":"90 Caliber Net","desc":"Active: Caitlyn fires a net in the target direction and recoils 390 units in the opposite direction. The net deals magic damage to the first enemy hit and slows them by 50% for 1 second. Caitlyn will not dash backwards if she is immobilized or grounded during the cast time. She can cast any of her abilities during the dash.","img":"CaitlynE.png","cd":"16/14/12/10/8","cost":"75","range":"750"},"R":{"name":"Ace in the Hole","desc":"Active: Caitlyn locks onto the target enemy champion and channels for 1 second, revealing them as well as revealing herself. Ace in the Hole is placed on a 5-second cooldown if canceled. Once Caitlyn completes the channel, she fires a homing bullet toward the target that deals physical damage to the first enemy champion it hits, increased by 0%–50% (based on critical strike chance).","img":"CaitlynR.png","cd":"90","cost":"100","range":"3500"}},"Camille":{"title":"the Steel Shadow","passive":{"name":"Adaptive Defenses","desc":"Innate: Periodically, Camille's next basic attack on-hit against an enemy champion grants her a shield equal to 20% of her maximum health, lasting for 2 seconds and absorbing damage from either exclusively physical damage or magic damage, based on which type the target has previously dealt most of against champions as well as on Camille's current armor and magic resistance.","img":"Camille_Passive.png"},"Q":{"name":"Precision Protocol","desc":"Active: Camille empowers her next basic attack within 4 seconds to have an uncancellable windup, gain 50 bonus range, deal bonus physical damage and grant her bonus movement speed for 1 second. After 0.25 seconds, Precision Protocol can then be recast within the next 3.5 seconds at no additional cost.","img":"CamilleQ.png","cd":"9/8/7/6/5","cost":"25","range":"325"},"W":{"name":"Tactical Sweep","desc":"Active: Camille sweeps her leg in a cone in the target direction over 1.1 seconds, during which she is ghosted and unable to declare basic attacks. Afterwards, she deals physical damage to all enemies within.","img":"CamilleW.png","cd":"12/11.5/11/10.5/10","cost":"50/55/60/65/70","range":"610"},"E":{"name":"Hookshot","desc":"Active: Camille fires a grapple in the target direction. If the grapple collides with terrain, Camille will dash toward and attach to the terrain for 0.75 seconds, during which she gains the ability to cast Wall Dive. Camille will be knocked down by any immobilizing or polymorphing crowd control during the dash.","img":"CamilleE.png","cd":"16/15/14/13/12","cost":"70","range":"800"},"R":{"name":"The Hextech Ultimatum","desc":"Active: Camille becomes untargetable and leaps with displacement immunity towards the target enemy champion over 0.5 seconds, revealing them for the duration and disrupting their ongoing channels. Upon landing on the target, she becomes targetable again and creates a hexagonal zone around her current location for a duration, knocking away all other nearby enemies on impact, though not through terrain.","img":"CamilleR.png","cd":"140/115/90","cost":"100","range":"475"}},"Cassiopeia":{"title":"the Serpent's Embrace","passive":{"name":"Serpentine Grace","desc":"Innate: Cassiopeia gains 4–72 (based on level) bonus movement speed, but she cannot purchase Boots items. Cassiopeia gains an additional 1–18 (based on level) bonus movement speed if her team obtains the Blessing of Noxus, for a total bonus of 5–90 (based on level).","img":"Cassiopeia_Passive.png"},"Q":{"name":"Noxious Blast","desc":"Active: Cassiopeia creates a blast at the target location that explodes after a 0.4-second delay. Enemies within the blast are poisoned for 3 seconds, taking magic damage every 0.429 seconds over the duration. If Noxious Blast hits an enemy champion, Cassiopeia gains bonus movement speed that decays over 3 seconds.","img":"CassiopeiaQ.png","cd":"3.5","cost":"50/55/60/65/70","range":"850"},"W":{"name":"Miasma","desc":"Active: Cassiopeia spews forth 8 bolts of venom in an arc at the target location, creating toxic clouds at the area for 5 seconds. Enemies within the clouds are poisoned to take magic damage every 0.263 seconds and become grounded and slowed by an amount that decays over the area's duration. Miasma will cast at max range if cast beyond that.","img":"CassiopeiaW.png","cd":"24/22/20/18/16","cost":"70/75/80/85/90","range":"700"},"E":{"name":"Twin Fang","desc":"Active: Cassiopeia launches her fangs at the target enemy that deal 52–120 (based on level) (+ 10% AP) magic damage. If this kills the target, Twin Fang's mana cost is refunded. Against a poisoned target, Twin Fang deals bonus magic damage and heals Cassiopeia. The heal is reduced by 75% against minions and small and medium monsters.","img":"CassiopeiaE.png","cd":"0.75","cost":"40","range":"700"},"R":{"name":"Petrifying Gaze","desc":"Active: Cassiopeia blasts enemies in a cone in the target direction, dealing magic damage to enemies struck within and slowing them by 40% for 2 seconds. Enemies with their facing direction towards her are instead stunned for the same duration.","img":"CassiopeiaR.png","cd":"120/100/80","cost":"100","range":"825"}},"Chogath":{"title":"the Terror of the Void","passive":{"name":"Carnivore","desc":"Innate: Whenever Cho'Gath kills an enemy, it heals for 18–52 (based on level) and restores 4.72–9.48 (based on level) mana.","img":"GreenTerror_TailSpike.png"},"Q":{"name":"Rupture","desc":"Active: Cho'Gath ruptures the target location after a 0.627 seconds delay, granting sight of the area before dealing magic damage to enemies within and knocking them up for 1 second, and afterwards slowing them by 60% for 1.5 seconds.","img":"Rupture.png","cd":"6","cost":"50","range":"950"},"W":{"name":"Feral Scream","desc":"Active: Cho'Gath roars in a cone in the target direction, dealing magic damage to enemies hit. Enemy champions and Rift Scuttlers hit are also silenced for a duration.","img":"FeralScream.png","cd":"11/10.5/10/9.5/9","cost":"70/75/80/85/90","range":"300"},"E":{"name":"Vorpal Spikes","desc":"Active: Cho'Gath empowers its next 3 basic attacks within 6 seconds to gain 50 bonus range and launch a blast of spikes on-attack in the target's direction. Enemies struck are dealt magic damage and slowed by an amount that decays over 1.5 seconds. The damage based on the target's health ratio is capped at 200 against monsters.","img":"VorpalSpikes.png","cd":"8/7/6/5/4","cost":"30","range":"40"},"R":{"name":"Feast","desc":"Active: Cho'Gath attempts to eat the target enemy, dealing them true damage. Against non-champions, the base damage is modified. If the target is killed, Cho'Gath gains a stack of Feast. Only 6 stacks can be gained from non-epic monsters or minions.","img":"Feast.png","cd":"80/70/60","cost":"100","range":"175"}},"Corki":{"title":"the Daring Bombardier","passive":{"name":"Hextech Munitions","desc":"Innate: Corki's basic attacks deal bonus true damage equal to 20% AD. This damage is affected by critical strike modifiers.","img":"Corki_RapidReload.png"},"Q":{"name":"Phosphorus Bomb","desc":"Active: Corki launches a bomb at the target location that explodes upon impact, dealing magic damage to enemies hit. The bomb also grants sight of the area for 6 seconds and reveals enemy champions hit for the same duration.","img":"PhosphorusBomb.png","cd":"9/8.5/8/7.5/7","cost":"60/65/70/75/80","range":"825"},"W":{"name":"Valkyrie","desc":"Active: Corki dashes to the target location and drops bombs that leave up to 3 blazing patches along his path, depending on the distance traveled. Each patch lasts 2.5 seconds. Enemies within the patches are dealt magic damage every 0.5 seconds, lingering for 1 second. Gatling Gun can be cast during the dash. Valkyrie will cast at max range if cast beyond that.","img":"CarpetBomb.png","cd":"20/18/16/14/12","cost":"80/85/90/95/100","range":"600"},"E":{"name":"Gatling Gun","desc":"Active: Corki sprays bullets in a cone toward his facing direction for 4 seconds, dealing physical damage every 0.25 seconds to all enemies hit and applying a stack to them at the same tick rate for 2 seconds, refreshing with subsequent hits and stacking up to 4 times. Each stack reduces the target's armor and magic resistance.","img":"GGun.png","cd":"12","cost":"50/55/60/65/70","range":"600"},"R":{"name":"Missile Barrage","desc":"Passive: Basic attacks on-hit against champions reduce Missile Barrage's remaining recharge time by 2–4 (based on critical strike chance) seconds. Active: Corki fires a missile in the target direction that explodes upon the first enemy hit, dealing physical damage to enemies within the area.","img":"MissileBarrage.png","cd":"2","cost":"35","range":"1225"}},"Darius":{"title":"the Hand of Noxus","passive":{"name":"Hemorrhage","desc":"Innate: Darius' damaging basic attacks and abilities apply a stack of Hemorrhage to enemies for 5 seconds, refreshing on subsequent applications and stacking up to 5 times.","img":"Darius_Icon_Hemorrhage.png"},"Q":{"name":"Decimate","desc":"Active: Darius becomes ghosted for 1 second and hefts his axe for 0.75 seconds, afterward swinging it around himself to deal physical damage to nearby enemies. Enemies within the inner radius take 35% damage.","img":"DariusCleave.png","cd":"9/8/7/6/5","cost":"25/30/35/40/45","range":"1"},"W":{"name":"Crippling Strike","desc":"Active: Darius empowers his next basic attack within 4 seconds to have an uncancellable windup, gain 25 bonus range, deal bonus physical damage and slow the target by 90% for 1 second. This damage is affected by critical strike modifiers. If this attack kills the target, half of Crippling Strike's cooldown is reduced and its mana cost is refunded. Crippling Strike resets Darius' basic attack timer.","img":"DariusNoxianTacticsONH.png","cd":"5","cost":"40","range":"300"},"E":{"name":"Apprehend","desc":"Passive: Darius gains armor penetration. Active: Darius sweeps his axe in a cone in the target direction, granting sight of the area for 1 second while pulling enemies hit towards him. Upon arrival, they rebound 150 units off of him, remaining airborne and becoming slowed by 40% for 1 second. Darius is unable to move or cast Decimate or Noxian Guillotine for 0.4 seconds after Apprehend's cast time.","img":"DariusAxeGrabCone.png","cd":"26/23.5/21/18.5/16","cost":"70/60/50/40/30","range":"535"},"R":{"name":"Noxian Guillotine","desc":"Active: Darius attempts to execute the target enemy champion, leaping towards them to deal true damage, increased by 0%–100% (based on target's Hemorrhage stacks), and granting sight of the area around them for 2.5 seconds from the start of the cast time.","img":"DariusExecute.png","cd":"120/100/80","cost":"100/100/0","range":"460"}},"Diana":{"title":"Scorn of the Moon","passive":{"name":"Moonsilver Blade","desc":"Innate: Diana gains 15%–35% (based on level) bonus attack speed. After casting an ability, this bonus is tripled to 45%–105% (based on level) for 5 seconds.","img":"Diana_Passive_LunarBlade.png"},"Q":{"name":"Crescent Strike","desc":"Active: Diana unleashes a bolt of lunar energy that travels in a counter-clockwise arc before exploding at the target location, granting sight of the area for 0.5 seconds and dealing magic damage to enemies hit and afflicting them with Moonlight for 3 seconds, during which they are revealed. Lunar Rush interacts with Moonlight. Crescent Strike will cast at max range if cast beyond that.","img":"DianaQ.png","cd":"8/7.5/7/6.5/6","cost":"50","range":"900"},"W":{"name":"Pale Cascade","desc":"Active: Diana grants herself a shield for up to 5 seconds and creates three spheres that orbit her counterclockwise for the same duration, detonating upon contact with an enemy to deal magic damage to nearby enemies. If all three spheres detonate, Pale Cascade's shield is reapplied, stacking with its original shield and refreshing the duration.","img":"DianaOrbs.png","cd":"15/13.5/12/10.5/9","cost":"40/45/50/55/60","range":"800"},"E":{"name":"Lunar Rush","desc":"Active: Diana dashes to the target enemy's location, and upon completion, she deals them magic damage and consumes Moonlight from all enemies. If the target is within 400 range, Diana will dash through their location. If Moonlight is consumed from the target, Lunar Rush's current cooldown is reduced to 0.25 seconds. Diana can cast any of her abilities during the dash.","img":"DianaTeleport.png","cd":"22/20/18/16/14","cost":"40/45/50/55/60","range":"825"},"R":{"name":"Moonfall","desc":"Active: Diana pulls in all nearby enemies, during which they are revealed, then slows them for 2 seconds. If an enemy champion is pulled in, she calls down a beam of moonlight to strike upon the area around her after 1 second, dealing magic damage to all nearby enemies, increased for each champion pulled beyond the first.","img":"DianaR.png","cd":"100/90/80","cost":"100","range":"475"}},"DrMundo":{"title":"the Madman of Zaun","passive":{"name":"Goes Where He Pleases","desc":"Innate: Dr. Mundo regenerates an additional[ 0.4%–2.3% (based on level) of his maximum health every 5 seconds. ][ 0.04%–0.23% (based on level) of his maximum health every 0.5 seconds. ]","img":"DrMundo_P.png"},"Q":{"name":"Infected Bonesaw","desc":"Active: Dr. Mundo throws an infected bonesaw in the target direction that deals magic damage to the first enemy hit and slows them by 40% for 2 seconds. Infected Bonesaw has a minimum damage threshold, and is capped against monsters. If the bonesaw hits an enemy, Dr. Mundo heals for 50% of the health cost, increased to 100% against champions or monsters.","img":"DrMundoQ.png","cd":"4","cost":"0","range":"975"},"W":{"name":"Heart Zapper","desc":"Active: Dr. Mundo charges up a defibrillator for up to 3 seconds, dealing magic damage every 0.25 seconds to nearby enemies and storing 80%–95% (based on level) of post-mitigation damage he takes as grey health on his health bar, reduced to 25% after the first 0.75 seconds. Heart Zapper can be recast after 0.5 seconds within the duration, and does so automatically after the duration.","img":"DrMundoW.png","cd":"17/16.5/16/15.5/15","cost":"0","range":"325"},"E":{"name":"Blunt Force Trauma","desc":"Passive: Dr. Mundo gains bonus attack damage.","img":"DrMundoE.png","cd":"9/8.25/7.5/6.75/6","cost":"0","range":"0"},"R":{"name":"Maximum Dosage","desc":"Active: Dr. Mundo injects himself with chemicals to become enhanced for 10 seconds, gaining increased base health, bonus movement speed, and bonus health regeneration. At rank 3, Maximum Dosage's increased base health and bonus health regeneration are both increased by 5% for each enemy champion within 1200 units at the time of cast.","img":"DrMundoR.png","cd":"120","cost":"0","range":"20"}},"Draven":{"title":"the Glorious Executioner","passive":{"name":"League of Draven","desc":"Innate: When Draven catches a Spinning Axe, kills a non-champion, or destroys a turret, he gains a stack of Adoration. When Draven kills an enemy champion, he consumes all of his Adoration stacks and gains 25 + (2 × stacks) bonus gold. Draven loses 50% of his Adoration stacks upon death.","img":"Draven_passive.png"},"Q":{"name":"Spinning Axe","desc":"Active: Draven starts spinning his axe, empowering his next basic attack within 5.8 seconds to deal bonus physical damage. Upon hitting the target, the axe then ricochets off of them to land after 2 seconds, with the location being determined by Draven's current movement. If Draven catches the axe, he gains Spinning Axe's empowered attack again. Draven can hold up to two Spinning Axes at once.","img":"DravenSpinning.png","cd":"12/11/10/9/8","cost":"45","range":"300"},"W":{"name":"Blood Rush","desc":"Active: Draven enters an adrenaline rush, gaining bonus attack speed for 3 seconds as well as decaying bonus movement speed and ghosting for 1.5 seconds. Catching a Spinning Axe resets Blood Rush's cooldown.","img":"DravenFury.png","cd":"12","cost":"40/35/30/25/20","range":"1000"},"E":{"name":"Stand Aside","desc":"Active: Draven throws a fan of axes in a line in the target direction, dealing physical damage to enemies hit, knocking them aside, though not through terrain, and slowing them for 2 seconds.","img":"DravenDoubleShot.png","cd":"16/15/14/13/12","cost":"70","range":"1050"},"R":{"name":"Whirling Death","desc":"Active: Draven hurls two massive axes in the target direction that briefly grant sight of their surroundings and deal physical damage to enemies hit. Enemy champions that are damaged to or while below a health threshold equal to the number of Adoration stacks are executed. Whirling Death can be recast after 1 second while the axes are traveling, and does so automatically after the axes hit an enemy champion or the edge of the map.","img":"DravenRCast.png","cd":"100/90/80","cost":"100","range":"20000"}},"Ekko":{"title":"the Boy Who Shattered Time","passive":{"name":"Z-Drive Resonance","desc":"Innate - Resonance: Ekko's basic attacks on-hit and damaging abilities apply a stack of Resonance to enemies hit for 4 seconds, refreshing on subsequent hits and stacking up to 3 times. The third stack consumes them all to deal 30–140 (based on level) (+ 90% AP) bonus magic damage. Z-Drive Resonance deals 300% damage against monsters. Resonance cannot affect the same target more than once every few seconds.","img":"Ekko_P.png"},"Q":{"name":"Timewinder","desc":"Active: Ekko throws a temporal grenade in the target direction that deals magic damage to enemies hit. At 700 units or upon hitting an enemy champion, the grenade slows down for 1.75 seconds to gradually expand into a Temporal Sickness field that slows nearby enemies, travelling for another 190 units. Afterwards, the grenade contracts and homes back to Ekko at an increased speed, dealing magic damage to enemies hit.","img":"EkkoQ.png","cd":"9/8.5/8/7.5/7","cost":"50/60/70/80/90","range":"1075"},"W":{"name":"Parallel Convergence","desc":"Passive: Ekko's basic attacks deal bonus magic damage equal to 3% (+ 3% per 100 AP) of the target's missing health against enemies below 30% of their maximum health. The damage has a minimum threshold of 15 and is capped at 150 against minions and monsters.","img":"EkkoW.png","cd":"22/20/18/16/14","cost":"30/35/40/45/50","range":"1600"},"E":{"name":"Phase Dive","desc":"Active: Ekko dashes in the target direction, then empowers his next basic attack within 3 seconds to have a 0.25-second cast time, gain 300 bonus range, cause him to blink within 125 range of the target, and deal bonus magic damage. Phase Dive resets Ekko's basic attack timer. Ekko can cast any of his abilities during the dash.","img":"EkkoE.png","cd":"9/8.5/8/7.5/7","cost":"40/45/50/55/60","range":"325"},"R":{"name":"Chronobreak","desc":"Passive: Upon learning Chronobreak or if its current cooldown is lower than 4 seconds, Ekko reveals a time-delayed afterimage of himself that constantly tracks where he was 4 seconds ago.","img":"EkkoR.png","cd":"110/80/50","cost":"100","range":"850"}},"Elise":{"title":"the Spider Queen","passive":{"name":"Spider Queen","desc":"Innate - Human Form: Elise gains one dormant Spiderling whenever she hits an enemy with an ability, storing once per cast and up to 2 / 3 / 4 / 5 (based on Human Form's Rank) at a time. She stores the maximum number of Spiderlings when the game starts and upon respawning.","img":"ElisePassive.png"},"Q":{"name":"Neurotoxin / Venomous Bite","desc":"Active: Elise fires a toxin at the target enemy that deals magic damage, with the damage based on the target's health ratio being capped against monsters.","img":"EliseHumanQ.png","cd":"6","cost":"80/85/90/95/100","range":"615"},"W":{"name":"Volatile Spiderling / Skittering Frenzy","desc":"Active: Elise summons a venom-gorged spider for 3 seconds, which is untargetable and crawls to the target location, navigating its path upon encountering terrain. The spider explodes upon contact with an enemy or at the end of its lifespan, dealing magic damage to nearby enemies.","img":"EliseHumanW.png","cd":"12","cost":"60/70/80/90/100","range":"950"},"E":{"name":"Cocoon / Rappel","desc":"Active: Elise fires a web in the target direction, stunning the first enemy hit for a few seconds, during which they are also revealed.","img":"EliseHumanE.png","cd":"12/11.5/11/10.5/10","cost":"50","range":"1075"},"R":{"name":"Spider Form","desc":"Passive: Spider Queen's bonuses are increased. Toggle: Elise switches between her Human Form and Spider Form. Spider Form: Elise transforms into a spider, gaining 25 bonus movement speed, melee basic attacks with 125 range, and access to her arachnid abilities. Additionally, she summons all stored Spiderlings and heals them to full health.","img":"EliseR.png","cd":"3","cost":"0","range":"20"}},"Evelynn":{"title":"Agony's Embrace","passive":{"name":"Demon Shade","desc":"Innate: Evelynn shrouds herself in Demon Shade after not performing actions that break stealth for 4 seconds. Attacking or casting abilities ends Demon Shade immediately and places it on a 4-second static cooldown, reduced to 1.25 seconds from casting Last Caress. Taking damage from champions or turrets interrupts Demon Shade and places it on a 1.5-second static cooldown.","img":"Evelynn_Passive.png"},"Q":{"name":"Hate Spike","desc":"Active: Evelynn launches a dart in the target direction, dealing magic damage to the first enemy hit and marking them for 4 seconds. Evelynn's next 3 basic attacks or abilities against the marked target deal bonus magic damage. Hate Spike may be recast up to 3 times at no cost until the ability comes off cooldown.","img":"EvelynnQ.png","cd":"4","cost":"40/45/50/55/60","range":"800"},"W":{"name":"Allure","desc":"Active: Evelynn curses the target enemy champion or medium or large monster for 5 seconds. Evelynn's next basic attack or ability against the accursed target expunges them, slowing them by 45% for 0.75 seconds.","img":"EvelynnW.png","cd":"15/14/13/12/11","cost":"60/70/80/90/100","range":"1200/1300/1400/1500/1600"},"E":{"name":"Whiplash","desc":"Active: Evelynn whips the target enemy with her lashers, dealing magic damage and applying on-hit effects. Evelynn also gains bonus movement speed for 2 seconds. Gaining Demon Shade resets Whiplash's cooldown and empowers its next cast. The damage based on the target's health ratio for both Whiplash and its empowered cast deals a minimum of 25 and is capped at 450 against monsters.","img":"EvelynnE.png","cd":"8","cost":"40/45/50/55/60","range":"210"},"R":{"name":"Last Caress","desc":"Active: Evelynn reveals her true form, becoming untargetable at the start of the cast time and then unleashing her lashers in a cone in the target direction, dealing magic damage to enemies struck within. After 0.5 seconds, she blinks 700 units in the opposite direction and becomes targetable again. Last Caress is empowered to deal 240% damage against enemies below 30% of their maximum health.","img":"EvelynnR.png","cd":"120/100/80","cost":"100","range":"25000"}},"Ezreal":{"title":"the Prodigal Explorer","passive":{"name":"Rising Spell Force","desc":"Innate: Ezreal generates a stack of Rising Spell Force for each enemy hit by his abilities, lasting for 6 seconds, refreshing on subsequent hits, and stacking up to 5 times. Rising Spell Force: For each stack, Ezreal gains 10% bonus attack speed, up to a maximum of 50%.","img":"Ezreal_RisingSpellForce.png"},"Q":{"name":"Mystic Shot","desc":"Active: Ezreal fires a bolt of energy in the target direction that deals physical damage to the first enemy hit, applying on-hit effects and triggering on-attack effects. If Mystic Shot successfully hits an enemy, the current cooldowns of Ezreal's abilities, including Mystic Shot's, are reduced by 1.5 seconds.","img":"EzrealQ.png","cd":"5.5/5.25/5/4.75/4.5","cost":"28/31/34/37/40","range":"1150"},"W":{"name":"Essence Flux","desc":"Active: Ezreal fires an orb in the target direction that marks the first enemy champion, epic monster, or structure hit for 4 seconds. His next basic attack or ability against the target detonates the mark to deal them bonus magic damage. If the mark was detonated with an ability, Ezreal restores 60 mana plus the mana cost of that ability.","img":"EzrealW.png","cd":"8","cost":"50","range":"1150"},"E":{"name":"Arcane Shift","desc":"Active: Ezreal blinks from his current location to up to 475 units towards the target location, then fires a homing bolt towards the nearest enemy that deals magic damage and reveals them for 1 second. Arcane Shift prioritizes firing at the nearest enemy marked by Essence Flux. The target does not have to be visible to be hit by this ability. Arcane Shift will cast at max range if cast beyond that.","img":"EzrealE.png","cd":"26/23/20/17/14","cost":"70","range":"475"},"R":{"name":"Trueshot Barrage","desc":"Active: Ezreal fires an arc of energy in the target direction that briefly grants sight of its surroundings and deals magic damage to enemies hit. Minions and non-epic monsters take 50% reduced damage.","img":"EzrealR.png","cd":"120/105/90","cost":"100","range":"25000"}},"Fiddlesticks":{"title":"the Ancient Fear","passive":{"name":"A Harmless Scarecrow","desc":"Innate - Scarecrow Effigy: Fiddlesticks begins the game with an exclusive Scarecrow Effigy, which permanently occupies the trinket slot. Fiddlesticks can pretend to be an Effigy by standing still and not acting nor being acted upon for 2 seconds, during which it adjusts its body into a scarecrow and extends its arm out to expose its lantern.","img":"FiddlesticksP.png"},"Q":{"name":"Terrify","desc":"Passive: While Fiddlesticks has been out of combat for at least 2.5 seconds and is not visible to the enemy team, or is pretending to be an Effigy, its next damaging ability will additionally fear targets hit for a duration. Active: Fiddlesticks launches a crow at the target enemy that deals magic damage and fears them for a duration. Terrify has a minimum damage threshold and is capped at 400 against monsters.","img":"FiddleSticksQ.png","cd":"15/14.5/14/13.5/13","cost":"65","range":"575"},"W":{"name":"Bountiful Harvest","desc":"Active: Fiddlesticks forms a tether between itself and each nearby enemy over the cast time, then channels for up to 2 seconds to harvest their souls, revealing them in the process.","img":"FiddleSticksW.png","cd":"10/9.5/9/8.5/8","cost":"60/65/70/75/80","range":"650"},"E":{"name":"Reap","desc":"Active: Fiddlesticks slashes the target location with its scythe, dealing magic damage to enemies within the area and slowing them for 1.25 seconds. Enemies hit in the center of the area are also silenced for 1.25 seconds.","img":"FiddleSticksE.png","cd":"10/9/8/7/6","cost":"40/45/50/55/60","range":"850"},"R":{"name":"Crowstorm","desc":"Active: Fiddlesticks channels for 1.5 seconds, then blinks to the target location upon completion with a murder of crows flying wildly around it for 5 seconds, dealing magic damage every 0.25 seconds to nearby enemies. Crowstorm will cast at max range if cast beyond that.","img":"FiddleSticksR.png","cd":"140/110/80","cost":"100","range":"800"}},"Fiora":{"title":"the Grand Duelist","passive":{"name":"Duelist's Dance","desc":"Innate: Fiora identifies the Vitals of nearby visible enemy champions, marked as an arc around them in North-, East-, South- or Westward direction. Vitals take 1.75 seconds to become targetable and linger for 13.25 seconds afterwards while Fiora remains near the target, otherwise the Vital will disappear. After a Vital ends, Fiora identifies a new one on her target.","img":"Fiora_P.png"},"Q":{"name":"Lunge","desc":"Active: Fiora dashes in the target direction, then stabs a nearby enemy. Lunge can hit structures and wards. Stabbing a target reduces Lunge's cooldown by 50%. The stab deals physical damage and applies on-hit effects. Fiora can cast any of her abilities during the dash. The target does not have to be visible to be hit by this ability, unless it is a ward.","img":"FioraQ.png","cd":"13/11.25/9.5/7.75/6","cost":"20","range":"400"},"W":{"name":"Riposte","desc":"Active: Fiora enters a defensive stance for 0.75 seconds, becoming unable to act, preventing all incoming non-turret damage, and gaining debuff immunity and crowd control immunity. Additionally, over the first 0.5 seconds of the duration, Fiora poises to strike, after which she sends a shock with her sword in a line in the target direction, dealing magic damage to all enemies hit until colliding with an enemy champion.","img":"FioraW.png","cd":"24/22/20/18/16","cost":"50","range":"750"},"E":{"name":"Bladework","desc":"Active: Fiora empowers her next two basic attacks on-attack within 4 seconds to gain 25 bonus range and bonus attack speed. The first attack slows the target by 30% for 1 second but cannot critically strike. The second attack will critically strike for modified critical damage, including to structures. Bladework resets Fiora's basic attack timer.","img":"FioraE.png","cd":"11/10/9/8/7","cost":"40","range":"425"},"R":{"name":"Grand Challenge","desc":"Passive: Duelist's Dance's bonus movement speed is increased. Active: Fiora challenges the target enemy champion for 8 seconds, highlighting all four of their Vitals after a 0.5-second delay. While in effect, Duelist's Dance does not identify new Vitals on Fiora's target. While near the target, Fiora gains Duelist's Dance's bonus movement speed.","img":"FioraR.png","cd":"110/90/70","cost":"100","range":"500"}},"Fizz":{"title":"the Tidal Trickster","passive":{"name":"Nimble Fighter","desc":"Innate: Fizz is permanently ghosted and reduces every instance of incoming damage by 4 (+ 1% AP), up to a maximum of 50% reduction.","img":"Fizz_P.png"},"Q":{"name":"Urchin Strike","desc":"Active: Fizz dashes a fixed distance in the direction of the target enemy. If they are in range upon arrival, he deals magic damage plus 100% AD physical damage and applies on-hit effects. Seastone Trident and Chum the Waters can be cast during the dash.","img":"FizzQ.png","cd":"8/7.5/7/6.5/6","cost":"50","range":"550"},"W":{"name":"Seastone Trident","desc":"Passive: Fizz's basic attacks rend enemies on-hit, dealing magic damage every 0.5 seconds over 3 seconds, refreshing on subsequent hits. Active: Fizz empowers his next basic attack within 4 seconds to have an uncancellable windup, gain 50 bonus range, and deal bonus magic damage.","img":"FizzW.png","cd":"7/6/5/4/3","cost":"30/40/50/60/70","range":"600"},"E":{"name":"Playful / Trickster","desc":"Active: Fizz dashes to the target location while becoming untargetable, balancing on his trident for 0.75 seconds, during which he can cast Trickster after 0.15 seconds into the duration. He then begins to hop off of his trident over 0.5 seconds, afterwards becoming targetable and landing to create a splash that deals magic damage to nearby enemies and slows them for 2 seconds.","img":"FizzE.png","cd":"16/14/12/10/8","cost":"75/80/85/90/95","range":"400"},"R":{"name":"Chum the Waters","desc":"Active: Fizz throws down a lure at the target location that attracts a shark, granting sight of the area before it emerges to chomp at the lure after 2 seconds, dealing magic damage to nearby enemies, knocking them back, though not through terrain, and slowing them for 2 seconds. The further the lure travels in its initial flight, the larger the shark that is attracted; increasing Chum the Waters' damage, slow, eruption radius and knock back distance.","img":"FizzR.png","cd":"120/100/80","cost":"100","range":"1300"}},"Galio":{"title":"the Colossus","passive":{"name":"Colossal Smash","desc":"Innate: Periodically, Galio's next basic attack is empowered to have an uncancellable windup, gain 40% bonus attack speed and deal 15–115 (based on level) (+ 100% AD) (+ 45% AP) (+ 60% bonus magic resistance) modified magic damage to the target and all enemies near them.","img":"Galio_Passive.png"},"Q":{"name":"Winds of War","desc":"Active: Galio creates two windblasts 250 units to either side of him that arc out before converging to the target location, dealing magic damage to all enemies they pass through.","img":"GalioQ.png","cd":"11/10/9/8/7","cost":"60/65/70/75/80","range":"825"},"W":{"name":"Shield of Durand","desc":"Passive: Galio gains Anti-Magic Bulwark, and restores it after 12 / 10 / 8 (based on level) seconds without taking damage.Anti-Magic Bulwark: Gain a shield that absorbs magic damage.","img":"GalioW.png","cd":"18/17/16/15/14","cost":"50","range":"275"},"E":{"name":"Justice Punch","desc":"Active: Galio steps backwards in the opposite direction over the cast time, then dashes to the target location until he hits an enemy champion or terrain. Galio deals magic damage to enemies he passes through, reduced to 80% against non-champions, and knocks them up for 0.75 seconds as well as reveals them for the same duration. Justice Punch will cast at max range if cast beyond that.","img":"GalioE.png","cd":"11/10/9/8/7","cost":"50","range":"650"},"R":{"name":"Hero's Entrance","desc":"Active: Galio prepares to make an entrance, channeling for 2.75 seconds and designating the target allied champion's location at the time of cast as his landing spot. Additionally, he resets Shield of Durand's passive shield for himself and grants it to all allied champions within the area for 5 seconds.","img":"GalioR.png","cd":"180/160/140","cost":"100","range":"4000/4750/5500"}},"Gangplank":{"title":"the Saltwater Scourge","passive":{"name":"Trial by Fire","desc":"Innate: Periodically, Gangplank empowers his next basic attack to set the target on fire, dealing them[ 50–250 (based on level) (+ 100% bonus AD) (+ 2 per 1% critical strike chance) bonus true damage over 2.5 seconds. ][ 5–25 (based on level) (+ 10% bonus AD) (+ 0.2 per 1% critical strike chance) bonus true damage every 0.25 seconds over 2.5 seconds. ] Turrets are dealt 50% damage.","img":"Gangplank_Passive.png"},"Q":{"name":"Parrrley","desc":"Active: Gangplank fires a shot at the target enemy that deals physical damage, applies on-hit effects as a ranged attack, and triggers on-attack effects. Parrrley can critically strike for (175% + 40%) damage. If Parrrley kills the target, Gangplank plunders gold and Silver Serpents. Each enemy killed by a Powder Keg explosion that was originally set off by Parrrley also counts for the plunder.","img":"GangplankQWrapper.png","cd":"4.5","cost":"50/45/40/35/30","range":"625"},"W":{"name":"Remove Scurvy","desc":"Active: Gangplank consumes a large quantity of citrus fruit, cleansing himself from all crowd control and healing himself.","img":"GangplankW.png","cd":"22/20/18/16/14","cost":"60/70/80/90/100","range":"400"},"E":{"name":"Powder Keg","desc":"Active: Gangplank consumes a charge to place a powder keg at the target location that lasts for 25 seconds and will connect to other kegs with overlapping connection radius through a trail of black powder. The keg starts with 3 health and loses 1 every 2 / 1 / 0.5 (based on level) seconds until it is left with 1 health. Gangplank periodically stocks a Powder Keg charge, up to a maximum.","img":"GangplankE.png","cd":"0","cost":"0","range":"1000"},"R":{"name":"Cannon Barrage","desc":"Active: Gangplank shoots a flare into the air, signaling his ship off-shore to fire upon the target location for 8 seconds, calling down 12 waves of cannonballs in clusters of 3 every 2 seconds, and granting sight of the area for the duration. Each wave deals magic damage to all enemies within the area and slows them by 30% for 0.5 seconds.","img":"GangplankR.png","cd":"160/140/120","cost":"100","range":"30000"}},"Garen":{"title":"The Might of Demacia","passive":{"name":"Perseverance","desc":"Innate: Garen regenerates an additional[ 1.5%–10.1% (based on level) of his maximum health every 5 seconds. ][ 0.15%–1.01% (based on level) of his maximum health every 0.5 seconds. ] Perseverance is lost for 8 seconds if Garen takes damage from champions, epic monsters, or turrets, or if he is hit by an enemy ability or affected by an enemy summoner spell, refreshing on subsequent damage and hits taken from them.","img":"Garen_Passive.png"},"Q":{"name":"Decisive Strike","desc":"Active: Garen cleanses himself of all slows and gains 35% bonus movement speed for a duration. Additionally, Garen empowers his next basic attack within 4.5 seconds to have an uncancellable windup, lunge at the target, deal bonus physical damage, and silence them for 1.5 seconds. Decisive Strike resets Garen's basic attack timer.","img":"GarenQ.png","cd":"8","cost":"0","range":"300"},"W":{"name":"Courage","desc":"Passive: Whenever Garen kills an enemy, he generates a stack of Courage, stacking up to 150 times. Courage: For each stack, Garen gains 0.2 bonus armor and 0.2 bonus magic resistance, up to a maximum of 30 bonus resistances each. After reaching maximum stacks, Garen gains 10% bonus armor and 10% bonus magic resistance.","img":"GarenW.png","cd":"22/19.5/17/14.5/12","cost":"0","range":"0"},"E":{"name":"Judgment","desc":"Active: Garen rapidly spins his sword around himself 7 (+ 1 per 25% bonus attack speed) times over 3 seconds, becoming unable to declare basic attacks but gaining ghosting and dealing physical damage to nearby enemies periodically. Judgment can be recast after 1 second while active, and does so automatically after it ends.","img":"GarenE.png","cd":"9/8.25/7.5/6.75/6","cost":"0","range":"325"},"R":{"name":"Demacian Justice","desc":"Active: Garen calls upon the might of Demacia onto the target enemy champion, dealing them true damage as well as revealing them for 1 second at the start of the cast time.","img":"GarenR.png","cd":"120/100/80","cost":"0","range":"400"}},"Gnar":{"title":"the Missing Link","passive":{"name":"Rage Gene","desc":"Innate - Rage Gene: Mini Gnar generates 4 / 7 / 11 (based on level) Rage over 2 seconds upon dealing or receiving damage, up to 100. Against non-champions, basic attacks and Boomerang Throw instantly generate[ 0.5 / 0.875 / 1.375 (based on level) Rage. ][ 12.5% of the amount. ] Against champions, Boomerang Throw instantly generates[ 1 / 1.75 / 2.75 (based on level) Rage, ][ 25% of the amount, ]and basic attacks instantly generate[ 2 / 3.5 / 5.5 (based on level). ][ 50% of the amount. ] Boomerang Throw can only generate Rage once per cast, and grants Rage based on the first enemy hit. Gnar's Rage decays after being out of combat for 13 seconds.","img":"Gnar_Passive.png"},"Q":{"name":"Boomerang Throw / Boulder Toss","desc":"Active: Gnar throws a boomerang in a line in the target direction that deals physical damage to enemies in its path and slows them for 2 seconds. After reaching its maximum range or hitting an enemy, the boomerang flies back toward Gnar based on his current movement, dealing 50% damage to subsequent targets. Catching the boomerang while it is returning back refunds 40% of the ability's total cooldown.","img":"GnarQ.png","cd":"16/14.5/13/11.5/10","cost":"0","range":"1100"},"W":{"name":"Hyper / Wallop","desc":"Passive: Gnar's basic attacks on-hit and ability hits apply a stack of Hyper to enemies for 3.5 seconds, refreshing on subsequent applications and stacking up to 3 times. The third stack against a target consumes them all to deal bonus magic damage, capped at 300 against monsters, and grant Gnar 20 / 40 / 60 / 80% (based on GNAR!'s rank) bonus movement speed that decays over 3 seconds.","img":"GnarW.png","cd":"7","cost":"0","range":"0"},"E":{"name":"Hop / Crunch","desc":"Active: Gnar leaps to the target location, then gains bonus attack speed for 6 seconds. If Gnar lands on a unit he will bounce 500 units further in the same direction. Landing on an enemy deals them physical damage and slows them by 80% for 0.5 seconds. Gnar will not bounce if he is immobilized during the first leap. Boomerang Throw can be cast during the dash. Hop will cast at max range if cast beyond that.","img":"GnarE.png","cd":"22/19.5/17/14.5/12","cost":"0","range":"475"},"R":{"name":"GNAR!","desc":"Mini Gnar - Passive: Hyper's bonus movement speed is increased. Mega Gnar - Active: Gnar thrusts in the target direction, knocking away nearby enemies up to 590 units in that direction, though not through terrain, and afterwards dealing them physical damage, as well as slowing them by 45% after a 0.4-second delay for a duration.","img":"GnarR.png","cd":"90/60/30","cost":"0","range":"590"}},"Gragas":{"title":"the Rabble Rouser","passive":{"name":"Happy Hour","desc":"Innate: Periodically, after casting an ability, Gragas heals himself for 5.5% of his maximum health.","img":"GragasPassiveHeal.png"},"Q":{"name":"Barrel Roll","desc":"Active: Gragas rolls a cask to the target location, remaining there for 4 seconds and granting sight of the area. Upon arrival, the cask starts to ferment over the first 2 seconds of its duration to increase its damage and the effectiveness of its slow, up to a maximum of 150% of their initial values. Barrel Roll can be recast at any time within its duration after the cask has fully travelled, and does so automatically after its duration ends.","img":"GragasQ.png","cd":"10/9/8/7/6","cost":"80","range":"850"},"W":{"name":"Drunken Rage","desc":"Active: Gragas channels for 0.75 seconds, drinking out of his brew, and gains damage reduction for 2.5 seconds. Upon completing the channel, Gragas empowers his next basic attack within 5 seconds to have an uncancellable windup, gain 50 bonus range and deal bonus magic damage to the target and nearby enemies, reduced to 50% against structures and capped at 300 against monsters.","img":"GragasW.png","cd":"5","cost":"30","range":"20"},"E":{"name":"Body Slam","desc":"Active: Gragas charges in the target direction and stops upon colliding with an enemy, dealing magic damage to all nearby enemies, knocking them back, though not through terrain, and stunning them for 1 second. Body Slam's current cooldown is reduced by 40% if Gragas hits an enemy. Barrel Roll and Explosive Cask can be cast during the dash.","img":"GragasE.png","cd":"14/13.5/13/12.5/12","cost":"50","range":"600"},"R":{"name":"Explosive Cask","desc":"Active: Gragas hurls a cask that travels to the target location over 0.5 seconds, exploding on impact to deal magic damage to all enemies within the area and knock them back 900 units, though not through terrain, from the epicenter of the explosion, as well as granting sight of the area for 1 second.","img":"GragasR.png","cd":"100/85/70","cost":"100","range":"1000"}},"Graves":{"title":"the Outlaw","passive":{"name":"New Destiny","desc":"Innate - Double Barrel: Graves' basic attacks fire his shotgun to consume ammunition within 2 shells. He will reload over a few seconds immediately after expending all shells or withholding leftover shells for a while. The reload time is reduced by Graves' level and bonus attack speed, and can be interrupted by declaring an attack or casting an ability.","img":"GravesTrueGrit.png"},"Q":{"name":"End of the Line","desc":"Active: Graves fires a round in the target direction that deals physical damage to enemies it passes through and leaves behind a powder trail. After 2 seconds, or 0.231 seconds upon colliding with terrain, the round detonates to deal physical damage to enemies within a wide perpendicular area and in a reverse wave along the powder trail.","img":"GravesQLineSpell.png","cd":"13/11.25/9.5/7.75/6","cost":"80","range":"925"},"W":{"name":"Smoke Screen","desc":"Active: Graves fires a smoke canister at the target location that upon impact deals magic damage to enemies within the area and slows them by 50% for 0.5 seconds. The canister creates a cloud of smoke for 4 seconds that applies nearsight of outside the area to all enemies within every 0.25 seconds, reducing their sight radius relative to the center.","img":"GravesSmokeGrenade.png","cd":"26/24/22/20/18","cost":"70/75/80/85/90","range":"950"},"E":{"name":"Quickdraw","desc":"Active: Graves dashes to the target location, reloading one shell while generating a stack of True Grit for 4 seconds, stacking up to 8 times. Dashing towards an enemy champion generates 2 stacks of True Grit. Quickdraw's current cooldown is reduced by 0.5 seconds for every pellet impacting an enemy.","img":"GravesMove.png","cd":"16/15/14/13/12","cost":"40","range":"425"},"R":{"name":"Collateral Damage","desc":"Active: Graves fires an explosive shell in the target direction that deals physical damage to enemies hit and causes him to recoil 400 units in the opposite direction. Upon hitting an enemy champion or reaching the end of its range, the shell explodes in a cone to deal reduced damage to additional enemies.","img":"GravesChargeShot.png","cd":"100/80/60","cost":"100","range":"1000"}},"Gwen":{"title":"The Hallowed Seamstress","passive":{"name":"A Thousand Cuts","desc":"Innate: Gwen's basic attacks on-hit, the center of Snip Snip!, and Needlework deal bonus magic damage equal to 1% (+ 0.55% per 100 AP) of the target's maximum health.","img":"Gwen_Passive.png"},"Q":{"name":"Snip Snip!","desc":"Passive: Gwen's basic attacks generate a stack of Snippy on-hit for 6 seconds, stacking up to 4 times and refreshing on subsequent attacks.","img":"GwenQ.png","cd":"6.5/5.75/5/4.25/3.5","cost":"40","range":"450"},"W":{"name":"Hallowed Mist","desc":"Active: Gwen summons the Hallowed Mist upon her current location, lasting for 4 seconds. Hallowed Mist can be recast after 0.5 seconds, and does so automatically if Gwen attempts to leave the area. While inside the mist, Gwen becomes ghosted, gains 22 (+ 7% AP) bonus armor and bonus magic resistance and is untargetable to all enemies (except turrets and monsters) outside of the mist.","img":"GwenW.png","cd":"22/21/20/19/18","cost":"60","range":"0"},"E":{"name":"Skip 'n Slash","desc":"Active: Gwen dashes to the target location, then empowers her basic attacks within the next 4 seconds to deal bonus magic damage on-hit and gain bonus attack speed and 75 bonus attack range. Gwen's first basic attack within the duration reduces Skip 'n Slash's cooldown by 50%.","img":"GwenE.png","cd":"13/12.5/12/11.5/11","cost":"35","range":"400"},"R":{"name":"Needlework","desc":"Active: Gwen launches a needle in the target direction that deals magic damage to enemies hit and slows them by 60% them for 1.5 seconds.","img":"GwenR.png","cd":"120/100/80","cost":"100","range":"1200"}},"Hecarim":{"title":"the Shadow of War","passive":{"name":"Warpath","desc":"Innate: Hecarim gains bonus attack damage equal to 12%–24% (based on level) of his bonus movement speed.","img":"Hecarim_Passive.png"},"Q":{"name":"Rampage","desc":"Active: Hecarim cleaves his glaive around himself, dealing physical damage to nearby enemies, reduced to 60% against minions.","img":"HecarimRapidSlash.png","cd":"4","cost":"28/26/24/22/20","range":"350"},"W":{"name":"Spirit of Dread","desc":"Active: Hecarim surrounds himself with the Spirit of Dread for 4 seconds, dealing magic damage every second to nearby enemies. While active, Hecarim gains bonus armor and bonus magic resistance and is healed for 25% of the post-mitigation damage dealt to enemies within the area from all sources, halved to 12.5% for damage dealt by allies. The healing is capped against minions and monsters.","img":"HecarimW.png","cd":"14","cost":"50/55/60/65/70","range":"525"},"E":{"name":"Devastating Charge","desc":"Active: Hecarim becomes ghosted and gains 25%–65% (based on time active) bonus total movement speed for 4 seconds.","img":"HecarimRamp.png","cd":"20/19/18/17/16","cost":"60","range":"300"},"R":{"name":"Onslaught of Shadows","desc":"Active: Hecarim dashes with displacement immunity to the target location and summons 5 spectral riders in an arrow formation that charge alongside him in the target direction, dealing magic damage to all enemies in their path and revealing them for 2.5 seconds. Upon arrival, he fears nearby enemies for 0.75–1.5 (based on distance traveled) seconds and slows them, ramping to 99% over the duration.","img":"HecarimUlt.png","cd":"140/120/100","cost":"100","range":"50000"}},"Heimerdinger":{"title":"the Revered Inventor","passive":{"name":"Hextech Affinity","desc":"Innate: Heimerdinger gains 20% bonus movement speed while near an allied turret or a H-28G Evolution Turret or H-28Q Apex Turret deployed by him.","img":"Heimerdinger_Passive.png"},"Q":{"name":"H-28 G Evolution Turret","desc":"Active: Heimerdinger deploys a H-28G Evolution Turret at the target location, which lasts until destroyed. Heimerdinger periodically stocks a Turret Kit charge, up to a maximum of 3. Up to 3 H-28G Evolution Turrets can be deployed at a time, with those deployed beyond the maximum destroying the oldest one. See Pets for more details about H-28G Evolution Turrets.","img":"HeimerdingerQ.png","cd":"1","cost":"20","range":"350"},"W":{"name":"Hextech Micro-Rockets","desc":"Active: Heimerdinger launches a wave of 5 rockets that converge upon the target location and fan beyond it up to a maximum range, with each one dealing magic damage to the first enemy it hits. Every rocket hitting an enemy champion grants 20% beam charge to all turrets within 1000 range, up to a maximum of 100% beam charge when hitting 5 rockets on an enemy champion.","img":"HeimerdingerW.png","cd":"11/10/9/8/7","cost":"50/60/70/80/90","range":"1325"},"E":{"name":"CH-2 Electron Storm Grenade","desc":"Active: Heimerdinger hurls a grenade at the target location that detonates upon impact, dealing magic damage to nearby enemies and slowing them by 35% for 2 seconds. If the grenade hits an enemy champion, all turrets within 1000 range of the impact gain 100% beam charge. Enemies hit at the center of the grenade's impact are also stunned for 1.5 seconds.","img":"HeimerdingerE.png","cd":"11","cost":"85","range":"970"},"R":{"name":"UPGRADE!!!","desc":"Active: Heimerdinger empowers his next basic ability for an additional effect, consuming the empowerment upon cast and placing UPGRADE!!! on full cooldown. These empowered abilities have the same cooldowns as their basic forms, deal modified damage, and do not have a mana cost. UPGRADE!!! can be recast after 3 seconds while the empowerment is available. Recast: Heimerdinger ends UPGRADE!!! and puts it on a 3-second cooldown.","img":"HeimerdingerR.png","cd":"100/85/70","cost":"100","range":"1"}},"Hwei":{"title":"the Visionary","passive":{"name":"Signature of the Visionary","desc":"Innate: Hwei's damaging abilities mark enemies hit for 4 seconds. Subsequent damaging abilities against marked targets consume the mark to create an explosion beneath them, dealing 35–230 (based on level) (+ 30% AP) bonus magic damage to enemies in the area after a 0.85-second delay.","img":"HweiPassive.png"},"Q":{"name":"Subject: Disaster","desc":"Active: Hwei enters a disastrous mood, gaining access to its abilities as well as Wash Brush. He will exit the mood upon casting any of them.","img":"HweiQ.png","cd":"10/9/8/7/6","cost":"80/90/100/110/120","range":"0"},"W":{"name":"Subject: Serenity","desc":"Active: Hwei enters a serene mood, gaining access to its abilities as well as Wash Brush. He will exit the mood upon casting any of them.","img":"HweiW.png","cd":"18/17.5/17/16.5/16","cost":"90/95/100/105/110","range":"0"},"E":{"name":"Subject: Torment","desc":"Active: Hwei enters a tumultuous mood, gaining access to its abilities as well as Wash Brush. He will exit the mood upon casting any of them.","img":"HweiE.png","cd":"12/11.5/11/10.5/10","cost":"50/55/60/65/70","range":"0"},"R":{"name":"Spiraling Despair","desc":"Active: Hwei launches a globule of pure despair in the target direction that collides with the first enemy champion hit, afflicting them with an aura that grows over 3 seconds, reveals the target, and grants sight within its radius. Enemies within are both dealt magic damage and applied a stack of Despair every 0.25 seconds. Despair: For each stack, the target is slowed by 10% for 0.25 seconds, stacking up to 12 times.","img":"HweiR.png","cd":"120/100/80","cost":"100","range":"1300"}},"Illaoi":{"title":"the Kraken Priestess","passive":{"name":"Prophet of an Elder God","desc":"Innate: Periodically, Illaoi spawns a Tentacle on the nearest terrain perpendicular to her location, if no other Tentacles are already nearby it. Tentacles fully spawn after a 2 second delay and are untargetable in the meantime.","img":"Illaoi_P.png"},"Q":{"name":"Tentacle Smash","desc":"Passive: Tentacle damage is increased. Active: Illaoi slams down a Tentacle in the target direction.","img":"IllaoiQ.png","cd":"10/9/8/7/6","cost":"40/45/50/55/60","range":"850"},"W":{"name":"Harsh Lesson","desc":"Active: Illaoi's next basic attack within 6 seconds gains 225 bonus range and causes her to leap to the target's location if they're beyond her normal basic attack range. The attack deals bonus physical damage, with a minimum threshold, and capped at 300 against non-champions, and commands all Tentacles in range to attack the target. The minimum bonus damage can also be applied against turrets.","img":"IllaoiW.png","cd":"4","cost":"30","range":"400"},"E":{"name":"Test of Spirit","desc":"Active: Illaoi launches a tendril in the target direction that stops at the first enemy hit, pulling their Spirit out in front of Illaoi over 0.75 seconds if they're a champion. The target is tethered to the Spirit for 7 seconds, revealing them in addition to granting sight of the area around them while the tether remains.","img":"IllaoiE.png","cd":"16/15/14/13/12","cost":"35/40/45/50/55","range":"900"},"R":{"name":"Leap of Faith","desc":"Active: Illaoi gains displacement immunity and leaps into the air for the cast time. She then slams her idol into the ground, dealing physical damage to nearby enemies. For each enemy champion hit, a Tentacle is summoned for 8 seconds (up to a maximum of 6 summons).","img":"IllaoiR.png","cd":"120/95/70","cost":"100","range":"450"}},"Irelia":{"title":"the Blade Dancer","passive":{"name":"Ionian Fervor","desc":"Innate: Irelia generates a stack of Ionian Fervor for each enemy champion hit by her abilities, or if she hits at least one non-champion, lasting for 6 seconds, refreshing on basic attacks and ability hits against enemy champions, large monsters, and structures, and stacking up to 4 times.","img":"Irelia_Passive.png"},"Q":{"name":"Bladesurge","desc":"Active: Irelia dashes 100 units through the target enemy's location, and upon collision or dash completion, she deals physical damage, applies on-hit effects, and heals herself. Bladesurge deals 50–237 (based on level) bonus physical damage to minions. Bladesurge's current cooldown is reduced to 0.2 seconds upon collision of targets marked as Unsteady, and is reset if the target dies to or during Bladesurge's dash.","img":"IreliaQ.png","cd":"10/9/8/7/6","cost":"15","range":"600"},"W":{"name":"Defiant Dance","desc":"Active: Irelia charges for up to 1.5 seconds, during which she increases Defiant Dance's damage over the first 0.75 seconds of the channel and reduces incoming physical damage by 40%–70% (based on level) (+ 7% per 100 AP) and incoming magic damage by 20%–35% (based on level) (+ 3.5% per 100 AP).","img":"IreliaW.png","cd":"20/18/16/14/12","cost":"70/75/80/85/90","range":"825"},"E":{"name":"Flawless Duet","desc":"Active: Irelia sends a blade to the target location for 3.5 seconds. Flawless Duet can be recast after 0.15 seconds while the blade is active, and does so automatically at the end of its duration, though not if she is unable to cast abilities. Recast: Irelia sends a second blade to the target location, or to her current position if Flawless Duet was recast automatically.","img":"IreliaE.png","cd":"16/14.5/13/11.5/10","cost":"50","range":"850"},"R":{"name":"Vanguard's Edge","desc":"Active: Irelia launches a barrage of blades in the target direction, expanding outward upon hitting an enemy champion, dealing magic damage to all enemies hit and revealing them for 1 second.","img":"IreliaR.png","cd":"125/105/85","cost":"100","range":"950"}},"Ivern":{"title":"the Green Father","passive":{"name":"Friend of the Forest","desc":"Innate: Ivern cannot attack nor damage non-epic monsters. Instead, targeting a jungle camp initiates a 2.5 second channel that will plant a grove upon the camp. Placing a grove costs 94.5–0.14 (based on level) health and 90–0.37 (based on level) mana. The channel cannot be cancelled in the first 0.15 seconds and in the last 0.5 seconds. Ivern cannot place a grove while he is unable to cast abilities.","img":"IvernP.png"},"Q":{"name":"Rootcaller","desc":"Active: Ivern throws a vine in the target direction, dealing magic damage to the first enemy hit and rooting them for a duration, during which they are also revealed. Rootcaller can be recast while the target is rooted. Ivern and allied champions can select the target rooted by Rootcaller to dash to their location, stopping at their attack range. Recast: Ivern dashes to the rooted target.","img":"IvernQ.png","cd":"14/13/12/11/10","cost":"60","range":"1125"},"W":{"name":"Brushmaker","desc":"Passive: While Ivern is in brush, his basic attacks are empowered to deal bonus magic damage on-hit. This bonus persists for 3 seconds after leaving brush. Active: Ivern grows a patch of brush at the target location for 45 seconds, granting sight of the area within and around it for 8 seconds. Brushes despawn instantly after allied vision of them is lost. Spawning brush near terrain or other brush increases its radius.","img":"IvernW.png","cd":"0.5","cost":"30","range":"1150"},"E":{"name":"Triggerseed","desc":"Active: Ivern places a seed on the target allied champion, Daisy, or himself, granting the target a shield for 2 seconds. After 2 seconds, the seed explodes to deal magic damage to nearby enemies and slow them for 2 seconds. If the seed does not damage an enemy champion and the shield persists by the end of the duration, the shield is reapplied for the same strength and duration without the explosion effect.","img":"IvernE.png","cd":"11/10/9/8/7","cost":"70","range":"750"},"R":{"name":"Daisy!","desc":"Active: Ivern summons his sentinel friend Daisy to his side, who lands 350 units away from him in the target direction and remains on the field for up to 45 seconds as a controllable pet. Daisy! can be recast at any time while Daisy is alive. Recast: Ivern commands Daisy to move to the target location. If cast on Ivern, Daisy will follow him.","img":"IvernR.png","cd":"140/130/120","cost":"100","range":"600"}},"Janna":{"title":"the Storm's Fury","passive":{"name":"Tailwind","desc":"Innate: Janna grants 6% bonus movement speed to nearby allied champions that are facing in the direction of her location. Janna's basic attacks on-hit and Zephyr deal bonus magic damage equal to 30% of her bonus movement speed.","img":"JannaP.png"},"Q":{"name":"Howling Gale","desc":"Active: Janna summons a whirlwind at her current location that charges up over 3 seconds, increasing its range, speed, damage, and knock up duration every second over the duration. Howling Gale's direction is determined by this cast. Howling Gale can be recast at any time within the duration, and does so automatically after the duration.","img":"HowlingGale.png","cd":"14","cost":"90/95/100/105/110","range":"1075"},"W":{"name":"Zephyr","desc":"Passive: Janna is ghosted and gains bonus movement speed. Active: Janna sends an air elemental at the target enemy that deals magic damage and slows them for 2 seconds, capped at 99%.","img":"SowTheWind.png","cd":"8/7.5/7/6.5/6","cost":"50/55/60/65/70","range":"4294967295"},"E":{"name":"Eye Of The Storm","desc":"Passive: Whenever Janna's abilities slow or knock up at least one enemy champion, 20% of Eye of the Storm's cooldown is refunded. This may occur once per spell cast. Active: Janna grants the target allied champion or turret, or herself, a shield for 4 seconds. While the shield holds, the target gains bonus attack damage.","img":"EyeOfTheStorm.png","cd":"16/15/14/13/12","cost":"70/75/80/85/90","range":"800"},"R":{"name":"Monsoon","desc":"Active: Janna unleashes a blast that knocks back all nearby enemies to up to 875 units over 0.5 seconds based on their proximity, though not through terrain. Janna also channels for up to 3 seconds, healing herself and nearby allies every 0.25 seconds.","img":"ReapTheWhirlwind.png","cd":"130/115/100","cost":"100","range":"725"}},"JarvanIV":{"title":"the Exemplar of Demacia","passive":{"name":"Martial Cadence","desc":"Innate: Jarvan IV's basic attacks are empowered to deal bonus physical damage equal to 8% of the target's current health, with a minimum threshold of 20 and capped at 400 against non-champion targets. This effect cannot occur on the same target more than once every few seconds.","img":"JarvanIVP.png"},"Q":{"name":"Dragon Strike","desc":"Active: Jarvan IV extends his lance in the target direction, dealing physical damage to enemies hit and inflicting them with armor reduction for 3 seconds. If the lance connects with a deployed Demacian Standard, Jarvan IV dashes to its location, knocking up nearby enemies around him and along his path for 0.75 seconds. Jarvan IV can cast any of his abilities during the dash.","img":"JarvanIVDragonStrike.png","cd":"10/9/8/7/6","cost":"45/50/55/60/65","range":"770"},"W":{"name":"Golden Aegis","desc":"Active: Jarvan IV slows all nearby enemies for 2 seconds. Jarvan IV also grants himself a shield for 4 seconds, increased by 1.3% of his maximum health for each enemy champion hit by Golden Aegis.","img":"JarvanIVGoldenAegis.png","cd":"9","cost":"30","range":"625"},"E":{"name":"Demacian Standard","desc":"Passive: Jarvan IV gains bonus attack speed. Active: Jarvan IV throws a Demacian flag to the target location, dealing magic damage to enemies within the area. The flag then remains for 8 seconds, granting sight of its surroundings and providing an aura that grants Demacian Standard's passive bonus attack speed to all nearby allied champions as well as Jarvan IV himself. Demacian Standard will cast at max range if cast beyond that.","img":"JarvanIVDemacianStandard.png","cd":"12/11.5/11/10.5/10","cost":"55","range":"860"},"R":{"name":"Cataclysm","desc":"Active: Jarvan IV leaps with displacement immunity to the target enemy champion's location over 0.35 seconds, dealing physical damage to all nearby enemies upon arrival.","img":"JarvanIVCataclysm.png","cd":"120/105/90","cost":"100","range":"650"}},"Jax":{"title":"Grandmaster at Arms","passive":{"name":"Relentless Assault","desc":"Innate: Jax's basic attacks generate a stack of Relentless Assault on-attack for 2.5 seconds, refreshing on subsequent attacks and stacking up to 8 times. Stacks expire by one every 0.25 seconds when the duration ends. Relentless Assault: For each stack, Jax gains 3.5%–11% (based on level) bonus attack speed, up to a maximum of 28%–88% (based on level).","img":"Armsmaster_MasterOfArms.png"},"Q":{"name":"Leap Strike","desc":"Active: Jax dashes to the target unit's location. If the target is an enemy and they are in range upon arrival, Jax deals physical damage to them. Jax can cast any of his abilities during the dash.","img":"JaxQ.png","cd":"8/7.5/7/6.5/6","cost":"50","range":"700"},"W":{"name":"Empower","desc":"Active: Jax empowers his next basic attack or Leap Strike against an enemy within 10 seconds to deal bonus magic damage, reduced to 50% against structures. If Empower is used on a basic attack, it will gain 50 bonus range and have an uncancellable windup. Empower resets Jax's basic attack timer.","img":"JaxW.png","cd":"7/6/5/4/3","cost":"30","range":"300"},"E":{"name":"Counter Strike","desc":"Active: Jax enters Evasion for 2 seconds: a defensive stance that causes him to dodge all incoming non-turret basic attacks and take 25% reduced damage from all area of effect abilities from champions. Counter Strike can be recast after 1 second, and does so automatically after the duration.","img":"JaxE.png","cd":"17/15/13/11/9","cost":"50/60/70/80/90","range":"300"},"R":{"name":"Grandmaster-at-Arms","desc":"Passive: Jax's basic attacks generate a stack of Grandmaster-At-Arms on-hit for 2.5 seconds, refreshing on subsequent hits and stacking up to 2 times. At 2 stacks, his next basic attack on-hit is empowered to consume them all to deal bonus magic damage, reduced to 50% against structures. While Grandmaster-At-Arms is active, the empowered attack triggers at 1 stack instead.","img":"JaxR.png","cd":"110/100/90","cost":"100","range":"260"}},"Jayce":{"title":"the Defender of Tomorrow","passive":{"name":"Hextech Capacitor","desc":"Innate: Whenever Jayce switches between either Hammer Stance or Cannon Stance, he gains ghosting and 40 bonus movement speed for 0.75 seconds.","img":"Jayce_Passive.png"},"Q":{"name":"To the Skies! / Shock Blast","desc":"Active: Jayce leaps to the target enemy's location over 0.5 seconds. Upon arrival, he smashes his hammer to the ground to deal physical damage to all enemies within an area and slow them for 2 seconds. Lightning Field can be cast during the dash.","img":"JayceToTheSkies.png","cd":"16/14/12/10/8/6","cost":"40","range":"600"},"W":{"name":"Lightning Field / Hyper Charge","desc":"Passive: Jayce's basic attacks restore mana on-hit. Active: Jayce surrounds himself with an electric field for 4 seconds that deals magic damage every second to nearby enemies.","img":"JayceStaticField.png","cd":"10","cost":"40","range":"285"},"E":{"name":"Thundering Blow / Acceleration Gate","desc":"Active: Jayce roots the target enemy over the cast time, then swings his hammer at them to deal magic damage, capped against monsters, and knock them back 600 units. Jayce is unable to cast To the Skies! or Shock Blast for 0.4 seconds after Thundering Blow's cast time.","img":"JayceThunderingBlow.png","cd":"20/18/16/14/12/10","cost":"55","range":"240"},"R":{"name":"Mercury Cannon / Mercury Hammer","desc":"Active: Jayce transforms into Cannon Stance, receiving access to its abilities, becoming ranged with 500 attack range, and empowering his next basic attack to reduce the target's armor and magic resistance by 10 / 15 / 20 / 25% (based on level) for 5 seconds. Jayce begins the game with Transform but cannot increase its rank. Instead, his basic abilities each have 6 ranks.","img":"JayceStanceHtG.png","cd":"6","cost":"0","range":"600"}},"Jhin":{"title":"the Virtuoso","passive":{"name":"Whisper","desc":"Innate - Death In 4 Acts: Jhin's basic attacks consume ammunition within 4 rounds. He will reload over 2.5 seconds immediately after expending all rounds or withholding leftover rounds after 10 seconds of being out of combat and not being affected by crowd control. The latter reload can be interrupted by declaring an attack or casting an ability.","img":"Jhin_P.png"},"Q":{"name":"Dancing Grenade","desc":"Active: Jhin throws a grenade at the target enemy that deals physical damage and can bounce to up to three additional nearby enemies, prioritizing the closest enemy that has not been hit. The grenade's damage is increased by 35% any time an enemy dies by any means after being hit by the grenade before it strikes its next target.","img":"JhinQ.png","cd":"7/6.5/6/5.5/5","cost":"40/45/50/55/60","range":"550"},"W":{"name":"Deadly Flourish","desc":"Passive: Enemy champions that trigger a Lotus Trap to bloom or are damaged by Jhin or allied champions are marked for 4 seconds. Active: Jhin fires a shot in the target direction that deals physical damage to all enemies in a line until colliding with an enemy champion, reduced by 25% against minions. Hitting a marked champion roots them for a duration and grants Jhin Every Moment Matters' bonus movement speed.","img":"JhinW.png","cd":"12","cost":"50/55/60/65/70","range":"3000"},"E":{"name":"Captive Audience","desc":"Passive - Beauty in Death: Whenever Jhin kills an enemy champion, he summons a Blooming Lotus Trap on their corpse. Active: Jhin places a Lotus Trap at the target location which, upon landing, becomes stealthed after arming over 1 second, lasting for up to 180 seconds and granting sight within its radius. The Lotus Trap blooms upon enemy contact, with enemies in the area at the time of its trigger becoming revealed for 4 seconds.","img":"JhinE.png","cd":"2","cost":"30","range":"750"},"R":{"name":"Curtain Call","desc":"Active: Jhin channels for up to 10 seconds, transforming his weapon into a cannon and gaining the ability to recast Curtain Call 4 times within the duration.","img":"JhinR.png","cd":"120/105/90","cost":"100","range":"25000"}},"Jinx":{"title":"the Loose Cannon","passive":{"name":"Get Excited!","desc":"Innate: Whenever Jinx scores a takedown against an enemy champion, epic monster, turret, or inhibitor within 3 seconds of damaging them, she gains 175% bonus movement speed decaying over 6 seconds. Additionally, she is allowed to exceed the attack speed cap and gains a stack of Get Excited! for the same duration, stacking up to 5 times. Only takedowns against enemy champions can grant stacks beyond the first.","img":"Jinx_Passive.png"},"Q":{"name":"Switcheroo!","desc":"Toggle: Jinx switches between Pow-Pow, her minigun, and Fishbones, her rocket launcher. Pow-Pow: Basic attacks with Pow-Pow generate a stack of Rev'd up for 2.5 seconds, refreshing on subsequent attacks with Pow-Pow and stacking up to 3 times. Each stack of Rev'd up grants bonus attack speed, with all stacks beyond the first one being 50% effective. Stacks expire by one when the duration ends.","img":"JinxQ.png","cd":"0.9","cost":"20","range":"600"},"W":{"name":"Zap!","desc":"Active: Jinx fires a shock blast in the target direction that deals physical damage to the first enemy it hits and reveals and slows them for 2 seconds.","img":"JinxW.png","cd":"8/7/6/5/4","cost":"40/45/50/55/60","range":"1450"},"E":{"name":"Flame Chompers!","desc":"Active: Jinx tosses out 3 Chompers centered at the target location, landing after 0.4 seconds, arming after 0.75 seconds, and exploding after 5 seconds to deal magic damage to nearby enemies. Each Chomper explodes on contact with an enemy champion, knocking them down and rooting them for 1.5 seconds. Enemy champions can be affected by only one Chomper. Flame Chompers! will cast at max range if cast beyond that.","img":"JinxE.png","cd":"24/20.5/17/13.5/10","cost":"90","range":"925"},"R":{"name":"Super Mega Death Rocket!","desc":"Active: Jinx fires a massive rocket in the target direction, briefly granting sight of its surroundings and exploding upon colliding with an enemy champion. The explosion deals physical damage to nearby enemies and grants sight of the area for 2 seconds. Super Mega Death Rocket! deals 10%–100% (based on distance traveled) damage. This does not affect the bonus damage based on the target's missing health.","img":"JinxR.png","cd":"85/65/45","cost":"100","range":"25000"}},"KSante":{"title":"the Pride of Nazumah","passive":{"name":"Dauntless Instinct","desc":"Innate: K'Sante's abilities mark enemies hit for 4 seconds. His basic attacks against marked enemies are empowered to consume the mark on-hit, dealing 12 (+ 1%–2% (based on level) of target's maximum health) bonus physical damage. The health-based portion deals a minimum of 15–100 (based on level) damage against minions and 20–105 (based on level) against monsters.","img":"Icons_KSante_P.png"},"Q":{"name":"Ntofo Strikes","desc":"Active: K'Sante slams his ntofo down in the target direction that deals physical damage to enemies hit and slows them by 80% for 0.5 seconds. If this hits at least one enemy, K'Sante generates a stack for 6 seconds, stacking up to 2 times and refreshing on subsequent hits. At 2 stacks, the next Ntofo Strikes consumes them all to become empowered with a new effect.","img":"KSanteQ.png","cd":"3.5","cost":"20","range":"450"},"W":{"name":"Path Maker","desc":"Active: K'Sante raises his ntofos defensively and prepares to dash in the target direction, charging for a minimum of 0.4 seconds and up to 1 second. During this time, he gains displacement immunity and 30% damage reduction; additionally, Path Maker's range, stun duration, and All Out bonus true damage modifier increase over the first 0.9 seconds of the channel.","img":"KSanteW.png","cd":"14/13/12/11/10","cost":"40/45/50/55/60","range":"600"},"E":{"name":"Footwork","desc":"Active: K'Sante dashes to the target location, though not through terrain, and grants himself a shield for 2 seconds. Footwork can also be cast on allies with increased range and speed, and the ability to dash through terrain. If the target ally is a champion, they receive the shield as well. All Out Bonus: Footwork's dash speed is increased, and its cooldown is reduced by 50%.","img":"KSanteE.png","cd":"10/9.5/9/8.5/8","cost":"45/50/55/60/65","range":"525"},"R":{"name":"All Out","desc":"Active: K'Sante roots the target enemy champion for 0.5 seconds and gains displacement immunity over the cast time. He then shatters his ntofos, pulling the target to a location that is 300 units in the cast direction from their location at the time of cast, during which they are revealed, and blinking 175 units behind that location. The target is dealt physical damage near the end of the displacement and is stunned for 0.3 seconds once it ends.","img":"KSanteR.png","cd":"120/100/80","cost":"100","range":"250"}},"Kaisa":{"title":"Daughter of the Void","passive":{"name":"Second Skin","desc":"Innate - Living Weapon: Kai'Sa can evolve each of her basic abilities by gaining a set amount of permanent stats from items and stat growth, granting them additional effects. Evolving an ability causes her to enter a 2-second cast time. The upgrade is lost if the stat requirement is no longer met.","img":"Kaisa_Passive.png"},"Q":{"name":"Icathian Rain","desc":"Active: Kai'Sa releases a swarm of 6 missiles that evenly distributes among nearby visible enemies, each one hitting their target after 0.4 seconds to deal physical damage. Minions below 35% health take double damage. Non-minions take 25% damage from missiles beyond their first.","img":"KaisaQ.png","cd":"10/9/8/7/6","cost":"55","range":"600"},"W":{"name":"Void Seeker","desc":"Active: Kai'Sa fires a void bolt in the target direction that briefly grants sight around its trajectory as it travels, deals magic damage to the first enemy hit, applies 2 Plasma, and reveals them for 4 seconds. Evolution: Requires 100 ability power from items to upgrade: Void Seeker applies 3 Plasma instead and refunds 75% of its cooldown if it hits an enemy champion.","img":"KaisaW.png","cd":"20/18.5/17/15.5/14","cost":"55/60/65/70/75","range":"3000"},"E":{"name":"Supercharge","desc":"Active: Kai'Sa charges up over the cast time, during which she is still able to move, becoming ghosted and gaining bonus movement speed for the duration, with the effectiveness increased by 0%–100% (based on bonus attack speed). After completing the charge, she gains bonus attack speed and reduces her basic attack windup percentage by 6.44% for 4 seconds. Supercharge's current cooldown is reduced by 0.5 seconds on-attack.","img":"KaisaE.png","cd":"16/14.5/13/11.5/10","cost":"30","range":"1"},"R":{"name":"Killer Instinct","desc":"Active: Kai'Sa grants herself a shield for 2 seconds and dashes to a target location near a visible enemy champion that was affected by Plasma within the last 4 seconds. The shield's duration is refreshed when the dash ends. An enemy champion within range and affected by Plasma is required to cast this ability. Killer Instinct resets Kai'Sa's basic attack timer. Kai'Sa can cast any of her abilities during the dash.","img":"KaisaR.png","cd":"130/100/70","cost":"100","range":"2000/2500/3000"}},"Kalista":{"title":"the Spear of Vengeance","passive":{"name":"Martial Poise","desc":"Innate: Whenever Kalista inputs a movement command during her basic attack windup or the cast time of Pierce, she will dash a short distance in the direction of the inputted location.Kalista cannot dash while immobilized or grounded, and she will be knocked down by any immobilizing or polymorphing crowd control during the dash.","img":"Kalista_Passive.png"},"Q":{"name":"Pierce","desc":"Active: Kalista launches a spear in the target direction that deals physical damage to the first enemy hit. If Pierce kills the target, the spear continues onward to transfer all of the target's Rend stacks to the next enemy it hits. This can repeat indefinitely until the spear reaches its maximum range.","img":"KalistaMysticShot.png","cd":"9","cost":"60/65/70/75/80","range":"1150"},"W":{"name":"Sentinel","desc":"Passive - Soul-Marked: While Kalista and her Oathsworn are tethered, their basic attacks and Pierce apply a Soul-Mark to the target hit for 4 seconds. If both Kalista's and the Oathsworn's Soul-Mark are applied to the same enemy, the marks are consumed to deal magic damage to the target, capped against non-champions. Soul-Mark cannot affect an enemy more than once every few seconds.","img":"KalistaW.png","cd":"30","cost":"0","range":"5000"},"E":{"name":"Rend","desc":"Passive: Kalista's basic attacks on-hit and Pierce apply a stack of Rend to enemies for 4 seconds, refreshing on subsequent hits and stacking up to 254 times. Active: Kalista rips all lodged spears from nearby enemies, consuming all of their stacks to deal them physical damage and slow them for 2 seconds. Each additional spear on the target deals reduced damage. Rend deals 50% damage against epic monsters.","img":"KalistaExpungeWrapper.png","cd":"0","cost":"30","range":"1000"},"R":{"name":"Fate's Call","desc":"Active: Kalista invokes her tether to retrieve and hold her Oathsworn for 4 seconds. Kalista cleanses the Oathsworn from all crowd control and renders them invulnerable and untargetable for the duration, and pulls them to her over 1 second.","img":"KalistaRx.png","cd":"160/140/120","cost":"100","range":"1000"}},"Karma":{"title":"the Enlightened One","passive":{"name":"Gathering Fire","desc":"Innate: Mantra's current cooldown is reduced by 4 seconds for each enemy champion hit by Karma's damaging abilities.","img":"Karma_Passive.png"},"Q":{"name":"Inner Flame","desc":"Active: Karma fires a bolt in the target direction that explodes on the first enemy hit, dealing magic damage to nearby enemies and slowing them by 40% for 1.5 seconds.","img":"KarmaQ.png","cd":"9/8/7/6/5","cost":"40/50/60/70/80","range":"950"},"W":{"name":"Focused Resolve","desc":"Active: Karma deals magic damage to the target enemy champion or monster and forms a tether between her and them for 2 seconds, during which they are revealed. If the tether is not broken by the end of its duration, the target is dealt the same magic damage again and is rooted for a duration, during which they are revealed.","img":"KarmaSpiritBind.png","cd":"12","cost":"50/55/60/65/70","range":"675"},"E":{"name":"Inspire","desc":"Active: Karma grants a shield to herself or the target allied champion for 2.5 seconds as well as 40% bonus movement speed for 2 seconds.","img":"KarmaSolKimShield.png","cd":"10/9.5/9/8.5/8","cost":"60/65/70/75/80","range":"800"},"R":{"name":"Mantra","desc":"Active: Karma empowers her next basic ability within 8 seconds for an additional effect. Mantra can be used while affected by cast-inhibiting crowd control. Karma begins the game with one rank in Mantra. Her empowered abilities scale based on Mantra's rank.","img":"KarmaMantra.png","cd":"40/38/36/34","cost":"0","range":"1100"}},"Karthus":{"title":"the Deathsinger","passive":{"name":"Death Defied","desc":"Innate: Upon taking fatal damage, Karthus enters a zombie state for 7 seconds, during which he can cast his abilities at no cost. If Defile has been learned, it will remain toggled on for Death Defied's entire duration. Requiem becomes disabled after Death Defied has lasted 4 seconds.","img":"Karthus_Passive.png"},"Q":{"name":"Lay Waste","desc":"Active: Karthus conjures a blast at the target location that detonates after 0.528 seconds to 0.759 seconds, granting sight of the area and dealing magic damage to all enemies within, doubled when only one target is struck. During Death Defied, Lay Waste will cast at maximum range if cast beyond that.","img":"KarthusLayWasteA1.png","cd":"0","cost":"20/25/30/35/40","range":"875"},"W":{"name":"Wall of Pain","desc":"Active: Karthus erects a wall of pain at the target location perpendicular to his facing that lasts 5 seconds, granting sight around its pillars and center. Enemies that touch the wall are inflicted with 25% magic resistance reduction and become slowed for 5 seconds, decaying over the duration. This can affect enemies only once per cast.","img":"KarthusWallOfPain.png","cd":"15","cost":"70","range":"1000"},"E":{"name":"Defile","desc":"Passive: Karthus restores mana whenever he kills an enemy. Toggle: Karthus surrounds himself in a necrotic aura that deals magic damage every 0.25 seconds to all nearby enemies. Toggling Defile off triggers a final tick of damage. Defile cannot be toggled off during Death Defied.","img":"KarthusDefile.png","cd":"0.5","cost":"30/42/54/66/78","range":"550"},"R":{"name":"Requiem","desc":"Active: Karthus channels for 3 seconds, then deals magic damage to all targetable enemy champions upon completion.","img":"KarthusFallenOne.png","cd":"200/180/160","cost":"100","range":"10000"}},"Kassadin":{"title":"the Void Walker","passive":{"name":"Void Stone","desc":"Innate: Kassadin is permanently ghosted and takes 10% reduced magic damage.","img":"Kassadin_Passive.png"},"Q":{"name":"Null Sphere","desc":"Active: Kassadin fires an orb of void energy at the target enemy that deals magic damage and disrupts their ongoing channels. He also gains a shield that absorbs magic damage for 1.5 seconds.","img":"NullLance.png","cd":"9/8.5/8/7.5/7","cost":"60/65/70/75/80","range":"650"},"W":{"name":"Nether Blade","desc":"Passive: Kassadin's basic attacks deal 20 (+ 10% AP) bonus magic damage on-hit. Active: Kassadin empowers his next basic attack within 5 seconds to have an uncancellable windup, gain 50 bonus range, deal increased bonus magic damage, and restore mana, with the restoration amount quintupled against champions. Nether Blade resets Kassadin's basic attack timer.","img":"NetherBlade.png","cd":"7","cost":"1","range":"1"},"E":{"name":"Force Pulse","desc":"Passive: Each time Kassadin or a nearby champion casts an ability, Force Pulse's current cooldown is reduced by 0.75 seconds. Active: Kassadin emits a pulse of void energy in a cone in the target direction that deals magic damage to enemies hit and slows them for 1 second.","img":"ForcePulse.png","cd":"21/20/19/18/17","cost":"60/65/70/75/80","range":"400"},"R":{"name":"Riftwalk","desc":"Active: Kassadin blinks toward the target location, dealing magic damage to all nearby enemies upon arrival. He then gains a stack of Riftwalk for 15 seconds, refreshing on subsequent casts and stacking up to 4 times. Riftwalk: For each stack, Riftwalk deals bonus magic damage at an increased mana cost. Riftwalk will cast at max range if cast beyond that.","img":"RiftWalk.png","cd":"5/3.5/2","cost":"40","range":"500"}},"Katarina":{"title":"the Sinister Blade","passive":{"name":"Voracity","desc":"Innate: Scoring a champion takedown within 3 seconds of damaging them will reduce the current cooldowns of Katarina's abilities by 15 seconds.","img":"Katarina_Passive.png"},"Q":{"name":"Bouncing Blade","desc":"Active: Katarina throws a Dagger at the target enemy that deals magic damage and can bounce to up to two additional nearby enemies. The Dagger then lands onto the ground after 1 second, about 350 units opposite from where it struck the first target. The target does not have to be visible for the Dagger to bounce to them.","img":"KatarinaQ.png","cd":"11/10/9/8/7","cost":"0","range":"625"},"W":{"name":"Preparation","desc":"Active: Katarina tosses a Dagger into the air above her current location and gains bonus movement speed that decays until it lands after 1.25 seconds, becoming ghosted for the same duration.","img":"KatarinaW.png","cd":"15/14/13/12/11","cost":"0","range":"25000"},"E":{"name":"Shunpo","desc":"Active: Katarina blinks to the target location around the target unit or Dagger, dealing magic damage to the nearest enemy in range and applying on-hit effects. Shunpo resets Katarina's basic attack timer. Upon blinking, Katarina enters a 0.15-second cast time.","img":"KatarinaEWrapper.png","cd":"12/11/10/9/8","cost":"0","range":"725"},"R":{"name":"Death Lotus","desc":"Active: Katarina channels for up to 2.5 seconds, rapidly throwing a dagger every 0.166 seconds to up to 3 of the closest nearby enemy champions, revealing herself in the process.Each dagger deals physical damage and magic damage, applies on-hit effects, with on-hit damage reduced in effectiveness, triggers on-attack effects, and inflicts Grievous Wounds on the target for 3 seconds.","img":"KatarinaR.png","cd":"75/60/45","cost":"0","range":"550"}},"Kayle":{"title":"the Righteous","passive":{"name":"Divine Ascent","desc":"Innate: Kayle ascends through four forms that each grant additional bonuses. She ascends upon spending a skill point at levels 1, 6, 11, and 16.","img":"Kayle_P.png"},"Q":{"name":"Radiant Blast","desc":"Active: Kayle conjures a portal in front of her that faces the target direction, from which a celestial sword launches forward. The sword expands upon hitting an enemy, targets struck in the area are dealt magic damage, slowed for 2 seconds, and inflicted with 15% reduced armor and magic resistance for 4 seconds.","img":"KayleQ.png","cd":"12/11/10/9/8","cost":"60/70/80/90/100","range":"900"},"W":{"name":"Celestial Blessing","desc":"Active: Kayle and the target allied champion are healed and gain bonus movement speed for 2 seconds. If cast without a valid target, or self-cast, Celestial Blessing will automatically target the closest allied champion in range, prioritizing the one with the lowest health.","img":"KayleW.png","cd":"15","cost":"70/75/80/85/90","range":"900"},"E":{"name":"Starfire Spellblade","desc":"Passive: Kayle deals bonus magic damage on-hit. Active: Kayle kindles her blade, empowering her next basic attack within 6 seconds to have an uncancellable windup and deal additional bonus magic damage on-hit that is capped at 400 against monsters. If Kayle is not yet Arisen, this attack becomes ranged with 525 range.","img":"KayleE.png","cd":"8/7.5/7/6.5/6","cost":"0","range":"550"},"R":{"name":"Divine Judgment","desc":"Active: Kayle grants herself or a target allied champion invulnerability for 2.5 seconds and conjures swords of fire. After 2.5 seconds, she rains the swords down around the target, dealing magic damage to nearby enemies.","img":"KayleR.png","cd":"160/120/80","cost":"100/50/0","range":"900"}},"Kayn":{"title":"the Shadow Reaper","passive":{"name":"The Darkin Scythe","desc":"Innate: Kayn has a secondary experience bar that tracks progress toward his Darkin and Shadow Assassin forms. He gathers orbs from champion takedowns and each instance of damage (excluding damage over time) dealt against champions. Once he has earned enough orbs, he unlocks a form based on whether he earned more from melee or ranged champions (for Darkin and Shadow Assassin, respectively), with the other form unlocked later.","img":"Kayn_Passive_Primary.png"},"Q":{"name":"Reaping Slash","desc":"Active: Kayn dashes in the target direction, dealing physical damage to enemies he passes through. He then swings his scythe, dealing the same damage to nearby enemies. Both instances of Reaping Slash deal 40 bonus physical damage against minions and monsters.","img":"KaynQ.png","cd":"7/6.5/6/5.5/5","cost":"40","range":"350"},"W":{"name":"Blade's Reach","desc":"Active: Kayn swings his scythe in the target direction, dealing physical damage to enemies hit and slowing them by 90% decaying over 1.5 seconds. Shadow Assassin Bonus: Blade's Reach's radius is extended by 200 units. Kayn conjures an untargetable shadow at the casting position to perform Blade's Reach's sweep over 0.55 seconds in his stead, removing the ability's cast time. Darkin Bonus: Blade's Reach knocks up enemies hit for 1 second.","img":"KaynW.png","cd":"13/12/11/10/9","cost":"40/45/50/55/60","range":"700"},"E":{"name":"Shadow Step","desc":"Active: Kayn gains 40% bonus total movement speed, ghosting and the ability to ignore terrain collision for a duration. If he has been in combat with enemy champions within the last 3 seconds, Shadow Step will instead last 1.5 seconds. Kayn heals himself upon entering terrain for the first time from casting Shadow Step and he gains unobstructed vision while inside.","img":"KaynE.png","cd":"21/19/17/15/13","cost":"90","range":"400"},"R":{"name":"Umbral Trespass","desc":"Passive: Kayn marks enemy champions he damaged in the last 3.15 seconds.","img":"KaynR.png","cd":"120/100/80","cost":"100","range":"550"}},"Kennen":{"title":"the Heart of the Tempest","passive":{"name":"Mark of the Storm","desc":"Innate: Kennen's abilities apply a stack of Mark of the Storm to enemies hit for 6 seconds, refreshing on subsequent applications and stacking up to 3 times. The third stack against a target consumes them all to stun them for 1.25 seconds and restore 25 energy. The stun duration is reduced to 0.5 seconds if this occurs on the same target again within 6 seconds. Slicing Maelstrom can apply only up to 3 stacks on a target.","img":"Kennen_Passive.png"},"Q":{"name":"Thundering Shuriken","desc":"Active: Kennen throws a shuriken in the target direction that deals magic damage to the first enemy hit.","img":"KennenShurikenHurlMissile1.png","cd":"7/6.25/5.5/4.75/4","cost":"60/55/50/45/40","range":"950"},"W":{"name":"Electrical Surge","desc":"Passive: Kennen's basic attacks on-attack generate a stack of Electrical Surge, stacking up to 4 times. At 4 stacks, his next basic attack on-attack is empowered to consume all stacks on-hit to deal bonus magic damage and apply a stack of Mark of the Storm.Kennen gains maximum stacks of Electrical Surge upon respawning.","img":"KennenBringTheLight.png","cd":"13/11.25/9.5/7.75/6","cost":"40","range":"725"},"E":{"name":"Lightning Rush","desc":"Active: Kennen turns into lightning for 2 seconds, becoming unable to declare basic attacks but gaining ghosting and 100% bonus movement speed. He deals magic damage to enemies he passes through, reduced to 65% against non-champions, and restores 40 energy upon damaging at least one enemy. Lightning Rush can be recast after 0.5 seconds, and does so automatically after the duration.","img":"KennenLightningRush.png","cd":"10/9/8/7/6","cost":"80","range":"170"},"R":{"name":"Slicing Maelstrom","desc":"Active: Kennen summons a storm around himself for 3 seconds, gaining bonus armor and bonus magic resistance for the duration. The storm strikes lightning bolts down on nearby enemies every 0.5 seconds, each one dealing magic damage. Slicing Maelstrom gains 10% additional damage for each subsequent strike a target has received, up to a combined total of 150% of the initial strike's damage.","img":"KennenShurikenStorm.png","cd":"120","cost":"0","range":"550"}},"Khazix":{"title":"the Voidreaver","passive":{"name":"Unseen Threat","desc":"Innate: Kha'Zix gains Unseen Threat whenever the enemy loses sight of him or he activates Void Assault. Unseen Threat: Kha'Zix empowers his next basic attack against an enemy champion to deal 17–136 (based on level) (+ 50% bonus AD) bonus magic damage and slow them by 25% for 2 seconds.","img":"Khazix_P.png"},"Q":{"name":"Taste Their Fear","desc":"Passive: Kha'Zix considers any enemy unit to be Isolated if they are not nearby to one of their allies. Taste Their Fear, Evolved Reaper Claws, and Evolved Spike Racks have special interactions against Isolated targets. Active: Kha'Zix slashes the target enemy, dealing physical damage, increased by 110% against Isolated targets.","img":"KhazixQ.png","cd":"4","cost":"20","range":"325"},"W":{"name":"Void Spike","desc":"Active: Kha'Zix fires a bolt of spikes in the target direction that explodes upon hitting an enemy, dealing physical damage to nearby enemies. Kha'Zix heals himself if he is within the explosion.","img":"KhazixW.png","cd":"9","cost":"55/60/65/70/75","range":"1000"},"E":{"name":"Leap","desc":"Active: Kha'Zix leaps to the target location, dealing physical damage to nearby enemies upon arrival. Taste Their Fear can be cast during the dash. Leap will cast at max range if cast beyond that.","img":"KhazixE.png","cd":"20/18/16/14/12","cost":"50","range":"700"},"R":{"name":"Void Assault","desc":"Passive: Each rank in Void Assault allows Kha'Zix to evolve one of his abilities, granting it additional effects. Evolving an ability causes him to enter a 2-second cast time. Kha'Zix cannot evolve while he is unable to cast abilities. Active: Kha'Zix becomes invisible for 1.25 seconds, during which he gains 40% bonus movement speed.","img":"KhazixR.png","cd":"100/85/70","cost":"100","range":"25000"}},"Kindred":{"title":"The Eternal Hunters","passive":{"name":"Mark of the Kindred","desc":"Innate: Both Lamb and Wolf mark targets to hunt. Scoring a takedown against a hunted target collects a stack of Mark of the Kindred. Mark of the Kindred: Lamb gains 75–250 (based on marks) bonus range on her basic attacks and Mounting Dread.","img":"Kindred_Passive.png"},"Q":{"name":"Dance of Arrows","desc":"Active: Lamb dashes toward the target location, gaining 35% (+ 5% per mark) bonus attack speed for 4 seconds and firing an arrow at up to 3 nearby visible enemies that deals physical damage. Her current attack target within any proximity will be prioritized by one of the arrows.","img":"KindredQ.png","cd":"9","cost":"35","range":"340"},"W":{"name":"Wolf's Frenzy","desc":"Passive: As Kindred move and attack, they build up to 100 stacks of Hunter's Vigor. At maximum stacks, Lamb's next basic attack heals her for 0%–100% (based on Kindred's missing health) of 47–81 (based on level). The heal is not triggered if Kindred is at full health.","img":"KindredW.png","cd":"18/17/16/15/14","cost":"40","range":"560"},"E":{"name":"Mounting Dread","desc":"Active: Lamb fires a shot at the target enemy that slows them by 30% (+ 5% per 100 AP) for 1 second and marks them for 4 seconds. Her basic attacks against the marked target each apply a stack, refreshing the duration and stacking up to 3 times. The third stack directs Wolf to pounce on the target, consuming all stacks to deal additional physical damage, capped at 300 against monsters.","img":"KindredEWrapper.png","cd":"14/12.5/11/9.5/8","cost":"0","range":"500"},"R":{"name":"Lamb's Respite","desc":"Active: Lamb blesses the ground underneath herself and enters a 0.264 seconds cast time, creating a sacred zone at her location at the time of cast that lasts for 4 seconds. All units inside the zone gain a minimum health threshold equal to 10% of their maximum health, and will also become invulnerable while remaining in the area when they reach or are at the threshold, during which they also cannot be healed, but can still regenerate health.","img":"KindredR.png","cd":"160/140/120","cost":"100","range":"500"}},"Kled":{"title":"the Cantankerous Cavalier","passive":{"name":"Skaarl, the Cowardly Lizard","desc":"Innate: Kled rides his semi-trusty mount, Skaarl. While Mounted, all damage dealt to the duo is suffered by Skaarl, who has 400–1550 (based on level) base health; additional sources of health are applied to Skaarl's maximum health. Effects based on percentage health consider Kled and Skaarl's combined maximum health.","img":"Kled_P.png"},"Q":{"name":"Bear Trap on a Rope","desc":"Active: Kled throws a bear trap in the target direction that deals physical damage to enemies hit, increased by 50% against minions and small monsters. The bear trap collides against the first enemy champion, large pet or large monster hit, forming a tether between Kled and the target for 1.75 seconds, during which they are revealed.","img":"KledQ.png","cd":"11/10/9/8/7","cost":"0","range":"800"},"W":{"name":"Violent Tendencies","desc":"Passive: Kled periodically gains Violent Tendencies, which starts expiring upon his next basic attack. Violent Tendencies: Kled gains 150% bonus attack speed on his next 4 basic attacks within 4 seconds. The fourth attack deals bonus physical damage, capped against monsters. Against structures, the fourth attack deals modified bonus physical damage.","img":"KledW.png","cd":"13/12/11/10/9","cost":"0","range":"0"},"E":{"name":"Jousting","desc":"Active: Skaarl dashes in the target direction, though not through terrain, dealing physical damage to enemies he passes through and pulling minions and small monsters hit towards them.","img":"KledE.png","cd":"13/12/11/10/9","cost":"0","range":"550"},"R":{"name":"Chaaaaaaaarge!!!","desc":"Active: Kled & Skaarl charge toward the target location, automatically navigating terrain along the way, during which they're ghosted, immune to crowd control and revealed to enemy champions in a 1250 radius. If the charge does not complete within 15 seconds, it will end prematurely. The charge is interrupted instantly if Kled dismounts during it.","img":"KledR.png","cd":"140/125/110","cost":"0","range":"3500/4000/4500"}},"KogMaw":{"title":"the Mouth of the Abyss","passive":{"name":"Icathian Surprise","desc":"Innate: Upon taking fatal damage, Kog'Maw enters a zombie state for 4 seconds, becoming ghosted and gaining 10% bonus movement speed that increases up to 50% over the duration. At the end of the duration, he explodes to deal 140–650 (based on level) true damage to nearby enemies.","img":"KogMaw_IcathianSurprise.png"},"Q":{"name":"Caustic Spittle","desc":"Passive: Kog'Maw gains bonus attack speed. Active: Kog'Maw ejects a wad of spittle in the target direction that deals magic damage to the first enemy hit and reduces their armor and magic resistance for 4 seconds.","img":"KogMawQ.png","cd":"7","cost":"40","range":"1175"},"W":{"name":"Bio-Arcane Barrage","desc":"Active: Kog'Maw empowers his basic attacks for the next 8 seconds to gain bonus attack range and deal bonus magic damage on-hit, capped at 100 against minions and monsters.","img":"KogMawBioArcaneBarrage.png","cd":"17","cost":"40","range":"530"},"E":{"name":"Void Ooze","desc":"Active: Kog'Maw spews a gob of ooze in the target direction that deals magic damage to enemies hit. A field of ooze is created in its wake for 3 seconds, slowing enemies every 0.25 seconds.","img":"KogMawVoidOoze.png","cd":"12","cost":"40/55/70/85/100","range":"1200"},"R":{"name":"Living Artillery","desc":"Active: Kog'Maw spits a globule of acid into the air that drops to the target location after 0.6 seconds, granting sight of the area before dealing magic damage to enemies hit and revealing them for 2 seconds. Living Artillery's damage is increased by 0%–50% (based on target's missing health), or instead by 100% if the target is below 40% maximum health.","img":"KogMawLivingArtillery.png","cd":"2/1.5/1","cost":"40","range":"1300/1550/1800"}},"Leblanc":{"title":"the Deceiver","passive":{"name":"Mirror Image","desc":"Innate: Periodically, when LeBlanc is damaged to 40% maximum health, she creates a clone of herself, after which they both instantly become invisible for 1 second. The clone can cast basic attacks with no effect and lasts 8 seconds. Upon spawning, it starts moving up to 1900 units toward a random direction in front of LeBlanc's movement, determined at the moment of its spawning. See Pets for more details about LeBlanc's clone.","img":"LeblancP.png"},"Q":{"name":"Sigil of Malice","desc":"Active: LeBlanc projects an orb at the target enemy that deals magic damage and marks them for 3.5 seconds. LeBlanc's next damaging ability against the marked target will consume the mark to deal the same magic damage again.","img":"LeblancQ.png","cd":"6","cost":"50","range":"700"},"W":{"name":"Distortion","desc":"Active: LeBlanc dashes to the target location, dealing magic damage to all nearby enemies upon arrival and leaving a return pad at the cast location for 4 seconds. Distortion can be recast after 0.2 seconds of the dash ending for the pad's duration. Recast: LeBlanc blinks to Distortion's return pad, regardless of range. Distortion will cast at max range if cast beyond that.","img":"LeblancW.png","cd":"15/13.75/12.5/11.25/10","cost":"60/70/80/90/100","range":"600"},"E":{"name":"Ethereal Chains","desc":"Active: LeBlanc flings an illusory chain in the target direction that deals magic damage to the first enemy it hits and forms a tether between LeBlanc and the target for 1.5 seconds, during which they are revealed. If the tether is not broken by the end of its duration, it fractures to deal magic damage to the target and root them for 1.5 seconds, during which they are revealed.","img":"LeblancE.png","cd":"14/13.25/12.5/11.75/11","cost":"50","range":"925"},"R":{"name":"Mimic","desc":"Active: LeBlanc casts a mimicked version of her most recently used basic ability, applying the same effects and dealing modified magic damage. Mimic: Sigil of Malice: The orb deals modified damage, while the mark consumption deals double that amount. Mimic: Distortion: Deals modified damage. Mimic: Ethereal Chains: The tether's application deals modified damage, while its fracturing deals double that amount.","img":"LeblancR.png","cd":"45/35/25","cost":"0","range":"25000"}},"LeeSin":{"title":"the Blind Monk","passive":{"name":"Flurry","desc":"Innate: After casting an ability, Lee Sin's next 2 basic attacks within 3 seconds gain 40% bonus attack speed and restore energy. The first attack restores 20 / 30 / 40 (based on level) energy and the second attack restores[ 10 / 15 / 20 (based on level) energy. ][ half of the previous amount. ]","img":"LeeSinPassive.png"},"Q":{"name":"Sonic Wave / Resonating Strike","desc":"Active: Lee Sin fires a sonic blast in the target direction that deals physical damage to the first enemy hit and marks them for 3 seconds, during which they are revealed. While the target is marked, Lee Sin can cast Resonating Strike.","img":"LeeSinQOne.png","cd":"10/9/8/7/6","cost":"50","range":"1100"},"W":{"name":"Safeguard / Iron Will","desc":"Active: Lee Sin dashes to the target allied unit's location. If the ally is a champion upon arrival, both they and Lee Sin gain a shield for 2 seconds and Safeguard's cooldown is halved. Lee Sin can self-cast Safeguard to shield himself. After Safeguard is cast, Lee Sin can cast Iron Will within the next 3 seconds. Iron Will and Cripple can be cast during the dash.","img":"LeeSinWOne.png","cd":"7","cost":"50","range":"700"},"E":{"name":"Tempest / Cripple","desc":"Active: Lee Sin smashes the ground beneath him, dealing magic damage to nearby enemies, marking them for 4 seconds and, if they are not invisible when struck, revealing them for the same duration. If Tempest hits an enemy, Lee Sin can cast Cripple within the next 3 seconds after a 0.1-second delay.","img":"LeeSinEOne.png","cd":"8","cost":"50","range":"450"},"R":{"name":"Dragon's Rage","desc":"Active: Lee Sin roots the target enemy champion over the cast time, then roundhouse kicks them to deal physical damage and knock them back up to 800 units over 0.8 seconds, rendering them airborne for 1 second. Enemies that collide with the displaced enemy while it is airborne take the same damage plus bonus physical damage and are knocked up for 1 second.","img":"LeeSinR.png","cd":"110/85/60","cost":"0","range":"375"}},"Leona":{"title":"the Radiant Dawn","passive":{"name":"Sunlight","desc":"Innate: Leona's abilities mark enemies hit for 2.5 seconds, refreshing on subsequent hits. Allied champions' damaging attacks and abilities against a marked target will consume the mark to deal 32–151 (based on level) bonus magic damage.","img":"LeonaSunlight.png"},"Q":{"name":"Shield of Daybreak","desc":"Active: Leona illuminates her shield, empowering her next basic attack within 6 seconds to have a 0.25-second cast time, gain 50 bonus range, deal bonus magic damage and stun the target for 1 second. Shield of Daybreak resets Leona's basic attack timer.","img":"LeonaShieldOfDaybreak.png","cd":"5","cost":"30/35/40/45/50","range":"100"},"W":{"name":"Eclipse","desc":"Active: Leona raises her guard for 3 seconds, gaining flat damage reduction of up to 50% of the damage instance and bonus armor and bonus magic resistance. Her shield detonates after the duration, dealing magic damage to nearby enemies. If this hits an enemy, Leona's guard is extended for an additional 3 seconds.","img":"LeonaSolarBarrier.png","cd":"14/13/12/11/10","cost":"60","range":"450"},"E":{"name":"Zenith Blade","desc":"Active: Leona projects her sword in the target direction that deals magic damage to enemies hit. If she hits at least one enemy champion, she will dash 225 units behind the last one struck within 3000 range and root them for 0.5 seconds. Leona is unable to move or attack while Zenith Blade is in flight. She can cast any of her abilities during the dash.","img":"LeonaZenithBlade.png","cd":"12/10.5/9/7.5/6","cost":"40/45/50/55/60","range":"875"},"R":{"name":"Solar Flare","desc":"Active: Leona calls down a solar flare that strikes upon the target location after 0.625 seconds, granting sight of the area before impact and for another 3 seconds afterwards. Enemies hit are dealt magic damage. Targets are also slowed by 80% for 1.75 seconds, or stunned for the same duration if they are hit by the epicenter.","img":"LeonaSolarFlare.png","cd":"90/75/60","cost":"100","range":"1200"}},"Lillia":{"title":"the Bashful Bloom","passive":{"name":"Dream-Laden Bough","desc":"Innate: Lillia's abilities apply Dream Dust to enemies hit, which deals[ 5% (+ 1.25% per 100 AP) of the target's maximum health total magic damage over 3 seconds, capped at 65 ][ 0.83% (+ 0.2083% per 100 AP) of the target's maximum health magic damage every 0.5 seconds over 3 seconds, capped at 10.83 per tick ]against monsters.","img":"Lillia_Icon_Passive.png"},"Q":{"name":"Blooming Blows","desc":"Passive: Whenever Lillia's abilities hit at least one enemy, she generates a stack of Prance for 6.5 seconds, refreshing on subsequent hits and stacking up to 4 times. Stacks expire by one every 1.5 seconds when the duration ends. Prance: For each stack, Lillia gains bonus movement speed.","img":"LilliaQ.png","cd":"6/5.5/5/4.5/4","cost":"65","range":"450"},"W":{"name":"Watch Out! Eep!","desc":"Active: Lillia dashes to 150 units in front of the target location over 0.759 seconds, though not through terrain, and deals magic damage in an area around the target spot. Enemies hit within the epicenter are dealt 200% increased damage. Watch Out! Eep! deals 50% damage to minions. Watch Out! Eep! will cast at max range if cast beyond that.","img":"LilliaW.png","cd":"14/13/12/11/10","cost":"50","range":"500"},"E":{"name":"Swirlseed","desc":"Active: Lillia lobs a seed at the target location that rolls forward indefinitely. The seed detonates upon hitting an enemy or terrain while on the ground, dealing magic damage to enemies in a cone, slowing them by 40% for 3 seconds and revealing them for 2 seconds. Swirlseed will cast at max range if cast beyond that.","img":"LilliaE.png","cd":"12","cost":"70","range":"700"},"R":{"name":"Lilting Lullaby","desc":"Active: Lillia casts a magical lullaby over all enemy champions affected by Dream Dust, which arrives after 0.3 seconds and renders them drowsy for 1.5 seconds, slowing them by 10%. After the duration, they fall asleep for 2 seconds. The next instance of non-persistent damage that a sleeping target takes from champions, large monsters or turrets consumes the debuff to deal additional magic damage.","img":"LilliaR.png","cd":"150/130/110","cost":"50","range":"1600"}},"Lissandra":{"title":"the Ice Witch","passive":{"name":"Iceborn Subjugation","desc":"Innate: Whenever a nearby enemy champion dies, Lissandra spawns a Frozen Thrall from their corpse.Frozen Thralls are ice spirits that have 33.48–325 (based on seconds alive) movement speed and slow nearby enemies by 25%. They will chase nearby visible enemies for 4 seconds, prioritizing champions, after which they shatter to deal 120–520 (based on level) (+ 50% AP) magic damage to nearby enemies.","img":"Lissandra_Passive.png"},"Q":{"name":"Ice Shard","desc":"Active: Lissandra launches a shard of ice in the target direction that deals magic damage and slows enemies hit for 1.5 seconds. If Ice Shard hits an enemy, it will shatter, increasing its width and maximum range.","img":"LissandraQ.png","cd":"7/6/5/4/3","cost":"55/60/65/70/75","range":"725"},"W":{"name":"Ring of Frost","desc":"Active: Lissandra freezes nearby enemies, dealing magic damage and rooting them for a duration.","img":"LissandraW.png","cd":"10/9.5/9/8.5/8","cost":"40","range":"450"},"E":{"name":"Glacial Path","desc":"Active: Lissandra sends a claw of ice in the target direction that deals magic damage to enemies it passes through, decelerating over 1.25 seconds. Glacial Path can be recast after 0.5 seconds while the claw is active. Recast: Lissandra consumes the claw and blinks to its current location.","img":"LissandraE.png","cd":"24/21/18/15/12","cost":"80/85/90/95/100","range":"1050"},"R":{"name":"Frozen Tomb","desc":"Active: Lissandra can cast Frozen Tomb on herself or an enemy champion. Enemy Cast: Lissandra freezes the target enemy champion, knocking them down and stunning them for 1.5 seconds. Self Cast: Lissandra instantly entombs herself in ice, entering stasis for 2.5 seconds and healing herself every 0.25 seconds over the duration. The healing is increased by 0%–100% (based on missing health at the time of cast).","img":"LissandraR.png","cd":"120/100/80","cost":"100","range":"550"}},"Locke":{"title":"the Ashen Exorcist","passive":{"name":"Silver Stake","desc":"Locke's attacks deal additional magic damage On-Hit, increased based on enemy missing Health.","img":"Locke_Passive.png"},"Q":{"name":"Ritual Nails","desc":"Locke readies a set of Soul Nails to throw, dealing magic damage and marking enemies hit. Nails apply a // Slow for // seconds, stacking with the amount of nails hit. Attacking the enemy consumes the Soul Nails, dealing magic damage per stack, increased by and for two and three nails respectively.","img":"LockeQ.png","cd":"10/9/8/7/6","cost":"70","range":"950"},"W":{"name":"Soul Ignition","desc":"Locke ignites his own soul, gaining Attack Speed and Move Speed that decays over seconds. for a short time, he suffers current Health true damage per second but Heals back the last damage taken, and an additional Health based on missing Health and time passed, up to a maximum of Health remaining. Can be Recast to end early.","img":"LockeW.png","cd":"18/17/16/15/14","cost":"50/55/60/65/70","range":"250"},"E":{"name":"Ashen Pursuit","desc":"Locke teleports to a location, dealing magic damage to nearby enemies on arrival. On his next Attack, he dashes to his target, dealing magic damage to all enemies in his path. Each hit consumes Soul Nails. If Locke scores a takedown, the Cooldown of this Ability is reset.","img":"LockeE.png","cd":"10","cost":"30/40/50/60/70","range":"425"},"R":{"name":"Purgatory","desc":"Locke throws a binding artifact to a location, dealing magic damage and Slowing enemies in the area by, decaying over seconds. The artifact marks enemies hit for a short time, sealing away marked enemy champions brought below, and resetting the duration of the mark on other affected champions. After the duration ends, if at least one champion was sealed, the artifact lands on the ground. Locke can pick up the artifact to permanently increase its execution threshold by, and refund of his total Cooldown, for each champion sealed.","img":"LockeR.png","cd":"120/100/80","cost":"100","range":"1000"}},"Lucian":{"title":"the Purifier","passive":{"name":"Lightslinger","desc":"Innate: After casting an ability, Lucian's next basic attack within 3.5 seconds fires an additional shot on-attack after 0.25 seconds, which deals 50 / 55 / 60% (based on level) AD physical damage, increased to 100% AD against minions. He will shoot the same target, else another target in range. The second shot applies on-hit effects, triggers on-attack effects, and is affected by critical strike modifiers.","img":"Lucian_Passive.png"},"Q":{"name":"Piercing Light","desc":"Active: Lucian fires a laser in a line in the direction of the target enemy that deals physical damage to enemies hit.","img":"LucianQ.png","cd":"9/8/7/6/5","cost":"48/56/64/72/80","range":"500"},"W":{"name":"Ardent Blaze","desc":"Active: Lucian fires a missile in the target direction that explodes in a cross pattern upon hitting an enemy or reaching maximum range, dealing magic damage to enemies hit and granting sight of the area for 1 second. Enemies hit are marked for 6 seconds. Lucian gains bonus movement speed for 1 second when he or allied champions damage a marked target. Allied champions triggering this effect grant Lucian Vigilance.","img":"LucianW.png","cd":"14/13/12/11/10","cost":"60","range":"900"},"E":{"name":"Relentless Pursuit","desc":"Passive: Relentless Pursuit's current cooldown is reduced by 1 second for each Lightslinger shot hit, doubled to 2 seconds against enemy champions. Active: Lucian dashes in the target direction.","img":"LucianE.png","cd":"16/15.5/15/14.5/14","cost":"32/24/16/8/0","range":"445"},"R":{"name":"The Culling","desc":"Active: Lucian channels for up to 3 seconds, rapidly firing up to 22 (+ 1 per 4% critical strike chance) shots in the target direction. Each shot deals physical damage to the first enemy hit, doubled against minions. The Culling can be recast after 0.75 seconds during the channel, and does so automatically when the channel ends. While channeling, Lucian is ghosted and may still move. Recast: Lucian ends The Culling.","img":"LucianR.png","cd":"110/100/90","cost":"100","range":"1400"}},"Lulu":{"title":"the Fae Sorceress","passive":{"name":"Pix, Faerie Companion","desc":"Innate: Lulu is assisted by Pix, an untargetable faerie, who follows her around and fires a barrage of 3 bolts towards her target whenever she uses a basic attack on-attack. Each bolt deals 5–39 (based on level) (+ 5% AP) magic damage to the first enemy it collides with, for a total of 15–117 (based on level) (+ 15% AP) on hitting a single target with all three bolts.","img":"Lulu_PixFaerieCompanion.png"},"Q":{"name":"Glitterlance","desc":"Active: Lulu and Pix each fire a magic bolt towards the target point, each one dealing magic damage to enemies hit, reduced to 70% against minions, and slowing them by 80% decaying over 2 seconds. Enemies take 50% damage from a second bolt.","img":"LuluQ.png","cd":"7","cost":"50/55/60/65/70","range":"925"},"W":{"name":"Whimsy","desc":"Active: Lulu can cast Whimsy on herself or a champion. Enemy Cast: Lulu launches a spell onto the target enemy champion that polymorphs them into a harmless critter for a duration, during which their base movement speed is reduced by 60, and disarms them for the same duration.","img":"LuluW.png","cd":"18","cost":"65","range":"650"},"E":{"name":"Help, Pix!","desc":"Active: Lulu can cast Help, Pix! on herself or an ally or enemy. Enemy Cast: Lulu sends Pix to the far side of the target enemy for 4 seconds, dealing magic damage and revealing them for the same duration. Self / Ally Cast: Lulu sends Pix to the target ally for 6.25 seconds. If the target is a champion, they are granted a shield for 2.5 seconds.","img":"LuluE.png","cd":"10/9.5/9/8.5/8","cost":"60/65/70/75/80","range":"650"},"R":{"name":"Wild Growth","desc":"Active: Lulu enlarges herself or the target allied champion, knocking up nearby enemies for 1 second. For the next 7 seconds, the target gains bonus health and 40% increased size and slows nearby enemies, which lingers for 0.25 seconds.","img":"LuluR.png","cd":"120/100/80","cost":"100","range":"900"}},"Lux":{"title":"the Lady of Luminosity","passive":{"name":"Illumination","desc":"Innate: Lux's abilities apply a mark to enemies hit for 6 seconds, refreshing on subsequent hits. Lux's basic attacks and Final Spark consume the mark to deal 30–200 (based on level) (+ 30% AP) bonus magic damage.","img":"LuxIlluminatingFraulein.png"},"Q":{"name":"Light Binding","desc":"Active: Lux shoots a sphere of light in the target direction that deals magic damage to the first two enemies hit and roots them for 2 seconds.","img":"LuxLightBinding.png","cd":"10","cost":"50","range":"1175"},"W":{"name":"Prismatic Barrier","desc":"Active: Lux throws her wand in the target direction that homes back to her after reaching maximum range. Allied champions hit by the wand gain a shield for 2.5 seconds, which can stack up to 2 times, stacking with the previous shield and refreshing its duration. Lux receives the shield upon throwing the wand and upon its return.","img":"LuxPrismaticWave.png","cd":"12/11.5/11/10.5/10","cost":"60/65/70/75/80","range":"1150"},"E":{"name":"Lucent Singularity","desc":"Active: Lux sends a lucent singularity to the target location, remaining there for 5 seconds to grant sight of the area and slow nearby enemies. Lucent Singularity can be recast at any time while it is in flight or within the duration, and does so automatically after the duration. Recast: Lux detonates the singularity, dealing magic damage to enemies within. If Lucent Singularity was recast while in flight, it will detonate upon arrival.","img":"LuxLightStrikeKugel.png","cd":"10/9.5/9/8.5/8","cost":"70/80/90/100/110","range":"1100"},"R":{"name":"Final Spark","desc":"Active: Lux fires a massive laser in a line in the target direction that deals magic damage to enemies hit and reveals them for 1.5 seconds, as well as granting sight of the surrounding area.","img":"LuxR.png","cd":"60/50/40","cost":"100","range":"3340"}},"Malphite":{"title":"Shard of the Monolith","passive":{"name":"Granite Shield","desc":"Innate - Shard of the Monolith: Malphite gains increased percentage size equal to 8% of his total armor, capped at 35% increased size at 437.5 armor. Innate: Malphite grants himself a shield equal to 10% of his maximum health. The shield lasts until it is broken, and refreshes after a few seconds of not taking damage.","img":"Malphite_GraniteShield.png"},"Q":{"name":"Seismic Shard","desc":"Active: Malphite sends a shard to the target enemy that deals magic damage and slows them for 3 seconds. Malphite also gains bonus movement speed equal to the raw amount the target lost from the slow for the duration.","img":"SeismicShard.png","cd":"8","cost":"70/75/80/85/90","range":"625"},"W":{"name":"Thunderclap","desc":"Passive: Malphite gains bonus armor, tripled while Granite Shield is active. Active: Malphite empowers his next basic attack within 6 seconds to have an uncancelable windup, gain 50 bonus range, and deal bonus physical damage on-hit. Additionally, Malphite's basic attacks on-hit for the next 5 seconds are empowered to trigger a cone in the direction of the target that deals physical damage to enemies hit.","img":"Obduracy.png","cd":"10/9.5/9/8.5/8","cost":"30/35/40/45/50","range":"400"},"E":{"name":"Ground Slam","desc":"Active: Malphite slams the ground beneath him, dealing magic damage to nearby enemies and crippling them for 3 seconds.","img":"Landslide.png","cd":"7","cost":"50/55/60/65/70","range":"400"},"R":{"name":"Unstoppable Force","desc":"Active: Malphite dashes with displacement immunity to the target location. Upon arrival, he deals magic damage to nearby enemies and knocks them up for 1.5 seconds. Unstoppable Force will cast at max range if cast beyond that.","img":"UFSlash.png","cd":"130/115/100","cost":"100","range":"1000"}},"Malzahar":{"title":"the Prophet of the Void","passive":{"name":"Void Shift","desc":"Innate: Periodically, Malzahar gains Void Shift until he takes non-minion damage or negates a crowd control effect, to which it then lingers for 0.25 seconds before expiring. Void Shift: Malzahar gains crowd control immunity and 90% damage reduction. Void Shift's cooldown refreshes whenever Malzahar takes non-minion damage or is affected by a crowd control effect, and resets upon respawning.","img":"Malzahar_Passive.png"},"Q":{"name":"Call of the Void","desc":"Active: Malzahar opens two portals to the void centered at the target location, granting sight of the area in between. After 0.4 seconds, enemies between the portals are dealt magic damage and silenced for a duration.","img":"MalzaharQ.png","cd":"6","cost":"60/65/70/75/80","range":"900"},"W":{"name":"Void Swarm","desc":"Passive: Malzahar generates a stack of Zz'Rot Swarm when he casts another ability, up to a maximum of 2. Active: Malzahar consumes all Zz'Rot Swarm stacks and, after a 0.5-second delay, summons a Voidling at the target location. Additional Voidlings are then summoned for each Zz'Rot Swarm stack consumed, with each Voidling being summoned 0.5 seconds after the previous one.","img":"MalzaharW.png","cd":"8","cost":"40/45/50/55/60","range":"150"},"E":{"name":"Malefic Visions","desc":"Active: Malzahar infects the target enemy's mind, dealing magic damage every 0.25 seconds over 4 seconds, which refreshes upon damaging them with Call of the Void or Nether Grasp. Malefic Visions executes minions if they would be damaged below 10–30 (based on level) health. If the target dies while infected, they spread Malefic Visions onto the closest nearby enemy and Malzahar restores 2% of his maximum mana.","img":"MalzaharE.png","cd":"11/10/9/8/7","cost":"60/70/80/90/100","range":"650"},"R":{"name":"Nether Grasp","desc":"Active: Malzahar tethers to the target enemy champion, knocking them down. He then channels for up to 2.5 seconds, suppressing and revealing the target and dealing them magic damage every 0.25 seconds, revealing himself in the process. Malzahar will continue to channel as long as the tether is not broken, even if the suppression is removed.","img":"MalzaharR.png","cd":"140/110/80","cost":"100","range":"700"}},"Maokai":{"title":"the Twisted Treant","passive":{"name":"Sap Magic","desc":"Innate: Periodically, Maokai empowers his next basic attack to have an uncancellable windup and heal him for 4%–12.8% (based on level) maximum health after a 0.25-second delay. Each time Maokai casts an ability, hits at least one enemy champion or epic monster with Sapling Toss, or is struck by an enemy's ability, Sap Magic's cooldown is reduced by 4 seconds, modified to 1.5 if he is hit by a large monster's basic attack or ability.","img":"Maokai_Passive.png"},"Q":{"name":"Bramble Smash","desc":"Active: Maokai sends a shockwave in the target direction that deals magic damage to enemies hit and slows them by 99% for 0.25 seconds. Bramble Smash deals bonus magic damage to monsters. Enemies near Maokai are also stunned for 0.5 seconds and knocked back up to 300 units based on their proximity to him.","img":"MaokaiQ.png","cd":"7/6.5/6/5.5/5","cost":"40","range":"600"},"W":{"name":"Twisted Advance","desc":"Active: Maokai dashes to the target enemy while being untargetable. Upon arrival, he deals magic damage and roots them for a duration.","img":"MaokaiW.png","cd":"14/13/12/11/10","cost":"60","range":"525"},"E":{"name":"Sapling Toss","desc":"Active: Maokai flings a Sapling to the target location, granting sight of the area. Once landed, a Sapling remains stationary for 30 seconds or until it reacts to the first nearby visible enemy, chasing them for up to 2.5 seconds. The Sapling explodes upon colliding with an enemy or when it expires, dealing magic damage to nearby enemies, capped at 300 against non-champions, and slowing them by 45% for 2 seconds.","img":"MaokaiE.png","cd":"18/17/16/15/14","cost":"60/65/70/75/80","range":"1100"},"R":{"name":"Nature's Grasp","desc":"Active: Maokai summons a colossal wall of five thorny brambles that slowly advances in the target direction, accelerating over time, each stopping when they collide with an enemy champion. Hitting at least one enemy champion grants Maokai bonus movement speed decaying over 2 seconds. Each bramble deals magic damage to enemies hit and roots them for 0.75–2.25 (based on distance traveled) seconds.","img":"MaokaiR.png","cd":"130/110/90","cost":"100","range":"3000"}},"MasterYi":{"title":"the Wuju Bladesman","passive":{"name":"Double Strike","desc":"Innate: Master Yi's basic attacks on-hit generate a stack of Double Strike for 4 seconds, refreshing on subsequent hits and stacking up to 3 times. At 3 stacks, Master Yi's next basic attack on-attack is empowered to consume the stacks on-hit and strike twice, the second strike dealing 50% AD physical damage. The second strike applies on-hit effects, triggers on-attack effects, and is affected by critical strike modifiers.","img":"MasterYi_Passive1.png"},"Q":{"name":"Alpha Strike","desc":"Active: Master Yi vanishes and becomes unable to act. After 0.231 seconds, he marks the target enemy and then proceeds to mark the nearest visible un-marked enemy within 600 units, recurring every 0.231 seconds[ up to 3 times. ][ for a total of 4 marks. ]If there are no other un-marked targets before then, Master Yi can mark the same enemies again. During Alpha Strike, Master Yi can select a direction from the primary target.","img":"AlphaStrike.png","cd":"20/19.5/19/18.5/18","cost":"50/55/60/65/70","range":"600"},"W":{"name":"Meditate","desc":"Active: Master Yi channels for up to 4 seconds, healing himself every 0.5 seconds, increased by 0%–100% (based on missing health). While channeling, Master Yi gains 70% damage reduction for the first 0.5 seconds, which is then modified to a reduced amount for the remaining duration of the channel. Meditate's damage reduction is halved against turrets and lingers for 0.5 seconds after the channel ends.","img":"Meditate.png","cd":"10","cost":"40","range":"20"},"E":{"name":"Wuju Style","desc":"Active: Master Yi empowers his basic attacks within the next 5 seconds to deal bonus true damage on-hit.","img":"WujuStyle.png","cd":"14","cost":"0","range":"20"},"R":{"name":"Highlander","desc":"Passive: Scoring a champion takedown reduces the current cooldowns of Master Yi's basic abilities by 70%. Active: Master Yi cleanses himself from all slows and cripples. For the next 7 seconds, he gains ghosting, bonus attack speed, bonus movement speed, slow immunity, and cripple immunity. While active, scoring a champion takedown extends Highlander's duration by 7 seconds.","img":"Highlander.png","cd":"85","cost":"100","range":"1"}},"Mel":{"title":"the Soul's Reflection","passive":{"name":"Searing Brilliance","desc":"Innate: Mel's damaging basic attacks and abilities apply a stack of Overwhelm to enemies for 5 seconds, refreshing on subsequent applications and stacking infinitely.","img":"Mel_Passive.png"},"Q":{"name":"Radiant Volley","desc":"Active: Mel launches a barrage of luminous bolts at the target location over 0.7 seconds which distribute evenly in the area. Each bolt explodes upon landing to deal magic damage to nearby enemies, reduced to 25% against minions. The bolts momentarily grant sight during their travel, while the explosions grant sight over their target area. Both can see through brush and terrain.","img":"MelQ.png","cd":"10/9/8/7/6","cost":"70/75/80/85/90","range":"950"},"W":{"name":"Rebuttal","desc":"Active: Mel forms a protective barrier around herself for 0.75 seconds, becoming invulnerable to non-turret damage and gaining 30% decaying bonus movement speed. All hostile non-turret projectiles that collide with the barrier will be destroyed instantly before Mel fires the same projectiles as her own, either toward or in the direction of the original sources, or toward herself.","img":"MelW.png","cd":"38/35/33/29/26","cost":"80/60/40/20/0","range":"250"},"E":{"name":"Solar Snare","desc":"Active: Mel fires an orb in the target direction that grants sight of its surroundings for 0.25 seconds as it travels. Enemies hit by the orb are dealt magic damage and rooted for a duration. The orb emanates a field of solar radiation that additionally expands after a 0.5-second delay. Enemies within the field are dealt magic damage and slowed by 30% every 0.125 seconds, lingering for 0.75 seconds after exiting.","img":"MelE.png","cd":"11/10.5/10/9.5/9","cost":"50/60/70/80/90","range":"1000"},"R":{"name":"Golden Eclipse","desc":"Passive: Overwhelm stacks store more damage. Active: Mel unleashes a radiant blast on all enemies affected by Overwhelm, dealing magic damage to each. Enemies are also revealed for 1 second from the start of the cast time. An enemy champion affected by Overwhelm is required to cast this ability. The target does not have to be visible to be hit by this ability.","img":"MelR.png","cd":"120/100/80","cost":"100","range":"25000"}},"Milio":{"title":"The Gentle Flame","passive":{"name":"Fired Up!","desc":"Innate: Milio's ability hits on himself and allied champions grant an enchantment for 4 seconds, which causes the next basic attack or ability hit against enemies to deal 7 / 11 / 15% (based on level) of enchanted target's AD bonus magic damage and apply a burn that deals[ 10–50 (based on level) (+ 20% of Milio's AP) magic damage over 1.5 seconds. ][ 1.67–8.33 (based on level) (+ 3.33% of Milio's AP) magic damage every 0.25 seconds over 1.5 seconds. ]","img":"Milio_P.png"},"Q":{"name":"Ultra Mega Fire Kick","desc":"Active: After a 0.25-second delay, Milio kicks a fireball in the target direction that grants sight of its path and knocks back and stuns the first enemy it hits over 1 second. Upon collision, the ball bounces once in the same direction from the target's location, granting sight of the area before exploding in the same radius after a brief delay, dealing magic damage to enemies hit and slowing them for 1.5 seconds.","img":"MilioQ.png","cd":"10","cost":"50/55/60/65/70","range":"1200"},"W":{"name":"Cozy Campfire","desc":"Active: Milio summons a fuemigo at the target location or upon the target allied champion for 6 seconds that follows the nearest allied champion and grants sight of its surroundings. Allied champions near the fuemigo gain bonus attack range equal to a percentage of their base attack range and heal every 0.264 seconds over the duration. Cozy Campfire can be recast after 0.5 seconds within the duration.","img":"MilioW.png","cd":"29/27/25/23/21","cost":"90/100/110/120/130","range":"350"},"E":{"name":"Warm Hugs","desc":"Active: Milio envelops himself or the target allied champion in protective flames, granting the target a shield and bonus movement speed for 2.5 seconds. Milio periodically stocks a Warm Hugs charge, up to a maximum of 2. Warm Hugs' effects can stack up to 2 times.","img":"MilioE.png","cd":"0.5","cost":"50/60/70/80/90","range":"650"},"R":{"name":"Breath of Life","desc":"Active: Milio explodes in soothing flames, healing and cleansing himself and nearby allied champions of non-airborne crowd control, and granting them 65% tenacity for 3 seconds. Milio cannot cast his other abilities for 0.75 seconds after Breath of Life's activation. Breath of Life cannot be used while affected by cast-inhibiting crowd control.","img":"MilioR.png","cd":"160/145/130","cost":"100","range":"700"}},"MissFortune":{"title":"the Bounty Hunter","passive":{"name":"Love Tap","desc":"Innate: Miss Fortune's basic attacks are empowered to apply a mark that expires upon attacking a new enemy. If the enemy was unmarked, this also deals 50%–100% (based on level) AD bonus physical damage, halved to 25%–50% (based on level) AD against minions.","img":"MissFortune_W.png"},"Q":{"name":"Double Up","desc":"Active: Miss Fortune fires a shot at the target enemy that deals physical damage, triggers on-attack effects, and bounces to hit another enemy behind them, applying on-hit effects to both enemies hit. Double Up's bounce is affected by critical strike modifiers. If Double Up kills the primary target, the bounce will critically strike.","img":"MissFortuneRicochetShot.png","cd":"7/6/5/4/3","cost":"40","range":"650"},"W":{"name":"Strut","desc":"Passive: Miss Fortune gains bonus movement speed after 4 seconds without taking non-persistent damage. This bonus is increased after another 3 seconds, and is granted instantly whenever Strut is cast or upon respawning. Active: Miss Fortune gains bonus attack speed for 4 seconds. Marking a new target with Love Tap reduces Strut's current cooldown by 2 seconds.","img":"MissFortuneViciousStrikes.png","cd":"12","cost":"45","range":"600"},"E":{"name":"Make It Rain","desc":"Active: Miss Fortune casts a storm of bullets at the target location for 2 seconds, granting sight of the area, dealing magic damage every 0.25 seconds to enemies within, and slowing them by 40% (+ 6% per 100 AP). Make It Rain will cast at max range if cast beyond that.","img":"MissFortuneScattershot.png","cd":"18/17/16/15/14","cost":"80","range":"1000"},"R":{"name":"Bullet Time","desc":"Active: Miss Fortune channels for up to 3 seconds, firing a number of waves of bullets in the target direction. Each wave is in a spread of 6 projectiles that deals 75% AD (+ 25% AP) physical damage to enemies hit. Each of the waves can critically strike for (120% + 8%) damage.","img":"MissFortuneBulletTime.png","cd":"120/110/100","cost":"100","range":"25000"}},"MonkeyKing":{"title":"the Monkey King","passive":{"name":"Stone Skin","desc":"Innate: Wukong gains 6–10 (based on level) bonus armor and regenerates an additional[ 0.35% of his maximum health every 5 seconds. ][ 0.035% of his maximum health every 0.5 seconds. ]Whenever Wukong or his clone damage an enemy champion or monster, he generates a stack of Strength of Stone for 5 seconds, refreshing on subsequent hits and stacking up to 5 times. Stacks expire by one every second when the duration ends.","img":"MonkeyKingStoneSkin.png"},"Q":{"name":"Crushing Blow","desc":"Active: Wukong empowers his next basic attack within 5 seconds to have an uncancellable windup, gain bonus range, deal bonus physical damage, and inflict armor reduction for 3 seconds. Crushing Blow's cooldown is reduced by 0.5 seconds whenever Wukong or his clone damage an enemy. Crushing Blow resets Wukong's and his clone's basic attack timer. Other abilities can be used during the attack's animation.","img":"MonkeyKingDoubleAttack.png","cd":"8/7.5/7/6.5/6","cost":"20","range":"250/275/300/325/350"},"W":{"name":"Warrior Trickster","desc":"Active: Wukong enters invisibility for 1 second and dashes in the target direction, leaving behind a clone of himself at his casting position for 3.25 seconds. The clone is untargetable to allies and can basic attack autonomously, prioritizing the last enemy Wukong damaged. It can also gain the effects of Crushing Blow and Nimbus Strike's bonus attack speed, and casts Cyclone whenever Wukong does. The clone deals reduced damage.","img":"MonkeyKingDecoy.png","cd":"22/21/20/19/18","cost":"60/55/50/45/40","range":"275"},"E":{"name":"Nimbus Strike","desc":"Active: Wukong dashes to the target enemy's location and sends out untargetable clones to strike up to two additional enemies near the target's location, dealing magic damage. Upon arrival, Wukong gains bonus attack speed for 5 seconds. Crushing Blow can be cast during the dash.","img":"MonkeyKingNimbus.png","cd":"10/9.25/8.5/7.75/7","cost":"30/35/40/45/50","range":"650"},"R":{"name":"Cyclone","desc":"Active: Wukong spins his staff around for up to 2 seconds, becoming ghosted and gaining 20% bonus movement speed. The staff deals physical damage every 0.25 seconds to enemies hit, and can knock them up once for 0.6 seconds. Cyclone will not knock up enemies who were already hit by either Wukong or his clone within the same cast.","img":"MonkeyKingSpinToWin.png","cd":"130/110/90","cost":"100","range":"315"}},"Mordekaiser":{"title":"the Iron Revenant","passive":{"name":"Darkness Rise","desc":"Innate: Mordekaiser's basic attacks are empowered to deal 40% AP bonus magic damage on-hit. Innate: Morderkaiser generates a stack for each enemy champion or large monster hit by his damaging basic attacks or basic abilities, lasting for 4 seconds, refreshing on subsequent hits, and stacking up to 3 times. At 3 stacks, he gains Darkness Rise.","img":"MordekaiserPassive.png"},"Q":{"name":"Obliterate","desc":"Active: Mordekaiser turns to face the target direction before striking his mace down in a line, dealing magic damage to enemies within, increased if only one enemy is hit.","img":"MordekaiserQ.png","cd":"8/7/6/5/4","cost":"0","range":"675"},"W":{"name":"Indestructible","desc":"Passive: Mordekaiser stores 45% of the post-mitigation damage he deals and 7.5% of the pre-mitigation damage he takes,[ reduced by 75% for non-champion sources, ][ reduced to 11.25% of damage dealt and 3.75% of damage taken for non-champion sources, ]as Potential Shield on his secondary resource bar, up to 30% of his maximum health. The Potential Shield decays by 8–25 (based on level) every second after not dealing or taking damage for 1 second. While Indestructible is not on cooldown, the Potential Shield will not decay below a minimum of 5% of his maximum health, and it will be set to that amount when it comes off cooldown if it was previously below it.","img":"MordekaiserW.png","cd":"12/11/10/9/8","cost":"0","range":"25000"},"E":{"name":"Death's Grasp","desc":"Passive: Mordekaiser gains magic penetration. Active: Mordekaiser summons a claw in the target direction that grants sight of the area. After 0.5 seconds, it deals magic damage to enemies within and pulls them 250 units.","img":"MordekaiserE.png","cd":"16/14/12/10/8","cost":"0","range":"700"},"R":{"name":"Realm of Death","desc":"Active: Mordekaiser aims his mace towards the target enemy champion, slowing them by 75% and revealing them over the cast time, and then banishing them with him to the Death Realm for 7 seconds. Mordekaiser also consumes the target's soul for 7 seconds, healing himself for 10% of their maximum health and reducing their current attack damage, ability power, total attack speed, maximum health, armor, magic resist, and size by 10%, in addition to gaining them for himself. If the target dies while inside the Death Realm, Mordekaiser keeps their partial stats until they respawn.","img":"MordekaiserR.png","cd":"140/120/100","cost":"0","range":"650"}},"Morgana":{"title":"the Fallen","passive":{"name":"Soul Siphon","desc":"Innate: Morgana heals herself for 18% of the post-mitigation damage dealt by her abilities against champions, large minions, and medium and large monsters.","img":"FallenAngel_Empathize.png"},"Q":{"name":"Dark Binding","desc":"Active: Morgana throws a sphere of dark magic in the target direction that deals magic damage to the first enemy hit and roots them for a duration.","img":"MorganaQ.png","cd":"10","cost":"50/55/60/65/70","range":"1250"},"W":{"name":"Tormented Shadow","desc":"Passive: Tormented Shadow's current cooldown is reduced by 5% of its total cooldown whenever Soul Siphon triggers. Simultaneous triggers from multiple targets will stack the cooldown reduction.","img":"MorganaW.png","cd":"12","cost":"70/80/90/100/110","range":"900"},"E":{"name":"Black Shield","desc":"Active: Morgana grants a shield to the target allied champion or herself for 5 seconds, which absorbs incoming magic damage and grants crowd control immunity while it holds.","img":"MorganaE.png","cd":"26/23.5/21/18.5/16","cost":"80","range":"800"},"R":{"name":"Soul Shackles","desc":"Active: Morgana latches chains of energy onto nearby enemy champions over the cast time, dealing magic damage and forming a tether between herself and each target for 3 seconds, during which she gains bonus movement speed and the targets are revealed and slowed by 20%.","img":"MorganaR.png","cd":"120/110/100","cost":"100","range":"625"}},"Naafiri":{"title":"the Hound of a Hundred Bites","passive":{"name":"We Are More","desc":"Innate: Periodically, Naafiri summons a Packmate that fights alongside her. She may have up to 2 / 3 / 4 / 5 (based on level) Packmates at a time. Naafiri summons the maximum number of Packmates when the game starts and upon respawning. Hitting champions or large monsters with abilities reduces the cooldown by 4 seconds. Killing enemies reduces it by 1 second. See Pets for full details on Packmates.","img":"Icons_Naafiri_P.png"},"Q":{"name":"Darkin Daggers","desc":"Active: Naafiri hurls a dagger in the target direction that deals physical damage to enemies hit and inflicts them with a bleed that deals bonus physical damage every 0.5 seconds for 5 seconds. The bleed executes minions and non-epic monsters if they would be damaged below 30–70 (based on level) health. Darkin Daggers can be recast after 0.5 seconds and within 4 seconds at no additional cost.","img":"NaafiriQ.png","cd":"9/8.5/8/7.5/7","cost":"50/60/70/80/90","range":"900"},"W":{"name":"The Call of the Pack","desc":"Active: Naafiri goes on the hunt for the next 5 seconds, becoming untargetable and ghosted for the first 1 second and vanishing all of her active Packmates in the first 0.9 seconds. Her active Packmates will reappear near her after their vanish. After 1.25 seconds into the hunt, Naafiri summons 2 additional Packmates that last for the remaining duration and can exceed We Are More's summon cap.","img":"NaafiriR.png","cd":"26/24/22/20/18","cost":"60","range":"400"},"E":{"name":"Eviscerate","desc":"Active: Naafiri dashes in the target direction and deals physical damage to enemies she passes through. Upon arrival, she explodes in a flurry of blades to deal physical damage to nearby enemies. Packmates vanish during the dash and reappear near Naafiri on her arrival. They are also healed to full health upon their reappearance.","img":"NaafiriE.png","cd":"11/10/9/8/7","cost":"40","range":"450"},"R":{"name":"Hounds' Pursuit","desc":"Active: Naafiri and her Packmates channel for 0.75 seconds to single out the target enemy champion, revealing them in the duration. Upon completion of the channel, they dash to the target; upon arrival Naafiri deals physical damage and slows the target by 99% for 0.25 seconds, whereas each Packmate deals 10% of that damage. Packmates become untargetable during their channel and dash.","img":"NaafiriW.png","cd":"110/95/80","cost":"100","range":"900"}},"Nami":{"title":"the Tidecaller","passive":{"name":"Surging Tides","desc":"Innate: Nami's abilities grant 100 (+ 25% AP) bonus movement speed to allied champions hit, decaying over 1.5 seconds. The bonus is[ doubled ][ increased to 200 (+ 50% AP) ]from Tidal Wave.","img":"NamiPassive.png"},"Q":{"name":"Aqua Prison","desc":"Active: Nami launches a bubble at the target location that lands after 0.726 seconds, dealing magic damage to enemies hit and suspending them for 1.5 seconds, during which they are revealed. Allied champions are granted Surging Tides in a slightly larger area.","img":"NamiQ.png","cd":"12/11/10/9/8","cost":"60","range":"875"},"W":{"name":"Ebb and Flow","desc":"Active: Nami unleashes a stream of water onto the target champion or herself, which then bounces to nearby unaffected champions up to twice, alternating between enemies and allies and Nami. Ebb and Flow heals allies and deals magic damage to enemies, with each bounce modifying the effectiveness of the next by -10% (+ 10% per 100 AP).","img":"NamiW.png","cd":"10","cost":"70/75/80/85/90","range":"725"},"E":{"name":"Tidecaller's Blessing","desc":"Active: Nami blesses herself or an allied champion for 6 seconds, empowering their next 3 basic attacks or abilities to each deal bonus magic damage and slow enemies for 1 second. Empowered abilities that apply area damage only deal 33%–66% (based on level) of the bonus damage to non-champions.","img":"NamiE.png","cd":"11","cost":"55/60/65/70/75","range":"800"},"R":{"name":"Tidal Wave","desc":"Active: Nami surges a tidal wave in the target direction, granting sight around its trajectory as it travels, dealing magic damage to enemies hit, knocking them up for 0.5 seconds, and slowing them by 70% for 2–4 (based on distance traveled) seconds.","img":"NamiR.png","cd":"120/110/100","cost":"100","range":"2550"}},"Nasus":{"title":"the Curator of the Sands","passive":{"name":"Soul Eater","desc":"Innate: Nasus gains 12 / 18 / 24% (based on level) life steal.","img":"Nasus_Passive.png"},"Q":{"name":"Siphoning Strike","desc":"Active: Nasus empowers his next basic attack within 10 seconds to have an uncancellable windup, gain 50 bonus range, and deal bonus physical damage. Siphoning Strike's base damage is affected by critical strike modifiers. If Siphoning Strike kills the target, Nasus permanently gains 3 stacks, increased to 12 if the target is a champion, large minion, or large monster. Siphoning Strike resets Nasus' basic attack timer.","img":"NasusQ.png","cd":"7.5/6.5/5.5/4.5/3.5","cost":"20","range":"255"},"W":{"name":"Wither","desc":"Active: Nasus ages the target enemy champion for 5 seconds, slowing them by 35% and crippling them by[ 75% of that amount, ][ 26.25%, ]both increasing every second over the duration.","img":"NasusW.png","cd":"15/14/13/12/11","cost":"80","range":"700"},"E":{"name":"Spirit Fire","desc":"Active: Nasus unleashes a spirit fire at the target location, granting sight of the area for 2.5 seconds and, after a 0.264 seconds delay, dealing magic damage to enemies within. The fire then remains for 5 seconds, dealing magic damage each second to enemies within and inflicting them with armor reduction, lingering for 1 second.","img":"NasusE.png","cd":"12","cost":"60/70/80/90/100","range":"650"},"R":{"name":"Fury of the Sands","desc":"Active: Nasus empowers himself for 15 seconds, gaining bonus health, bonus armor, bonus magic resistance, increased size, and 50 bonus attack range for the duration. While Nasus is empowered, he deals magic damage every 0.5 seconds to nearby enemies, capped at 240 per second, and Siphoning Strike's cooldown is halved.","img":"NasusR.png","cd":"120/100/80","cost":"100","range":"400"}},"Nautilus":{"title":"the Titan of the Depths","passive":{"name":"Staggering Blow","desc":"Innate: Nautilus' basic attacks are empowered to deal 14–116 (based on level) bonus physical damage and root the target for 0.75–1.5 (based on level) seconds. This effect cannot occur on the same target more than once every few seconds.","img":"Nautilus_StaggeringBlow.png"},"Q":{"name":"Dredge Line","desc":"Active: Nautilus hurls his anchor in the target direction that stops on the first enemy or terrain hit. If the anchor hits an enemy, it deals magic damage, reveals them for 1.15 seconds, stuns them for 1 second, and drags them toward Nautilus while he also dashes toward them, both over 0.9 seconds. If the anchor hits terrain, Nautilus dashes to that location and 50% of Dredge Line's cooldown and mana cost are refunded.","img":"NautilusAnchorDrag.png","cd":"14/13/12/11/10","cost":"60","range":"1150"},"W":{"name":"Titan's Wrath","desc":"Active: Nautilus grants himself a shield for 6 seconds, and while it holds, his basic attacks are empowered to apply Pain of Wrath to the target and surrounding non-structure enemies. Pain of Wrath: The target takes magic damage over time, half dealt immediately and the other half dealt after 1.25 seconds. Titan's Wrath resets Nautilus' basic attack timer.","img":"NautilusPiercingGaze.png","cd":"12","cost":"60","range":"350"},"E":{"name":"Riptide","desc":"Active: Nautilus sends three waves of explosions that radiate from him over 0.561 seconds. Each wave deals magic damage to enemies hit, reduced to 50% against those hit by subsequent waves beyond the first, and slows them by an amount that decays over 1.5 seconds. Riptide deals 150% damage against monsters.","img":"NautilusSplashZone.png","cd":"7/6.5/6/5.5/5","cost":"50/60/70/80/90","range":"600"},"R":{"name":"Depth Charge","desc":"Active: Nautilus sends out a Depth Charge that chases the target enemy champion, accelerating over time and creating eruptions every 0.264 seconds in its wake that also briefly grant sight of the area. Enemies hit by the eruptions are dealt magic damage, knocked up for 1 second, and stunned for a duration.","img":"NautilusGrandLine.png","cd":"120/100/80","cost":"100","range":"825"}},"Neeko":{"title":"the Curious Chameleon","passive":{"name":"Inherent Glamour","desc":"Innate: Neeko has a collection of disguises to take on the appearance of allied champions. She can choose a new champion to switch her disguise or select herself to deactivate her disguise, placing Inherent Glamour on a 0.5-second cooldown. Taking damage from a champion or turret puts Inherent Glamour on a 2-second cooldown.","img":"Neeko_P.png"},"Q":{"name":"Blooming Burst","desc":"Active: Neeko tosses a seed that blooms at the target location, dealing magic damage to nearby enemies. If the bloom kills an enemy or hits a champion or large monster, it will bloom again after 0.75 seconds to deal magic damage. This may occur up to 2 times per cast. Each bloom deals bonus magic damage against monsters. Blooming Burst will cast at max range if cast beyond that.","img":"NeekoQ.png","cd":"9/8.5/8/7.5/7","cost":"50/60/70/80/90","range":"800"},"W":{"name":"Shapesplitter","desc":"Passive: Neeko's basic attacks on-hit generate a stack of Shapesplitter, which refreshes on subsequent attacks and stacks up to 2 times. At 2 stacks, her next basic attack on-attack consumes them all to become non-projectile, deal bonus magic damage and grant her bonus movement speed for 1 second. This attack deals 75 bonus magic damage against monsters.","img":"NeekoW.png","cd":"16/15/14/13/12","cost":"0","range":"900"},"E":{"name":"Tangle-Barbs","desc":"Active: Neeko slings a magical spiral in the target direction that deals magic damage to enemies hit and roots them for a duration. If the spiral hits at least one enemy, it grows in size and its speed and root duration is increased.","img":"NeekoE.png","cd":"12/11.5/11/10.5/10","cost":"60/65/70/75/80","range":"1000"},"R":{"name":"Pop Blossom","desc":"Active: Neeko winds up spiritual essence over 1.25 seconds and highlights an area around herself, which is visible to enemies unless she is disguised. If Neeko is in a disguise, it will break after 0.5 seconds into the duration. After winding up, the cast time begins and Neeko leaps upward, knocking up nearby enemies for 0.6 seconds.","img":"NeekoR.png","cd":"120/105/90","cost":"100","range":"600"}},"Nidalee":{"title":"the Bestial Huntress","passive":{"name":"Prowl","desc":"Innate - Prowl: While in brush, Nidalee gains ghosting and 10% bonus movement speed, increased to 30% while facing a visible enemy champion within 1400 range. The bonuses persist for 2 seconds after leaving brush.","img":"Nidalee_Passive.png"},"Q":{"name":"Javelin Toss / Takedown","desc":"Active: Nidalee hurls a javelin in the target direction that deals magic damage to the first enemy hit, increased by 0%–200% (based on distance traveled).","img":"JavelinToss.png","cd":"6","cost":"50/55/60/65/70","range":"1500"},"W":{"name":"Bushwhack / Pounce","desc":"Active: Nidalee lays a trap at the target location that becomes stealthed after arming over 1.5 seconds, lasting for up to 120 seconds and granting sight within its radius. The trap will spring upon contact with an enemy, dealing magic damage every second over 4 seconds.","img":"Bushwhack.png","cd":"13/12/11/10/9","cost":"30/35/40/45/50","range":"900"},"E":{"name":"Primal Surge / Swipe","desc":"Active: Nidalee revitalizes herself or the target allied champion, granting the target bonus attack speed for 7 seconds and healing them for an amount that is increased by 0%–100% (based on target's missing health).","img":"PrimalSurge.png","cd":"12","cost":"50/55/60/65/70","range":"900"},"R":{"name":"Aspect Of The Cougar","desc":"Active: Nidalee switches between her Human Form and Cougar Form. Cougar Form: Nidalee transforms into a cougar, gaining melee attacks with 125 range and access to her cougar abilities. Human Form: Nidalee transforms into a human, gaining ranged attacks with 525 range and access to her human abilities. While in this form, applying a Hunted mark will reset Aspect of the Cougar's cooldown.","img":"AspectOfTheCougar.png","cd":"3","cost":"0","range":"20"}},"Nilah":{"title":"the Joy Unbound","passive":{"name":"Joy Unending","desc":"Innate: Whenever Nilah kills a minion, she and the nearest allied champion gain an additional 50% of the experience they would have lost from sharing.","img":"NIlahP.png"},"Q":{"name":"Formless Blade","desc":"Passive: Nilah gains 0%–33% (based on critical strike chance) armor penetration. Her basic attacks and Formless Blade heal her for 0%–20% (based on critical strike chance) of the post-mitigation damage dealt to champions, converting each heal instance beyond maximum health into a shield that lasts 6 seconds.","img":"NilahQ.png","cd":"4","cost":"30","range":"600"},"W":{"name":"Jubilant Veil","desc":"Active: Nilah envelops herself in mist for 2.25 seconds, during which she becomes ghosted, gains bonus movement speed, reduces all incoming magic damage taken by 25%, and dodges all non-turret basic attacks. Allied champions she touches will also be enveloped for 1.5 seconds, gaining the same effects.","img":"NilahW.png","cd":"26/25/24/23/22","cost":"60/45/30/15/0","range":"150"},"E":{"name":"Slipstream","desc":"Active: Nilah dashes a fixed distance in the direction of the target unit, dealing physical damage to enemies she passes through. Nilah periodically stocks a Slipstream charge, up to a maximum of 2. Slipstream resets Nilah's basic attack timer. Formless Blade and Apotheosis can be cast during the dash.","img":"NilahE.png","cd":"0.5","cost":"40","range":"550"},"R":{"name":"Apotheosis","desc":"Active: Nilah whirls her whip-blade over 1 second, dealing physical damage to nearby enemies every 0.25 seconds. She then unleashes a burst that deals physical damage and pulls them 250 units towards her. Each hit also slows targets by 10% for 3 seconds, refreshing on subsequent hits.","img":"NilahR.png","cd":"110/95/80","cost":"100","range":"400"}},"Nocturne":{"title":"the Eternal Nightmare","passive":{"name":"Umbra Blades","desc":"Innate: Periodically, Nocturne empowers his next basic attack to slash in a circle, dealing 120% AD physical damage to the target and nearby enemies and healing himself for 13–30 (based on level) (+ 30% AP) per enemy hit. Against minions, Umbra Blade's damage to secondary targets and healing are reduced by 50% and it applies on-hit effects to all targets(note) at 100% effectiveness.","img":"Nocturne_UmbraBlades.png"},"Q":{"name":"Duskbringer","desc":"Active: Nocturne casts out a shadow blade in the target direction that leaves a Dusk Trail in its wake, dealing physical damage to enemies hit. Enemy champions and large monsters hit will leave a Dusk Trail behind while moving. Dusk Trails last 5 seconds and will slowly disappear afterwards. While on the Dusk Trail, Nocturne is ghosted and gains bonus attack damage and bonus total movement speed.","img":"NocturneDuskbringer.png","cd":"8","cost":"60/65/70/75/80","range":"1125"},"W":{"name":"Shroud of Darkness","desc":"Passive: Nocturne gains bonus attack speed. Active: Nocturne gains a spell shield for 1.5 seconds. Upon successfully blocking a hostile effect, Shroud of Darkness' bonus attack speed is doubled for 5 seconds.","img":"NocturneShroudofDarkness.png","cd":"20/18/16/14/12","cost":"50","range":"20"},"E":{"name":"Unspeakable Horror","desc":"Passive: Nocturne gains 90% bonus movement speed while facing nearby feared targets. Active: Nocturne torments the target, forming a tether between himself and the target for 2 seconds, during which the target takes magic damage every 0.5 seconds over the duration. If the tether is not broken by the end of its duration, the target is feared for a duration while being slowed by 90%.","img":"NocturneUnspeakableHorror.png","cd":"15/14/13/12/11","cost":"60/65/70/75/80","range":"425"},"R":{"name":"Paranoia","desc":"Active: Nocturne terrorizes all enemy champions, nearsighting them for 6 seconds. He can recast Paranoia for the same duration after 0.25 seconds. Recast: Nocturne dashes with displacement immunity to the target enemy champion, dealing physical damage upon arrival. Nocturne can cast any of his abilities during the dash.","img":"NocturneParanoia.png","cd":"140/115/90","cost":"100","range":"2500/3250/4000"}},"Nunu":{"title":"the Boy and His Yeti","passive":{"name":"Call of the Freljord","desc":"Innate: When Nunu and Willump deal damage against an enemy champion, large monster or structure, they and a nearby allied champion gain Call of the Freljord for 4 seconds, prioritizing the ally with highest attack speed. Call of the Freljord: Gain 20% bonus attack speed and 10% bonus movement speed. Willump's basic attacks additionally deal 30% AD physical damage to secondary targets in a cone in front of him.","img":"NunuPassive.png"},"Q":{"name":"Consume","desc":"Active: Willump takes a bite out of the target enemy, dealing damage and healing himself. The heal is increased by 50% while he is below 50% maximum health. Against minions and monsters, he deals true damage. Additionally, if Consume would kill the target minion or small or medium monster, Willump devours the target, stunning and pulling them towards him over the cast time.","img":"NunuQ.png","cd":"13/12/11/10/9","cost":"60","range":"125"},"W":{"name":"Biggest Snowball Ever!","desc":"Active: Willump cleanses himself from all slows and channels for up to 10 seconds, becoming ghosted and slow-immune and creating a rolling snowball. Willump automatically navigates his movement in the direction of the cursor and can steer the snowball with a slow turn rate that increases over time, resetting upon changing direction. The duo have their movement speed reduced by 50% for the first 1 second, but after a delay they start gaining 14 movement speed every 0.25 seconds, up to a cap.","img":"NunuW.png","cd":"14","cost":"50/55/60/65/70","range":"7500"},"E":{"name":"Snowball Barrage","desc":"Active: Nunu throws a volley of 3 snowballs in the target direction over 0.4 seconds that each shatter upon hitting an enemy, dealing magic damage to enemies in a cone. Enemies hit 3 times are slowed for 1 second. Enemy champions and large monsters hit once are marked Snowbound for 4 seconds, refreshing on subsequent hits. Snowball Barrage can be recast twice within 3 seconds at no additional cost and with a cooldown in between casts.","img":"NunuE.png","cd":"14/13/12/11/10","cost":"50/55/60/65/70","range":"625"},"R":{"name":"Absolute Zero","desc":"Active: Nunu and Willump channel a blizzard for up to 3 seconds, granting themselves a shield and slowing nearby enemies by 0%–95% (based on channel time). Absolute Zero can be recast after 0.5 seconds during the channel, and does so automatically when the channel ends by any means.","img":"NunuR.png","cd":"110/100/90","cost":"100","range":"650"}},"Olaf":{"title":"the Berserker","passive":{"name":"Berserker Rage","desc":"Innate: Olaf gains bonus attack speed and life steal based on his missing health, up to 50%–100% (based on level) bonus attack speed and 8%–25% (based on level) life steal at 70% missing health.","img":"Olaf_Passive.png"},"Q":{"name":"Undertow","desc":"Active: Olaf throws an axe to the target location that deals physical damage to enemies it passes through and slows them for 1.5–2.5 (based on distance traveled) seconds. Enemy champions hit are also inflicted with 20% armor reduction for 4 seconds. Undertow deals bonus physical damage against monsters.","img":"OlafAxeThrowCast.png","cd":"9","cost":"50/55/60/65/70","range":"1000"},"W":{"name":"Tough It Out","desc":"Active: Olaf gains bonus attack speed for 5 seconds. He also grants himself a shield for 2.5 seconds for an amount that is capped at 70% missing health. Tough It Out resets Olaf's basic attack timer.","img":"OlafFrenziedStrikes.png","cd":"16/15/14/13/12","cost":"50","range":"700"},"E":{"name":"Reckless Swing","desc":"Active: Olaf strikes thunder onto the target enemy, dealing true damage. If Reckless Swing kills the target, Olaf heals himself equal to the health cost. Basic attacks reduce Reckless Swing's cooldown by 1 second, increased to 2 against monsters.","img":"OlafRecklessStrike.png","cd":"11/10/9/8/7","cost":"0","range":"325"},"R":{"name":"Ragnarok","desc":"Passive: Olaf gains bonus armor and bonus magic resistance. Active: Olaf becomes enraged for 3 seconds, cleansing himself of all crowd control and becoming immune to them, as well as gaining bonus attack damage and 10% increased size. For the first second of Ragnarok, he also gains bonus movement speed while facing visible enemy champions within 2000 units.","img":"OlafRagnarok.png","cd":"100/90/80","cost":"100","range":"400"}},"Orianna":{"title":"the Lady of Clockwork","passive":{"name":"Clockwork Windup","desc":"Innate - The Ball: Orianna is accompanied by The Ball, which she commands with her abilities. The Ball incurs a 0.01-second global cooldown on all of her abilities when she casts any ability. Additionally, The Ball attaches to Orianna if she is near it, and snaps back to her if she moves too far away from it, which incurs a 0.75-second cooldown on Command: Shockwave.","img":"OriannaPassive.png"},"Q":{"name":"Command: Attack","desc":"Active: Orianna commands The Ball to fly to the target location and remain there, dealing magic damage to enemies it passes through and nearby enemies upon arrival, reduced to 70% against those hit beyond the first.","img":"OrianaIzunaCommand.png","cd":"7/6/5/4/3","cost":"35","range":"815"},"W":{"name":"Command: Dissonance","desc":"Active: Orianna commands The Ball to emit an electric pulse that deals magic damage to nearby enemies. The pulse leaves behind an electric field that last 3 seconds, granting bonus movement speed to Orianna and her allies when they move within. Enemies that move within the field are slowed by the same amount, decaying over 2 seconds after leaving.","img":"OrianaDissonanceCommand.png","cd":"7","cost":"60/65/70/75/80","range":"225"},"E":{"name":"Command: Protect","desc":"Passive: The Ball grants bonus armor and bonus magic resistance to the unit it is attached to. Active: Orianna commands The Ball to fly to herself or the target allied champion and attach itself to the target, dealing magic damage to enemies it passes through and granting the target a shield for 2.5 seconds upon arrival.","img":"OrianaRedactCommand.png","cd":"9","cost":"60","range":"1095"},"R":{"name":"Command: Shockwave","desc":"Active: Orianna commands The Ball to unleash a shockwave that deals magic damage to nearby enemies, stuns them for 0.75 seconds, and pulls them over 325 units, though not through terrain.","img":"OrianaDetonateCommand.png","cd":"110/95/80","cost":"100","range":"410"}},"Ornn":{"title":"The Fire below the Mountain","passive":{"name":"Living Forge","desc":"Innate - Living Forge: Ornn can purchase non-consumable items from anywhere on the field by forging them himself, and is also presented a Forge Menu to quickly forge his recommended items. Once Ornn selects an item to forge, he channels for 4 seconds, building the item and paying its gold cost upon completion. The channel is interrupted if Ornn takes damage from enemy champions or turrets. Living Forge is disabled for 4 seconds after starting the channel.","img":"OrnnP.png"},"Q":{"name":"Volcanic Rupture","desc":"Active: Ornn sends a fissure in the target direction that deals physical damage to enemies hit and slows them by 40% for 2 seconds. The fissure stops at maximum range or 200 units behind the first enemy champion struck. After a 1.125-second delay, a magma pillar then erupts to knock aside enemies, though not through terrain, and linger as impassible terrain for 4 seconds. The pillar will not expire while Ornn is charging.","img":"OrnnQ.png","cd":"9/8.5/8/7.5/7","cost":"45","range":"800"},"W":{"name":"Bellows Breath","desc":"Active: Ornn marches forward in the target direction over 0.75 seconds, gaining displacement immunity and becoming unable to act for the duration. Over the march he belches fire over a cone in front of him, dealing magic damage every 0.15 seconds to enemies hit. The final gout of flame can reach slightly farther and will apply Brittle for 3 seconds.","img":"OrnnW.png","cd":"12/11.5/11/10.5/10","cost":"45/50/55/60/65","range":"25000"},"E":{"name":"Searing Charge","desc":"Active: Ornn charges in the target direction, dealing physical damage to enemies he passes through and stopping upon colliding with terrain. If Ornn collides with terrain during the charge, he creates a shockwave that knocks up and stuns nearby enemies for 1.25 seconds and deals the same damage if they were not already hit by the charge.","img":"OrnnE.png","cd":"14/13.5/13/12.5/12","cost":"35/40/45/50/55","range":"450"},"R":{"name":"Call of the Forge God","desc":"Active: Ornn sounds his horn, summoning a lava elemental at maximum range from the target direction that stampedes towards his casting position at increasing speed. The elemental deals magic damage to enemies it passes through and slows them for 2 seconds. Call of the Forge God can be recast after 1.25 seconds while the elemental is active.","img":"OrnnR.png","cd":"140/120/100","cost":"100","range":"2500"}},"Pantheon":{"title":"the Unbreakable Spear","passive":{"name":"Mortal Will","desc":"Innate: Pantheon generates a stack of Mortal Will whenever he lands a basic attack on-hit or casts an ability, stacking up to 5 times. At 5 stacks, Pantheon's next basic ability consumes the stacks to become empowered with an additional effect. Pantheon gains maximum stacks of Mortal Will upon starting the game, completing a Recall channel, and respawning.","img":"Pantheon_Passive.png"},"Q":{"name":"Comet Spear","desc":"Active: Pantheon charges while being slowed by 10% for up to 4 seconds to increase Comet Spear's range after 0.35 seconds of channeling. Comet Spear can be recast within the duration. Recast: Pantheon hurls his spear in the target direction that deals physical damage to enemies hit, increased against enemies below 20% of their maximum health but reduced by 50% against enemies beyond the first.","img":"PantheonQ.png","cd":"11/10.25/9.5/8.75/8","cost":"25","range":"575"},"W":{"name":"Shield Vault","desc":"Active: Pantheon leaps to the front of the target enemy's location. If the target is within 800 units upon arrival, he deals physical damage and stuns them for 1 second. Against minions and monsters, Shield Vault has a minimum damage of 60 and is capped at 200.","img":"PantheonW.png","cd":"13/12/11/10/9","cost":"55","range":"600"},"E":{"name":"Aegis Assault","desc":"Active: Pantheon braces his shield in the target direction and channels for 1.5 seconds, during which he becomes invulnerable to non-turret damage dealt by enemies from the target direction. He also continually performs strikes in a cone in front of him, dealing 8.3% AD physical damage every 0.125 seconds to enemies hit, reduced by 50% against minions and up to 100% AD total physical damage.","img":"PantheonE.png","cd":"22/21/20/19/18","cost":"80","range":"400"},"R":{"name":"Grand Starfall","desc":"Passive: Pantheon gains armor penetration. Active: Pantheon channels for 2 seconds, then leaps high into the air, vanishing and becoming immune to crowd control until he reappears. While in the air, Pantheon channels again for 2.25 seconds and grants sight around the target location 0.5 seconds into the channel.","img":"PantheonR.png","cd":"180/165/150","cost":"100","range":"5500"}},"Poppy":{"title":"Keeper of the Hammer","passive":{"name":"Iron Ambassador","desc":"Innate: Periodically, Poppy's next basic attack is empowered to throw her buckler, gaining 350 bonus range and dealing 20–180 (based on level) bonus magic damage. After it hits, the buckler then falls to a location near the target over 1 second, landing and remaining there for up to 4 seconds.","img":"Poppy_Passive.png"},"Q":{"name":"Hammer Shock","desc":"Active: Poppy smashes the area in the target direction, dealing physical damage to enemies hit. Against monsters, the damage based on their health ratio is capped. The impact creates a field for 1 second that slows enemies within, which then ruptures to deal the same physical damage.","img":"PoppyQ.png","cd":"8/7/6/5/4","cost":"35/40/45/50/55","range":"430"},"W":{"name":"Steadfast Presence","desc":"Passive: Poppy increases her total armor and total magic resistance by 12%, doubled to 24% while she is below 40% maximum health. Active: Poppy gains 40% bonus movement speed and creates an aura around herself for 2 seconds, causing all enemies who attempt to dash into or within it to be dealt magic damage and knocked up for 0.5 seconds. If a target was successfully interrupted, they become grounded and slowed by 25% for 2 seconds.","img":"PoppyW.png","cd":"20/18/16/14/12","cost":"50","range":"400"},"E":{"name":"Heroic Charge","desc":"Active: Poppy dashes to the target enemy's location. If they are in range upon arrival, she deals physical damage and carries them along with her for up to 400 units. If the target hits terrain, she stops to deal the same physical damage again and stuns them for a duration.","img":"PoppyE.png","cd":"14/13/12/11/10","cost":"70","range":"475"},"R":{"name":"Keeper's Verdict","desc":"Active: Poppy charges while being slowed by 15% for up to 4 seconds to increase Keeper's Verdict's range and knock back distance over 0.5 seconds after the first 0.5 seconds of the channel. Keeper's Verdict can be recast within the duration. Recast: Poppy releases the charge to launch her hammer upwards, dealing physical damage to enemies nearby and in an area in front of her and knocking them up for 1 second.","img":"PoppyR.png","cd":"140/120/100","cost":"100","range":"500"}},"Pyke":{"title":"the Bloodharbor Ripper","passive":{"name":"Gift of the Drowned Ones","desc":"Innate: Pyke's maximum health cannot increase except through growth (per level), instead he gains[ 1 bonus attack damage per 14 bonus health. ][ bonus attack damage equal to 7.143% of bonus health. ] Innate: Pyke gains 1 bonus movement speed while in the river.","img":"PykePassive.png"},"Q":{"name":"Bone Skewer","desc":"Active: Pyke charges while being slowed by 20% for up to 3 seconds to increase Bone Skewer's range over the first second of the channel. Bone Skewer can be recast within the duration. Recast: Pyke hurls his harpoon in the target direction, becoming unable to act while it is in flight and dealing physical damage to the first enemy hit and pulling them, during which they are also revealed, then slowing them by 90% for 1 second.","img":"PykeQ.png","cd":"10/9.5/9/8.5/8","cost":"70/75/80/85/90","range":"400"},"W":{"name":"Ghostwater Dive","desc":"Active: Pyke submerges into water for 5 seconds, entering camouflage and gaining 45% (+ 2% per 1 Lethality) bonus movement speed that decays over the duration. Attacking or casting abilities ends Ghostwater Dive immediately. Enemy champions within 1500 units of Pyke are alerted of his presence and whether he can execute them with Death from Below.","img":"PykeW.png","cd":"14/13/12/11/10","cost":"65","range":"600"},"E":{"name":"Phantom Undertow","desc":"Active: Pyke dashes in the target direction, leaving behind a Phantom. Pyke is ghosted while the Phantom is active. After 1 second, the Phantom homes back to Pyke to stun enemies around it and those it passes through along the way for 1.25 (+ 0.1 per 10 Lethality) seconds. Enemy champions hit also take physical damage.","img":"PykeE.png","cd":"15/14/13/12/11","cost":"40","range":"550"},"R":{"name":"Death From Below","desc":"Active: Pyke marks the target location with the shape of an X before striking it, executing enemy champions within the area that are below 250–550 (based on level) (+ 80% bonus AD) (+ 1.5 per 1 Lethality) health. Other enemies hit and enemy champions above the threshold are instead dealt[ 50% of the amount as physical damage. ][ 125–275 (based on level) (+ 40% bonus AD) (+ 0.75 per 1 Lethality) physical damage. ]","img":"PykeR.png","cd":"100/85/70","cost":"100","range":"750"}},"Qiyana":{"title":"Empress of the Elements","passive":{"name":"Royal Privilege","desc":"Innate: Qiyana's basic attacks and basic abilities deal 15–83 (based on level) (+ 30% bonus AD) (+ 30% AP) additional physical damage. This effect cannot occur on the same target more than once every few seconds. Gathering an Element with Terrashape resets Royal Privilege's per-target cooldown for enemies affected by Royal Privilege using a different Element (or no Element).","img":"Qiyana_Passive.png"},"Q":{"name":"Elemental Wrath / Edge of Ixtal","desc":"Active: Qiyana slashes forward in the target direction, dealing physical damage to enemies in a line, reduced to 75% damage against targets beyond the first. Edge of Ixtal deals 175% damage against monsters. Gathering an Element with Terrashape resets Edge of Ixtal's cooldown and upgrades it into Elemental Wrath.","img":"QiyanaQ.png","cd":"7","cost":"35","range":"525"},"W":{"name":"Terrashape","desc":"Passive: While holding an Element, Qiyana gains bonus attack speed, 25 bonus attack range and bonus magic damage on her basic attacks on-hit and basic abilities. While out-of-combat and moving near the Element currently being held, she gains bonus movement speed. Active: Qiyana dashes up to 300 units towards the target location to gather the Element of the nearest Brush, River or Terrain she targeted.","img":"QiyanaW.png","cd":"7","cost":"25/30/35/40/45","range":"1100"},"E":{"name":"Audacity","desc":"Active: Qiyana dashes a fixed distance in the direction of the target enemy. If they are in range upon arrival, she deals physical damage. Qiyana can cast any of her abilities during the dash.","img":"QiyanaE.png","cd":"11/10/9/8/7","cost":"40/45/50/55/60","range":"650"},"R":{"name":"Supreme Display of Talent","desc":"Active: Qiyana sweeps a windblast in the target direction that knocks back enemies hit, though not through terrain, and stops upon hitting Terrain.","img":"QiyanaR.png","cd":"120","cost":"100","range":"950"}},"Quinn":{"title":"Demacia's Wings","passive":{"name":"Harrier","desc":"Innate: Quinn's Blinding Assault against the primary target, Vault, and Skystrike mark enemies hit with Vulnerable for 4 seconds, during which they are revealed. Valor will periodically mark a nearby visible enemy if no Vulnerable targets exist for 1 second. Quinn's basic attacks against Vulnerable targets are empowered to consume the mark to deal 10–95 (based on level) (+ 16%–50% (based on level) AD) bonus physical damage.","img":"Quinn_Passive.png"},"Q":{"name":"Blinding Assault","desc":"Active: Quinn sends Valor in the target direction who stops upon hitting an enemy, marking them as Vulnerable and dealing physical damage to all nearby enemies. The primary target is nearsighted for 1.75 seconds if they are a champion, and disarmed for the same duration otherwise.","img":"QuinnQ.png","cd":"11/10.5/10/9.5/9","cost":"50/55/60/65/70","range":"1025"},"W":{"name":"Heightened Senses","desc":"Passive: Whenever Quinn uses a basic attack on-attack against a Vulnerable target or consumes their mark, she gains bonus attack speed and bonus movement speed for 2 seconds. Active: Valor grants sight of the surrounding area for 2 seconds and reveals enemy champions within for the same duration.","img":"QuinnW.png","cd":"50/45/40/35/30","cost":"0","range":"2100"},"E":{"name":"Vault","desc":"Active: Quinn dashes to the target enemy, marking them as Vulnerable, dealing physical damage, knocking them back a very short distance over 0.5 seconds, and slowing them by 50% decaying over 1.5 seconds. She then leaps back 525 units away from them. Vault resets Quinn's basic attack timer shortly after the initial dash. Heightened Senses can be cast during either of the dashes.","img":"QuinnE.png","cd":"12/11/10/9/8","cost":"50","range":"675"},"R":{"name":"Behind Enemy Lines","desc":"Active: Quinn channels for 2 seconds, signaling Valor to pair up. Upon completion, he picks her up and they unite, increasing her total movement speed, granting her ghosting, and allowing her to cast Skystrike. Behind Enemy Lines can be recast after 0.5 seconds during the channel.","img":"QuinnR.png","cd":"3","cost":"50/25/0","range":"700"}},"Rakan":{"title":"The Charmer","passive":{"name":"Fey Feathers","desc":"Innate: Periodically, Rakan grants himself a shield for 30–225 (based on level) (+ 95% AP) that lasts until broken. After being out of combat for 5 seconds, any leftover shield will be restored to maximum value. Rakan's basic attacks and ability hits reduce Fey Feathers' cooldown by 1 second for each enemy champion hit.","img":"Rakan_P.png"},"Q":{"name":"Gleaming Quill","desc":"Active: Rakan slings an enchanted feather in the target direction that deals magic damage to the first enemy hit. If the target was an enemy champion or epic monster, a radius is marked around Rakan. After 3 seconds or if an allied champion enters the radius, Rakan heals himself and nearby allied champions for 40–210 (based on level) (+ 55% AP).","img":"RakanQ.png","cd":"11/10/9/8/7","cost":"45","range":"850"},"W":{"name":"Grand Entrance","desc":"Active: Rakan dashes to the target location. After a 0.35-second delay upon arrival, he deals magic damage to nearby enemies and knocks them up for 1 second. Rakan will be knocked down by any immobilizing or polymorphing crowd control during the dash. Grand Entrance will cast at max range if cast beyond that.","img":"RakanW.png","cd":"14/13/12/11/10","cost":"50/60/70/80/90","range":"600"},"E":{"name":"Battle Dance","desc":"Active: Rakan grants a shield to the target allied champion for 3 seconds and then dashes to and around them. Battle Dance can be recast within 5 seconds at no additional cost. Recast: Rakan mimics the first cast's effects. Rakan will be knocked down by any immobilizing or polymorphing crowd control during the dash. If Xayah is the target, Battle Dance can be cast from an increased range.","img":"RakanE.png","cd":"0","cost":"40/45/50/55/60","range":"650"},"R":{"name":"The Quickness","desc":"Active: Rakan breaks into a captivating sprint for 4 seconds, gaining ghosting and 75% bonus movement speed for the duration. During this time, he deals magic damage to enemies he collides with and charms and slows them by 75% for a duration. This cannot affect the same enemy more than once.","img":"RakanR.png","cd":"130/110/90","cost":"100","range":"150"}},"Rammus":{"title":"the Armordillo","passive":{"name":"Spiked Shell","desc":"Innate: Rammus' basic attacks deal 10 (+ 10% armor) bonus magic damage on-hit, increased to 15 (+ 15% armor) during Defensive Ball Curl.","img":"Armordillo_ScavengeArmor.png"},"Q":{"name":"Powerball","desc":"Active: Rammus channels for up to 6 seconds to roll into a ball, gaining 25%–39.17% (based on level) bonus total movement speed per second over the duration, up to a maximum of 150%–235% (based on level). Powerball can be recast after 1 second within the duration, and does so automatically afterwards or upon casting Defensive Ball Curl.","img":"PowerBall.png","cd":"12/10.5/9/7.5/6","cost":"60","range":"300"},"W":{"name":"Defensive Ball Curl","desc":"Active: Rammus enters a defensive stance for 6 seconds, gaining bonus armor and bonus magic resistance. While active, enemies that use a basic attack on-hit against Rammus are dealt magic damage equal to Spiked Shell's bonus damage. Rammus' basic attacks extend the remaining duration of Defensive Ball Curl by 0.4 seconds, up to a maximum of 4 additional seconds.","img":"DefensiveBallCurl.png","cd":"7","cost":"40","range":"300"},"E":{"name":"Frenzying Taunt","desc":"Active: Rammus taunts the target enemy champion or monster for a duration and gains bonus attack speed for the same duration. The duration of the bonus attack speed continuously refreshes during Powerball, Defensive Ball Curl and Soaring Slam.","img":"PuncturingTaunt.png","cd":"12","cost":"50","range":"325"},"R":{"name":"Soaring Slam","desc":"Active: Rammus leaps to the target location with immunity to crowd control. Upon arrival, he creates an impact that deals magic damage to nearby enemies and slows them for 1.5 seconds. The impact deals increased damage at the epicenter if Soaring Slam was cast further than 800 units, capped at 1700 units with 50% increased damage.","img":"Tremors2.png","cd":"120/105/90","cost":"100","range":"25000"}},"RekSai":{"title":"the Void Burrower","passive":{"name":"Fury of the Xer'Sai","desc":"Innate: Rek'Sai basic attacks and ability hits generate 25 Fury. After 8 seconds of being out of combat, she loses 20 Fury per second. Fury gain is reduced[ by 80% ][ to 5 per hit ]against minions, wards, and plants. Prey Seeker will not generate Fury against non-champions.","img":"RekSai_Passive.png"},"Q":{"name":"Queen's Wrath / Prey Seeker","desc":"Active: Rek'Sai gains 35% bonus attack speed for 3 seconds. Her next basic attack within the duration will have an uncancellable windup and deal bonus physical damage to the target and surrounding enemies. Queen's Wrath's damage to the primary target is affected by critical strike modifiers. If Rek'Sai completes an attack, the duration is refreshed, for up to 3 total empowered attacks. Queen's Wrath resets Rek'Sai's basic attack timer.","img":"RekSaiQ.png","cd":"4/3.5/3/2.5/2","cost":"0","range":"325"},"W":{"name":"Burrow / Un-burrow","desc":"Active: Rek'Sai becomes Burrowed, reducing her sight radius to 385 units while gaining access to her Burrowed abilities. She also becomes ghosted and gains bonus movement speed, as well as Tremor Sense. Tremor Sense: Rek'Sai and her allies gain obscured vision of nearby enemy units that are moving at a rate of once every second.","img":"RekSaiW.png","cd":"4","cost":"0","range":"1650"},"E":{"name":"Furious Bite / Tunnel","desc":"Active: Rek'Sai bites the target enemy, dealing 100% AD physical damage. At maximum Fury, Furious Bite deals bonus physical damage, capped at 75–400 (based on level) against monsters.","img":"RekSaiE.png","cd":"6","cost":"0","range":"250"},"R":{"name":"Void Rush","desc":"Passive: Rek'Sai applies Marked as Prey to enemy champions she damages, lasting for 5 seconds.","img":"RekSaiR.png","cd":"120/100/80","cost":"0","range":"1500"}},"Rell":{"title":"the Iron Maiden","passive":{"name":"Break the Mold","desc":"Innate: Rell's basic attacks deal bonus magic damage on-hit equal to the sum of 5% of her total armor and 5% of her total magic resistance. Innate: Rell's basic attacks and abilities against non-minions reduce the target's armor and magic resistance by 3% for 5 seconds, refreshing on subsequent hits and stacking up to 5 times for a maximum of 15% reduction.","img":"RellP.png"},"Q":{"name":"Shattering Strike","desc":"Active: Rell thrusts her lance in the target direction, lunging forward 100 units and destroying the damage-mitigating shields of all enemies hit (excluding the shields of monsters) before dealing them magic damage and stunning them for 0.65 seconds.","img":"RellQ.png","cd":"11/10.5/10/9.5/9","cost":"50","range":"600"},"W":{"name":"Ferromancy: Crash Down","desc":"Passive - Mounted Alacrity: While Rell is Mounted, she gains bonus movement speed.","img":"RellW_Dismount.png","cd":"10","cost":"40","range":"450"},"E":{"name":"Full Tilt","desc":"Active: Rell powers up herself and the target allied champion for 3 seconds, both gaining 10% bonus movement speed which increases to 25% while moving within 1200 units of the empowered ally or an enemy.","img":"RellE.png","cd":"14/13/12/11/10","cost":"40","range":"1200"},"R":{"name":"Magnet Storm","desc":"Active: Rell erupts with magnetic fury, pulling nearby enemies inward. She then creates a gravitational field around her for the next 2 seconds that deals magic damage every 0.25 seconds to nearby enemies and drags them towards her.","img":"RellR.png","cd":"120/100/80","cost":"100","range":"200"}},"Renata":{"title":"the Chem-Baroness","passive":{"name":"Leverage","desc":"Innate: Renata's basic attacks are empowered to apply a mark that lasts 6 seconds, refreshes on subsequent hits and expires when attacking a new enemy. If the enemy was unmarked, the attack also deals bonus magic damage equal to 1%–2% (based on level) (+ 2% per 100 AP) of the target's maximum health.","img":"Renata_P.png"},"Q":{"name":"Handshake","desc":"Active: Renata fires a hook in the target direction that deals magic damage to the first enemy hit and roots them for 1 second, during which they are revealed.If the root was applied, Renata forms a tether between her and the target for the same duration, causing Renata to become unable to declare attacks and have her movement speed reduced by 30%. Handshake can be recast while the tether is active.","img":"RenataQ.png","cd":"16","cost":"80","range":"900"},"W":{"name":"Bailout","desc":"Active: Renata infuses herself or the target allied champion with a chemtech formula for 5 seconds, granting the target bonus attack speed and bonus movement speed while they are facing nearby visible enemy champions or minions, with both of the bonuses increasing in effectiveness by 0%–100% (based on seconds elapsed). Bailout's duration resets whenever the target scores a takedown against an enemy champion within 6 seconds of damaging them.","img":"RenataW.png","cd":"28/27/26/25/24","cost":"80","range":"800"},"E":{"name":"Loyalty Program","desc":"Active: Renata sends out chemtech rockets from either side of her that instantly strike targets around her. After 0.429 seconds they converge and travel to the target location as a single missile, striking targets along its path and exploding upon reaching the target location. Renata and allies struck are granted a shield for 3 seconds and enemies struck are dealt magic damage and slowed by 30% for 2 seconds.","img":"RenataE.png","cd":"14/13/12/11/10","cost":"70/80/90/100/110","range":"800"},"R":{"name":"Hostile Takeover","desc":"Active: Renata launches a cloud of potent chemicals that travels in the target direction, granting sight of its surroundings. Enemy champions and minions hit become berserk for a duration.","img":"RenataR.png","cd":"150/130/110","cost":"100","range":"2000"}},"Renekton":{"title":"the Butcher of the Sands","passive":{"name":"Reign of Anger","desc":"Innate: Renekton's basic attacks generate 5 Fury. After 12 seconds of being out of combat, he loses 1 Fury every 0.25 seconds. While Renekton has at least 50 Fury, his next basic ability consumes 50 Fury to become empowered with an additional effect. Empowered abilities do not generate Fury. Renekton generates 50% bonus Fury from all sources while below 50% of his maximum health.","img":"Renekton_Passive.png"},"Q":{"name":"Cull the Meek","desc":"Active: Renekton cleaves around himself, dealing physical damage to nearby enemies and healing himself for each enemy hit, up to a cap. Against champions, the healing is increased. Renekton generates 2.5 Fury for each non-champion hit and 10 Fury for each champion hit, with the Fury generated per cast capped at 30. Reign of Anger Bonus: Cull the Meek has increased damage, tripled total healing, and a quadrupled healing cap.","img":"RenektonCleave.png","cd":"7","cost":"0","range":"325"},"W":{"name":"Ruthless Predator","desc":"Active: Renekton empowers his next basic attack within 7 seconds to have a 0.2-second cast time, gain 50 bonus range and strike the target twice, dealing modified physical damage and stunning them for 0.75 seconds. Each strike applies on-hit effects and generates Fury. Hitting an enemy champion generates 10 bonus Fury. Ruthless Predator's first strike can critically strike for (75% + 40%) AD bonus physical damage.","img":"RenektonPreExecute.png","cd":"16/14/12/10/8","cost":"0","range":"300"},"E":{"name":"Slice and Dice","desc":"Active: Renekton dashes a fixed distance in the target direction, dealing physical damage to enemies he passes through. If Renekton hits an enemy, he can cast Dice within the next 4 seconds.","img":"RenektonSliceAndDice.png","cd":"16/14.5/13/11.5/10","cost":"0","range":"450"},"R":{"name":"Dominus","desc":"Active: Renekton empowers himself for 15 seconds, gaining bonus health, 20% increased size, 25 bonus attack range, and 20 Fury, as well as increasing Cull the Meek's effect radius. During this time, he deals magic damage every 0.5 seconds to nearby enemies and generates 5 Fury per second, up to a maximum of 75 Fury.","img":"RenektonReignOfTheTyrant.png","cd":"120/100/80","cost":"0","range":"20"}},"Rengar":{"title":"the Pridestalker","passive":{"name":"Unseen Predator","desc":"Innate: Rengar generates 1 Ferocity upon casting a basic ability or using Savagery's first attack. At 4 Ferocity, his next basic ability consumes them all to become empowered with an additional effect and grant him an additional cast along with 30 / 40 / 50% (based on level) bonus movement speed for 1.5 seconds. All Ferocity is lost after 10 seconds of being out of combat.Reaching 4 Ferocity with Savagery or Bola Strike locks the empowered version of the ability from being cast for 0.1 seconds. Similarly, consuming all Ferocity with an empowered ability locks the unempowered version of the ability from being cast for 0.1 seconds if it is not already on cooldown, increased to 0.25 seconds for Battle Roar.","img":"Rengar_P.png"},"Q":{"name":"Savagery","desc":"Active: Rengar empowers his next two basic attacks within 3 seconds to gain 40% bonus attack speed. His first attack has an uncancellable windup, gains 25 bonus range, and deals bonus physical damage. The attack will critically strike for ((31.25% + 30%) critical strike chance + 40%) AD bonus physical damage. Against structures, Savagery's damage is reduced by 40% and can also critically strike.","img":"RengarQ.png","cd":"0.25","cost":"0","range":"450"},"W":{"name":"Battle Roar","desc":"Passive: Rengar stores 50% of the post-mitigation damage he has taken in the last 1.5 seconds as grey health on his health bar, increased to 100% of damage taken from monsters. Active: Rengar roars, dealing magic damage to nearby enemies and 65–130 (based on level) bonus magic damage to monsters, and consuming his grey health to heal for the same amount.","img":"RengarW.png","cd":"0.25","cost":"0","range":"450"},"E":{"name":"Bola Strike","desc":"Active: Rengar throws a bola in the target direction that deals physical damage to the first enemy hit and slows them for 1.75 seconds, as well as revealing them for 2 seconds and granting sight of a 150-unit radius around them for the same duration. Ferocity Bonus: Bola Strike's damage is modified. The target is rooted instead of slowed.","img":"RengarE.png","cd":"0.25","cost":"0","range":"1000"},"R":{"name":"Thrill of the Hunt","desc":"Passive: Rengar also gains Unseen Predator while camouflaged from any source. Active: Rengar prowls for a duration, gaining bonus movement speed. After a 2-second delay, he also becomes camouflaged. During this time, Rengar will detect the nearest enemy champion in range, revealing and gaining sight of a 100-unit radius around them. Enemies detected are revealed for the remaining full duration.","img":"RengarR.png","cd":"100/90/80","cost":"0","range":"2500/3000/3500"}},"Riven":{"title":"the Exile","passive":{"name":"Runic Blade","desc":"Innate: Riven's ability casts generate a stack of Charge for 6 seconds, refreshing on subsequent casts and stacking up to 3 times. Riven's basic attacks are empowered to each consume a stack to deal bonus physical damage equal to 30%–60% (based on level) AD, reduced to[ 50% ][ 15%–30% (based on level) AD ]against structures. The bonus damage is affected by critical strike modifiers and applies life steal at 100% effectiveness.","img":"RivenRunicBlades.png"},"Q":{"name":"Broken Wings","desc":"Active: Riven can activate Broken Wings three times before the ability goes on cooldown, with a 0.3125-second static cooldown between casts. If Riven does not recast the ability within 4 seconds of the previous cast, it goes on cooldown.","img":"RivenTriCleave.png","cd":"13","cost":"0","range":"275"},"W":{"name":"Ki Burst","desc":"Active: Riven emits a flash of runic energy before the cast time, dealing physical damage to nearby enemies and stunning them for 0.75 seconds.","img":"RivenMartyr.png","cd":"11/10/9/8/7","cost":"0","range":"260"},"E":{"name":"Valor","desc":"Active: Riven dashes in the target direction, though not through terrain, while granting herself a shield for 1.5 seconds. Riven can cast any of her abilities during the dash. Valor will cast at max range if cast beyond that.","img":"RivenFeint.png","cd":"10/9/8/7/6","cost":"0","range":"250"},"R":{"name":"Blade of the Exile","desc":"Active: Riven empowers her blade for 15 seconds, gaining 25% AD bonus attack damage, 75 bonus attack range, and increased range on Broken Wings and Ki Burst. After 0.5 seconds, she can cast Wind Slash within the duration.","img":"RivenFengShuiEngine.png","cd":"120/90/60","cost":"0","range":"200"}},"Rumble":{"title":"the Mechanized Menace","passive":{"name":"Junkyard Titan","desc":"Innate: Rumble's basic ability casts generate Heat, which decays by 10 Heat per second after not using any basic ability within 4 seconds or The Equalizer within 2 seconds. Rumble's mech enters the Danger Zone when at or above 50 Heat, and becomes Overheated while at 150 Heat. Danger Zone: Rumble's mech enters the Danger Zone, empowering his basic abilities.","img":"Rumble_JunkyardTitan1.png"},"Q":{"name":"Flamespitter","desc":"Active: Rumble generates 20 Heat to activate his flamethrower for 3 seconds, dealing magic damage every 0.25 seconds to enemies hit in a frontal cone, reduced to 70% against minions. Danger Zone Bonus: Flamespitter's damage is increased by 50%. Flamespitter's damage based on the target's health ratio against monsters is capped at 65–300 (based on level).","img":"RumbleFlameThrower.png","cd":"10/9/8/7/6","cost":"0","range":"600"},"W":{"name":"Scrap Shield","desc":"Active: Rumble generates 20 Heat to grant himself a shield for 1.5 seconds. Rumble also gains bonus movement speed for 1 to 1.32 seconds. Danger Zone Bonus: Scrap Shield's shield strength and bonus movement speed are increased in effectiveness by 50%.","img":"RumbleShield.png","cd":"6","cost":"0","range":"20"},"E":{"name":"Electro Harpoon","desc":"Active: Rumble generates 20 Heat to shoot a harpoon in the target direction that deals magic damage to the first enemy hit, inflicting them with magic resistance reduction for 4 seconds and slowing them for 2 seconds. These effects stack additively with multiple harpoons, refreshing their duration and stacking up to 2 times. Rumble periodically stocks an Electro Harpoon charge, up to a maximum of 2.","img":"RumbleGrenade.png","cd":"0.5","cost":"0","range":"850"},"R":{"name":"The Equalizer","desc":"Active: Rumble deploys a barrage of rockets along the target path that land in a line over 0.75 seconds, creating a field of fire for 4.5 seconds after the last rocket lands. Enemies struck by the impact or within the field are marked as Burning for 1 second, which deals magic damage every 0.5 seconds, slows by 35%, and refreshes continuously while in the area.","img":"RumbleCarpetBomb.png","cd":"130/105/80","cost":"0","range":"1750"}},"Ryze":{"title":"the Rune Mage","passive":{"name":"Arcane Mastery","desc":"Innate: Ryze increases his maximum mana by (10% per 100 AP).","img":"Ryze_P.png"},"Q":{"name":"Overload","desc":"Passive: Ryze's other basic ability casts reset Overload's cooldown and charge a Rune stack for 4 seconds, refreshing on subsequent casts and stacking up to 2 times. Active: Ryze unleashes a runic blast in the target direction that deals magic damage to the first enemy hit and consumes all Rune stacks. If Ryze consumed 2 stacks, he gains bonus movement speed for 2 seconds.","img":"RyzeQWrapper.png","cd":"5","cost":"40/38/36/34/32","range":"1000"},"W":{"name":"Rune Prison","desc":"Active: Ryze seizes the target enemy, dealing magic damage and slowing them by 50% for 1.5 seconds. Flux Bonus: The target is rooted instead of slowed.","img":"RyzeW.png","cd":"11/10.5/10/9.5/9","cost":"50/60/70/80/90","range":"615"},"E":{"name":"Spell Flux","desc":"Active: Ryze projects an orb upon the target enemy that deals magic damage. The target and surrounding enemies are also marked with Flux for 4 seconds. Ryze's basic abilities against Flux targets consume the mark to become empowered with an additional effect. Flux Bonus: Spell Flux spreads farther.","img":"RyzeE.png","cd":"3.5/3.25/3/2.75/2.5","cost":"35/45/55/65/75","range":"615"},"R":{"name":"Realm Warp","desc":"Passive: Overload's Flux empowered damage is increased. Active: Ryze channels for 2 seconds to open a portal beneath him, marking the target location as its destination and granting sight of the area. Ryze is able to act while channeling, but the portal will cancel if he is interrupted. Upon completion, Ryze and allied units within will blink to the location and become rooted, disarmed, silenced and untargetable for 0.75 seconds.","img":"RyzeR.png","cd":"180/160/140","cost":"100","range":"3000"}},"Samira":{"title":"the Desert Rose","passive":{"name":"Daredevil Impulse","desc":"Innate: Samira's damaging basic attacks and abilities against at least one enemy champion different from the previous damaging hit made against champions generate a stack of Style for 6 seconds, refreshing on subsequent hits and stacking up to 6 times.","img":"SamiraP.png"},"Q":{"name":"Flair","desc":"Active: Samira fires a shot in the target direction that deals physical damage to the first enemy hit. If a targetable enemy is in front of Samira at the time of cast, she will instead slash with her blade in a cone, dealing the same damage to enemies hit. If Flair is cast during Wild Rush, Samira deploys explosives in her wake that detonate upon the end of the dash, dealing the same damage to enemies hit.","img":"SamiraQ.png","cd":"6/5/4/3/2","cost":"30","range":"950"},"W":{"name":"Blade Whirl","desc":"Active: Samira spins her blade over 0.75 seconds, destroying all hostile non-turret projectiles within the area for the duration. Samira slashes twice during Blade Whirl, each one dealing physical damage to all nearby enemies. The first slash occurs immediately and the second one occurs after the duration. Samira cannot basic attack nor cast Flair during Blade Whirl. Casting Inferno Trigger will end Blade Whirl early.","img":"SamiraW.png","cd":"30/28/26/24/22","cost":"60","range":"325"},"E":{"name":"Wild Rush","desc":"Active: Samira dashes a fixed distance in the direction of the target enemy or enemy structure, dealing magic damage to enemies she passes through. She also gains bonus attack speed for 5 seconds. Scoring a takedown against an enemy champion within 3 seconds of damaging them resets Wild Rush's cooldown. Flair and Inferno Trigger can be cast during the dash. Casting Blade Whirl will buffer it to cast at the end of the dash.","img":"SamiraE.png","cd":"20/18/16/14/12","cost":"40","range":"600"},"R":{"name":"Inferno Trigger","desc":"Active: Samira unleashes a torrent of shots for 2.277 seconds, reducing her movement speed by 30% and rapidly shooting at nearby enemies over 2.013 seconds at sporadic times in 0.2-second intervals each (10 times per enemy), dealing physical damage with each shot, reduced by 75% against minions. This damage is affected by critical strike modifiers and applies life steal at 50% effectiveness.","img":"SamiraR.png","cd":"5","cost":"0","range":"600"}},"Sejuani":{"title":"Fury of the North","passive":{"name":"Fury of the North","desc":"Innate - Icebreaker: Enemies stunned by Sejuani are marked Frozen for the disable's duration. Sejuani's next basic attack or ability against a Frozen enemy will consume the mark to deal bonus magic damage equal to 10% of their maximum health, capped at 250 against epic monsters.","img":"Sejuani_passive.png"},"Q":{"name":"Arctic Assault","desc":"Active: Bristle dashes to the target location until he collides with an enemy champion, dealing magic damage to enemies he passes through and knocking them up for 0.5 seconds. Arctic Assault can be cast during her other abilities without cancelling them and vice versa. Arctic Assault will cast at max range if cast beyond that.","img":"SejuaniQ.png","cd":"18/16.5/15/13.5/12","cost":"60/65/70/75/80","range":"650"},"W":{"name":"Winter's Wrath","desc":"Active: After 0.25 seconds into the cast time, Sejuani swings her flail in a cone in the target direction that deals physical damage to enemies hit and knocks back minions and monsters hit. After the cast time, Sejuani lashes out with her flail in a line in the same direction, dealing physical damage to enemies hit and slowing them by 75% for 0.25 seconds. Sejuani can move during Winter's Wrath's cast time.","img":"SejuaniW.png","cd":"9/8/7/6/5","cost":"60","range":"600"},"E":{"name":"Permafrost","desc":"Passive: Winter's Wrath and both Sejuani's and nearby allied melee champions' attacks on-hit apply stacks of Frost to enemy champions, medium or large monsters, and large minions for 5 seconds, refreshing on subsequent applications and stacking up to 4 times, though not applying if the target is Frozen. Enemies hit by Permafrost or Glacial Prison's bola have all of their Frost stacks consumed. Enemy champions cannot be affected by Frost for 8 seconds after having it consumed. Sejuani can cast Permafrost against an enemy with 4 stacks.","img":"SejuaniE.png","cd":"1.5","cost":"20","range":"560"},"R":{"name":"Glacial Prison","desc":"Active: Sejuani throws an ice bola in the target direction that stops upon hitting an enemy champion, dealing magic damage and stunning them for 1 second.","img":"SejuaniR.png","cd":"120/105/90","cost":"100","range":"1300"}},"Senna":{"title":"the Redeemer","passive":{"name":"Absolution","desc":"Innate - Weakened Soul: Senna's basic attacks on-hit and ability hits against enemy champions apply a stack of Mist for 4 seconds, modified to 0.75 seconds if Senna starts winding up a basic attack on them, and limited to once per target per cast. Subsequent hits will collect Mist and deal bonus physical damage equal to 1%–10% (based on level) of target's current health, rendering the target immune to further Mist infliction for a few seconds. This damage applies life steal at 100% effectiveness.","img":"Senna_Passive.png"},"Q":{"name":"Piercing Darkness","desc":"Active: Senna fires a spectral laser in the direction of the target unit, healing herself and allied champions hit, and dealing physical damage to enemies hit in a thinner line. Enemies hit are slowed by 15% (+ 15% per 100 bonus AD) (+ 10% per 100 AP) for a duration. The damage dealt to enemy champions applies life steal at 100% effectiveness.","img":"SennaQ.png","cd":"15","cost":"70/80/90/100/110","range":"600"},"W":{"name":"Last Embrace","desc":"Active: Senna throws a globule of Black Mist in the target direction that deals physical damage to the first enemy hit and attaches to them for 1 second. After the duration or when the target dies, the Black Mist spreads out of the target, rooting them and surrounding enemies for a few seconds.","img":"SennaW.png","cd":"11","cost":"50/55/60/65/70","range":"1250"},"E":{"name":"Curse of the Black Mist","desc":"Active: Senna surrounds herself with an aura of mist and gains camouflage for a duration. If Senna breaks the camouflage, she regains it after 1.75 seconds without performing actions that break stealth. Allied champions who enter the mist gain Wraith Form for a duration equal to the aura's remaining duration.","img":"SennaE.png","cd":"26/24.5/23/21.5/20","cost":"70","range":"400"},"R":{"name":"Dawning Shadow","desc":"Active: Senna fires two waves of spectral light in the target direction, granting sight of the area briefly along the path. The center wave deals physical damage to enemy champions hit and reveals them for 3 seconds, as well as hits all Mist Wraiths. The broad wave grants a shield to Senna and allied champions hit for 3 seconds.","img":"SennaR.png","cd":"140/120/100","cost":"100","range":"25000"}},"Seraphine":{"title":"the Starry-Eyed Songstress","passive":{"name":"Stage Presence","desc":"Innate - Echo: Seraphine's basic ability casts each generate a stack of Echo, stacking up to 2 times. At 2 stacks, Seraphine's next basic ability casts an additional time for 1 mana after a 0.033 seconds delay, consuming all Echo stacks after the cast time of the second cast.Seraphine gains maximum stacks of Echo when the game starts and upon respawning.","img":"Seraphine_Passive.png"},"Q":{"name":"High Note","desc":"Active: Seraphine hurls a soundwave to the target location that quickly expands in a radius upon arrival, dealing magic damage to enemies within the area. Against champions, the damage is increased by 0%–75% (based on target's missing health). High Note will cast at max range if cast beyond that.","img":"SeraphineQ.png","cd":"8/7.5/7/6.5/6","cost":"60/70/80/90/100","range":"900"},"W":{"name":"Surround Sound","desc":"Active: Seraphine grants a shield to herself and nearby allied champions for 2.5 seconds. For the same duration, she also gains 20% (+ 2% per 100 AP) decaying bonus movement speed and grants allies 8% (+ 0.8% per 100 AP) bonus movement speed. If Seraphine already had a shield at the time of cast, Surround Sound will pulse after the duration, healing herself and nearby allied champions, increased for each ally.","img":"SeraphineW.png","cd":"22","cost":"70/75/80/85/90","range":"800"},"E":{"name":"Beat Drop","desc":"Active: Seraphine fires a heavy soundwave in the target direction that deals magic damage to enemies hit, reduced to 70% against minions, and slows them by 99% for a few seconds. Enemies that are already slowed are also rooted for the same duration. Enemies that are immobilized or grounded are also stunned for the same duration.","img":"SeraphineE.png","cd":"11/10.5/10/9.5/9","cost":"60","range":"1300"},"R":{"name":"Encore","desc":"Active: Seraphine projects a captivating force in the target direction that deals magic damage to enemies hit, charms them, during which they are revealed, and slows them by 40% for a duration, increasing by 15% every 0.25 seconds over the duration up to 99%. Encore's projectile resets its remaining travel distance whenever it hits an allied or enemy champion, excluding Seraphine. Allied champions hit gain 4 Notes.","img":"SeraphineR.png","cd":"160/140/120","cost":"100","range":"25000"}},"Sett":{"title":"the Boss","passive":{"name":"Pit Grit","desc":"Innate - Heart of the Half-Beast: Sett regenerates[ an additional 0.075 / 0.25 / 0.5 / 1 (based on level) health every 0.5 seconds per 5% of his missing health. ][ up-to an additional 1.425 / 4.75 / 9.5 / 19 (based on level) health per 0.5 seconds, with the maximum reached at the threshold of 95% missing health. ]","img":"Sett_P.png"},"Q":{"name":"Knuckle Down","desc":"Active: Sett empowers his next two basic attacks within 5 seconds to gain 50 bonus range and deal bonus physical damage, capped at 400 total damage of each attack against monsters. For 1.5 seconds, Sett also gains 30% bonus movement speed while facing visible enemy champions within 2000 units.","img":"SettQ.png","cd":"9/8/7/6/5","cost":"0","range":"0"},"W":{"name":"Haymaker","desc":"Passive: Sett stores 100% of post-mitigation damage taken as Grit on his resource bar, up to a cap of 50% of his maximum health. Each instance of stored Grit decays in value by 30% every second after 4 seconds.","img":"SettW.png","cd":"18/16.5/15/13.5/12","cost":"0","range":"25000"},"E":{"name":"Facebreaker","desc":"Active: Sett pulls in enemies at his front and back along the target direction, dealing physical damage and slowing them by 70% for 0.5 seconds. Facebreaker deals 100 bonus physical damage to monsters. If Facebreaker affects at least one enemy on each side, all enemies are stunned for 1 second upon landing. If no enemies are hit, Sett is unable to move or attack for 0.25 seconds after Facebreaker's cast time.","img":"SettE.png","cd":"16/14.5/13/11.5/10","cost":"0","range":"490"},"R":{"name":"The Show Stopper","desc":"Active: Sett suppresses and reveals the target enemy champion while dashing with displacement immunity to their location and attaching them to himself upon arrival. He leaps another 600 units in the same direction to slam the target into the ground, creating a massive shockwave and quickly sliding forward 250 units beyond the impact.","img":"SettR.png","cd":"120/100/80","cost":"0","range":"400"}},"Shaco":{"title":"the Demon Jester","passive":{"name":"Backstab","desc":"Innate: Shaco's basic attacks are empowered to deal 20–35 (based on level) (+ 30% bonus AD) bonus physical damage when hitting an enemy from behind. Backstab is affected by critical strike modifiers. Deceive and Two-Shiv Poison have additional effects when they hit an enemy from behind.","img":"Jester_CarefulStrikes.png"},"Q":{"name":"Deceive","desc":"Active: Shaco becomes invisible for a duration, and after a 0.125-second delay, he blinks to the target location. Deceive's invisibility breaks when Shaco uses a basic attack or casts Two-Shiv Poison or Recall, but not from casting Jack in the Box or Hallucinate. After breaking the invisibility, Shaco empowers his next basic attack within 0.25 seconds to deal bonus physical damage, which is affected by critical strike modifiers.","img":"Deceive.png","cd":"13/12.5/12/11.5/11","cost":"40","range":"400"},"W":{"name":"Jack In The Box","desc":"Active: Shaco summons a box at the target location that becomes stealthed after arming over 2 seconds, lasting for up to 40 (+ 10% AP) seconds. The box is invulnerable and untargetable to enemies while stealthed.","img":"JackInTheBox.png","cd":"15","cost":"70/65/60/55/50","range":"500"},"E":{"name":"Two-Shiv Poison","desc":"Passive: Shaco's basic attacks slow enemies for 2 seconds while Two-Shiv Poison is not on cooldown. Active: Shaco throws a dagger at the target enemy that deals magic damage, increased by 50% if they are below 30% of their maximum health, and slows them for 3 seconds.","img":"TwoShivPoison.png","cd":"8","cost":"75","range":"625"},"R":{"name":"Hallucinate","desc":"Active: Shaco vanishes for 0.5 seconds and blinks in the target direction while creating a clone of himself that is summoned in the opposite direction, remaining within control range of him as a controllable clone for up to 18 seconds. Hallucinate can be recast at any time while the clone is alive, and can be used while affected by cast-inhibiting crowd control. Recast: Shaco commands the clone to move to the target location.","img":"HallucinateFull.png","cd":"100/90/80","cost":"100","range":"200"}},"Shen":{"title":"the Eye of Twilight","passive":{"name":"Ki Barrier","desc":"Innate: After completing an ability's effects, Shen grants himself a shield for 47–120 (based on level) (+ 13% bonus health) for 2.5 seconds. If Shen affects at least one other champion with an ability, Ki Barrier's cooldown is reduced by 4–8 (based on level) seconds. Shen manifests a Spirit Blade that he can control with Twilight Assault and Spirit's Refuge.","img":"Shen_Passive.png"},"Q":{"name":"Twilight Assault","desc":"Active: Shen recalls his Spirit Blade to his location. Enemy champions hit are slowed for the next 2 seconds while moving away from Shen. Once it arrives, Shen empowers his next 3 basic attacks within 8 seconds to gain 75 bonus range and deal bonus magic damage. Against structures, only the flat damage portion is applied.","img":"ShenQ.png","cd":"8/7.25/6.5/5.75/5","cost":"140/130/120/110/100","range":"400"},"W":{"name":"Spirit's Refuge","desc":"Active: Shen primes his Spirit Blade, creating an area around it. After 2 seconds, or when Shen or an allied champion enters the area, the Spirit Blade generates a protective zone for 1.75 seconds, blocking all non-turret basic attacks that hit Shen or allied champions in the area.","img":"ShenW.png","cd":"16/14.5/13/11.5/10","cost":"40","range":"400"},"E":{"name":"Shadow Dash","desc":"Passive: Dealing damage with Twilight Assault or Shadow Dash restores 30 / 40 / 50 (based on level) energy. Active: Shen dashes to the target location, dealing physical damage to enemy champions and monsters he passes through and taunting them for 1.5 seconds. Twilight Assault and Spirit's Refuge can be cast during the dash. Shadow Dash will cast at max range if cast beyond that.","img":"ShenE.png","cd":"18/16/14/12/10","cost":"150","range":"600"},"R":{"name":"Stand United","desc":"Active: Shen focuses his will, channeling for 3 seconds and granting the target allied champion a shield for 5 seconds at the time of cast, increased by 0%–60% (based on target's missing health). Upon completing the channel, Shen and his Spirit Blade blink to the target ally's location, placed between them and the nearest enemy champion. Shen also destroys any projectiles targeting him at the time of completion.","img":"ShenR.png","cd":"200/180/160","cost":"0","range":"35000"}},"Shyvana":{"title":"the Half-Dragon","passive":{"name":"Scalemail","desc":"Innate: Shyvana gains 5 bonus armor and 5 bonus magic resistance, which are each increased by 5 for every elemental drake and Elder Dragon her team slays. Additionally, Shyvana deals 20% increased damage to Dragons.","img":"Shyvana_Passive.png"},"Q":{"name":"Emberstrike","desc":"Active: Shyvana empowers her next basic attack within 6 seconds to gain 25 bonus range, deal 100% AD (+ 50% AP) physical damage, and cause her to strike again after 0.25 seconds to deal bonus physical damage.The second strike applies on-hit effects, triggers on-attack effects, and can critically strike for (175% + 40%) damage if the triggering attack does.","img":"ShyvanaQ.png","cd":"10/9/8/7/6","cost":"0","range":"25000"},"W":{"name":"Inferno Aegis","desc":"Active: Shyvana surrounds herself in flames for 3 seconds, gaining decaying bonus movement speed and dealing magic damage every 0.5 seconds to nearby enemies. During this time, Shyvana's basic attacks deal bonus magic damage on-hit to surrounding enemies and extend the duration of Burnout by 1 second, which can occur up to 4 times for a total of 4 additional seconds.","img":"ShyvanaW.png","cd":"13/12.25/11.5/10.75/10","cost":"0","range":"350"},"E":{"name":"Molten Burst","desc":"Active: Shyvana unleashes a fireball in the target direction that stops upon hitting an enemy champion, dealing magic damage to all enemies hit and marking them for 5 seconds. Shyvana's basic attacks against marked enemies are empowered to deal bonus magic damage on-hit equal to 3% (+ 1% per 100 bonus AD) of the target's maximum health, capped at 150 against monsters.","img":"ShyvanaE.png","cd":"12/11/10/9/8","cost":"0","range":"800"},"R":{"name":"Dragon's Descent","desc":"Passive - Fury: Dragon's Descent requires 100 Fury to be cast. Shyvana generates Fury per second while alive and in Human form and 2 Fury per basic attack on-hit in either form. Shyvana gains 100 Fury upon learning Dragon's Descent. Active: Shyvana transforms into Dragon Form and dashes with displacement immunity to the target location, dealing magic damage to enemies she passes through and carrying them alongside her.","img":"ShyvanaR.png","cd":"0","cost":"0","range":"1050"}},"Singed":{"title":"the Mad Chemist","passive":{"name":"Noxious Slipstream","desc":"Innate: Whenever Singed moves near a champion, he gains a stack of Noxious Slipstream for 2 seconds, refreshing on subsequent passes and stacking up to 25 times. Noxious Slipstream: For each stack, Singed gains 25% bonus movement speed, up to a maximum of 625%. This effect cannot occur on the same target more than once every few seconds.","img":"Singed_Passive.png"},"Q":{"name":"Poison Trail","desc":"Toggle: Singed continually creates a toxic cloud in his wake that lingers for 3.25 seconds. The cloud inflicts poison to enemies within, and resets the duration every 0.5 seconds while they remain. poison: The target takes magic damage every 0.25 seconds over 2 seconds. Subsequent inflictions refresh the duration.","img":"PoisonTrail.png","cd":"0","cost":"13","range":"20"},"W":{"name":"Mega Adhesive","desc":"Active: Singed spills a potent adhesive that lands at the target location after 0.375 seconds, creating a field for 3 seconds that grounds enemies within and slows them.","img":"MegaAdhesive.png","cd":"17/16/15/14/13","cost":"60/70/80/90/100","range":"1000"},"E":{"name":"Fling","desc":"Active: Singed flings the target enemy 550 units over himself over 0.693 seconds, dealing magic damage. The damage based on the target's health ratio is capped at 300 against minions and monsters. If the target lands on Mega Adhesive's area of effect after the displacement, they are rooted for a duration.","img":"Fling.png","cd":"10/9.5/9/8.5/8","cost":"60/70/80/90/100","range":"125"},"R":{"name":"Insanity Potion","desc":"Active: Singed empowers himself for 25 seconds with ability power, bonus armor, bonus magic resistance, bonus movement speed, bonus health regeneration, and bonus mana regeneration. During this time, Poison Trail additionally applies Grievous Wounds for 1 second, which refreshes every 0.25 seconds while the poison persists.","img":"InsanityPotion.png","cd":"100","cost":"100","range":"20"}},"Sion":{"title":"The Undead Juggernaut","passive":{"name":"Glory in Death","desc":"Innate: Upon taking fatal damage, Sion enters stasis for 1.5 seconds to reanimate into a frenzy, restoring 100% of his maximum health but losing 2.3–24.4 (based on level) health every 0.264 seconds, increasing by[ 70% of the base value ][ 1.61–17.08 (based on level) ]per subsequent tick. Sion's health regeneration and any healing (except life steal) he receives during this time is 0% effective.","img":"Sion_Passive1.png"},"Q":{"name":"Decimating Smash","desc":"Active: Sion prepares a strike in the target direction, charging for up to 2 seconds to increase Decimating Smash's range over an area, knock up duration, stun duration, and damage every 0.25 seconds, which has up to a maximum bonus for the base damage and up to a 200% bonus for the scaling damage.","img":"SionQ.png","cd":"10/9/8/7/6","cost":"45","range":"10000"},"W":{"name":"Soul Furnace","desc":"Passive: Sion gains 4 bonus health whenever he kills an enemy, increased to 15 for large enemies and takedowns against enemy champions. Active: Sion grants himself a shield that lasts for up to 6 seconds. Soul Furnace can be recast after 3 seconds while the shield holds, and does so automatically at the end of the duration.","img":"SionW.png","cd":"15/14/13/12/11","cost":"75/80/85/90/95","range":"500"},"E":{"name":"Roar of the Slayer","desc":"Active: Sion bellows a shockwave in the target direction that deals magic damage to the first enemy hit, slows them for 2.5 seconds and inflicts them with 20% armor reduction for 4 seconds.","img":"SionE.png","cd":"12/11/10/9/8","cost":"35/40/45/50/55","range":"800"},"R":{"name":"Unstoppable Onslaught","desc":"Active: Sion becomes immune to crowd control and ghosted and, after a brief delay, charges forward in the direction of the cursor for up to 8 seconds, during which he is able to steer at a slow turn rate while automatically navigating his movement. Unstoppable Onslaught can be recast after 0.4 seconds during the channel.","img":"SionR.png","cd":"140/100/60","cost":"100","range":"7500"}},"Sivir":{"title":"the Battle Mistress","passive":{"name":"Fleet of Foot","desc":"Innate: Sivir's basic attacks and ability hits against enemy champions grant her 55–75 (based on level) bonus movement speed decaying over 1.5 seconds, refreshing on subsequent hits.","img":"Sivir_Passive.png"},"Q":{"name":"Boomerang Blade","desc":"Active: Sivir hurls her crossblade in the target direction, dealing physical damage to enemies within its path, increased by 0%–50% (based on critical strike chance). Boomerang Blade's damage is reduced by 0%–60% (based on non-champions hit). Upon reaching maximum range, the crossblade returns to her, resetting the damage modifier and dealing the same damage to enemies on its way back. Enemies can be hit only once per pass.","img":"SivirQ.png","cd":"10/9.5/9/8.5/8","cost":"55/60/65/70/75","range":"1200"},"W":{"name":"Ricochet","desc":"Active: Sivir empowers her crossblade for the next 4 seconds, gaining bonus attack speed and causing her basic attacks to bounce to additional surrounding enemies, dealing them physical damage. If the triggering attack critically strikes, the bounces will do so as well for (175% + 40%) damage. Ricochet deals 65% damage against minions and executes them if they would be left below 15 health.","img":"SivirW.png","cd":"12","cost":"60","range":"20"},"E":{"name":"Spell Shield","desc":"Active: Sivir gains a spell shield for 1.5 seconds. Upon successfully blocking a hostile effect, she heals herself and activates Fleet of Foot after 0.25 seconds.","img":"SivirE.png","cd":"24/22.5/21/19.5/18","cost":"0","range":"20"},"R":{"name":"On The Hunt","desc":"Active: Sivir gains On the Hunt for a duration and grants it to nearby allied champions for the remaining duration. On the Hunt: Gain bonus movement speed. While active, Sivir's basic attacks on-attack reduce her basic abilities' current cooldowns by 0.5 seconds each. Sivir can refresh the duration of her On the Hunt buff whenever she scores a takedown against an enemy champion within 3 seconds of damaging them.","img":"SivirR.png","cd":"120/100/80","cost":"100","range":"1000"}},"Skarner":{"title":"the Primordial Sovereign","passive":{"name":"Threads of Vibration","desc":"Innate: Skarner's basic attacks on-hit, Shattered Earth, Upheaval, and Impale apply a stack of Quaking to enemies hit for 4 seconds, refreshing on subsequent applications and stacking up to 3 times. Enemies afflicted with 3 stacks take magic damage equal to [ 5%–9% (based on level) of their maximum health over the duration, capped at 100–300 (based on level) against monsters. ][ 0.63%–1.13% (based on level) of their maximum health every 0.5 seconds over the duration, capped at 12.5–37.5 (based on level) per tick against monsters. ]","img":"Skarner_Passive.png"},"Q":{"name":"Shattered Earth / Upheaval","desc":"Active: Skarner rips a boulder from the ground, empowering up to three of his next basic attacks within 5 seconds of each other. These attacks gain 25 bonus range, bonus attack speed, and deal bonus physical damage to the target and surrounding enemies, including structures.","img":"SkarnerQ.png","cd":"8/6.75/5.5/4.25/3","cost":"30","range":"400"},"W":{"name":"Seismic Bastion","desc":"Active: Skarner slams his claws into the ground, shielding himself equal to 8% of his maximum health for 2.5 seconds and releasing a shockwave that quickly expands in a radius around him to deal magic damage to enemies hit and slow them by 20% for 1 second. Skarner can move during Seismic Bastion's cast time.","img":"SkarnerW.png","cd":"10/9/8/7/6","cost":"60/65/70/75/80","range":"700"},"E":{"name":"Ixtal's Impact","desc":"Active: Skarner charges forward in the direction of the cursor for up to 2.75 seconds, during which he gains slow immunity, becomes ghosted, ignores terrain collision, and has unobstructed vision of the surrounding 650 units. He automatically navigates his movement along the way and is able to steer himself with a slow turn rate that increases over time, resetting upon changing direction. Ixtal's Impact can be recast after 1 second, and does so automatically after the duration.","img":"SkarnerE.png","cd":"22/21/20/19/18","cost":"50/55/60/65/70","range":"1700"},"R":{"name":"Impale","desc":"Active: Skarner winds up his stingers over the cast time, then lashes them forward in an isosceles trapezoid in the target direction, dealing magic damage to enemies hit and impaling up to 3 of the closest enemy champions within the area to suppress them for 1.5 seconds. While suppressed, the targets are revealed and attached to Skarner. If he successfully impales at least one enemy champion, Skarner gains 40% bonus movement speed for the same duration.","img":"SkarnerR.png","cd":"120/105/90","cost":"100","range":"625"}},"Smolder":{"title":"the Fiery Fledgling","passive":{"name":"Dragon Practice","desc":"Innate: Smolder generates a stack of Dragon Practice each time he hits an enemy champion with an ability, or whenever Super Scorcher Breath kills a minion or monster. His basic abilities deal bonus magic damage based on stacks. Super Scorcher Breath: Deals bonus magic damage equal to 30%–52.5% (+ 0%–12%) (based on critical strike chance) of Dragon Practice stacks. Achooo!: Explosions deal bonus magic damage equal to 55% of Dragon Practice stacks. Flap, Flap, Flap: Attacks each deal bonus magic damage equal to 10% of Dragon Practice stacks.","img":"Icons_Smolder_Passive.png"},"Q":{"name":"Super Scorcher Breath","desc":"Active: Smolder spits a fireball at the target enemy that deals physical damage, increased by 0%–75% (+ 0%–40%) (based on critical strike chance); applies on-hit effects; applies life steal at 50% effectiveness; and triggers on-attack effects. If Super Scorcher Breath kills at least one target, Smolder restores 15 mana. Super Scorcher Breath becomes empowered with new effects based on the number of Dragon Practice stacks:","img":"SmolderQ.png","cd":"5.5/5/4.5/4/3.5","cost":"25","range":"550"},"W":{"name":"Achooo!","desc":"Active: Smolder sneezes a fiery glob in the target direction that deals physical damage to enemies hit and slows them by 35% for 1.5 seconds, slowing down in missile speed after travelling 1200 units. Hitting an enemy champion creates an explosion that deals physical damage to nearby enemies, with subsequent explosions against the same target dealing 75% damage of the previous explosion's damage.","img":"SmolderW.png","cd":"14/13/12/11/10","cost":"50/55/60/65/70","range":"1500"},"E":{"name":"Flap, Flap, Flap","desc":"Active: Smolder takes flight for 1.25 seconds, becoming ghosted and gaining 75% bonus movement speed, unobstructed vision, and the ability to ignore terrain collision. While in flight, he automatically fires up to 5 (+ 1 per 100 Dragon Practice stacks) bolts at the nearest and most wounded visible enemy, dealing physical damage with each hit and prioritizing enemy champions.","img":"SmolderE.png","cd":"24/22/20/18/16","cost":"65","range":"700"},"R":{"name":"MMOOOMMMM!","desc":"Active: Smolder shouts for his mother to attack from above, causing her to exhale a wave of fire from behind him and towards the target direction, granting sight of its surroundings as it travels. The wave heals Smolder and deals physical damage to enemies hit, with those in the center taking 50% increased damage and becoming slowed by 40% for 2 seconds. MMOOOMMMM! deals 50% damage against minions and monsters.","img":"SmolderR.png","cd":"120/110/100","cost":"100","range":"4200"}},"Sona":{"title":"Maven of the Strings","passive":{"name":"Power Chord","desc":"Innate - Accelerando: Sona generates a stack of Accelerando each time she hits an enemy champion with Hymn of Valor and each time she mitigates sufficient damage or heals damaged allies with Aria of Perseverance, stacking up to 120 times. At maximum stacks, she instead reduces the current cooldown of Crescendo by 1.5 seconds each time. Accelerando: For each stack, Sona gains 0.5 basic ability haste, up to 60 at maximum stacks.","img":"Sona_Passive_Charged.png"},"Q":{"name":"Hymn of Valor","desc":"Active: Sona sends out bolts of sound to the two nearest visible enemies, prioritizing champions. Each bolt deals magic damage and grants sight of the area around the target for 1 second.Sona gains a stack of Accelerando for each bolt that hits an enemy champion. Melody Bonus: Sona and tagged allied champions deal bonus magic damage on their next basic attack within 5 seconds.","img":"SonaQ.png","cd":"8","cost":"50/55/60/65/70","range":"825"},"W":{"name":"Aria of Perseverance","desc":"Active: Sona heals herself and sends out a tone to heal the most wounded allied champion nearby. Melody Bonus: Sona and tagged allied champions are granted a shield for 1.5 seconds. Sona gains a stack of Accelerando whenever she heals a wounded ally or shields a minimum amount of damage for an ally with Aria of Perseverance.","img":"SonaW.png","cd":"10","cost":"80/85/90/95/100","range":"1000"},"E":{"name":"Song of Celerity","desc":"Active: Sona gains 20% (+ 2% per 100 AP) bonus movement speed for 7 seconds. If she takes damage during this time, the duration ends prematurely once or if 3 seconds have elapsed. Melody Bonus: Tagged allied champions gain bonus movement speed for 3 seconds.","img":"SonaE.png","cd":"14","cost":"65","range":"430"},"R":{"name":"Crescendo","desc":"Active: Sona strikes an irresistible chord in the target direction that deals magic damage to enemies hit and stuns them for 1.5 seconds.","img":"SonaR.png","cd":"140/120/100","cost":"100","range":"900"}},"Soraka":{"title":"the Starchild","passive":{"name":"Salvation","desc":"Innate: Soraka gains 90% bonus movement speed while facing nearby allied champions that are below 40% of their maximum health.","img":"Soraka_Passive.png"},"Q":{"name":"Starcall","desc":"Active: Soraka calls down a star upon the target location that grants sight of the area before landing after 0.25–1 (based on target range) seconds, dealing magic damage to enemies hit and slowing them by 30% for 1.5 seconds.","img":"SorakaQ.png","cd":"8/7/6/5/4","cost":"45/50/55/60/65","range":"810"},"W":{"name":"Astral Infusion","desc":"Active: Soraka heals the target allied champion. If cast while under Rejuvenation, the health cost will be reduced by a percentage. Astral Infusion cannot be cast if Soraka is below 5% of her maximum health.","img":"SorakaW.png","cd":"6/5/4/3/2","cost":"40/45/50/55/60","range":"550"},"E":{"name":"Equinox","desc":"Active: Soraka creates a celestial zone at the target location that deals magic damage to enemy champions within at the time of cast. The zone then persists for 1.5 seconds and silences enemies within. Afterwards, the zone erupts to deal the same damage to enemy champions within and root them for a duration.","img":"SorakaE.png","cd":"20/19/18/17/16","cost":"70/75/80/85/90","range":"925"},"R":{"name":"Wish","desc":"Active: Soraka calls upon the stars, healing herself and all allied champions, increased by 50% on targets below 40% of their maximum health.","img":"SorakaR.png","cd":"150/135/120","cost":"100","range":"25000"}},"Swain":{"title":"the Noxian Grand General","passive":{"name":"Ravenous Flock","desc":"Innate: Enemy champions that die will leave behind a Soul Fragment for 16 seconds, which can be collected by Swain after 1 second. Swain's ravens collect nearby Soul Fragments, as well as with Vision of Empire and Nevermove. Soul Fragment: For each stack, Swain gains 15 bonus health permanently. Upon collection, he will heal for 3%–6% (based on level) of his maximum health.","img":"Swain_P.png"},"Q":{"name":"Death's Hand","desc":"Active: Swain unleashes five bolts of eldritch power over 0.264 seconds in a cone in the target direction that deal magic damage to enemies hit. Subsequent bolts against an enemy deal 25% bonus damage.","img":"SwainQ.png","cd":"7/6/5/4/3","cost":"40/45/50/55/60","range":"750"},"W":{"name":"Vision of Empire","desc":"Active: Swain summons a demonic eye at the target location that grants sight of the area for 2 seconds and explodes after 1.5 seconds, dealing magic damage to enemies within, halved against minions, and slowing them for 1.5 seconds. Enemy champions hit are also revealed for 6 seconds and have a Soul Fragment collected from them.","img":"SwainW.png","cd":"22/21/20/19/18","cost":"60/65/70/75/80","range":"5500/6000/6500/7000/7500"},"E":{"name":"Nevermove","desc":"Active: Swain launches a demonic wave in the target direction. At maximum range, the wave homes back to Swain and detonates upon the first enemy hit, dealing magic damage to nearby enemies and rooting them for 1.5 seconds, during which they are revealed. Nevermove can be recast while champions hit are rooted.","img":"SwainE.png","cd":"12/11.5/11/10.5/10","cost":"50/55/60/65/70","range":"850"},"R":{"name":"Demonic Ascension","desc":"Active: Swain frees the demon within himself, gaining Demonic Ascension and generating 50 Demonic Energy. Demonic Ascension is maintained with Demonic Energy, which decays by 5 every 0.5 seconds, increased to 7.5 after 5 seconds have elapsed, and is lost once all Demonic Energy is depleted to 0. Swain generates 10 Demonic Energy every 0.5 seconds while draining from at least one enemy champion, and fully restores it to the maximum of 50 upon scoring a champion takedown.","img":"SwainR.png","cd":"120","cost":"100","range":"650"}},"Sylas":{"title":"the Unshackled","passive":{"name":"Petricite Burst","desc":"Innate: Whenever Sylas casts an ability, he generates a stack of Unshackled for 4 seconds, refreshing on subsequent casts and stacking up to 3 times. Unshackled: Sylas' next basic attack gains 125% bonus attack speed and is empowered to consume a stack to whirl his chains around him, which has an uncancellable windup and deals 130% AD (+ 30% AP) magic damage to the primary target and 40% AD (+ 20% AP) magic damage to nearby enemies.","img":"SylasP.png"},"Q":{"name":"Chain Lash","desc":"Active: Sylas lashes out two chains that converge to the target location and extend beyond it up to a maximum range, dealing magic damage to enemies hit and slowing them for 1.5 seconds. After a 0.6-second delay, the chains' intersection explodes to deal magic damage to enemies within, reduced to 40% against minions. Chain Lash will cast at max range if cast beyond that.","img":"SylasQ.png","cd":"10/9/8/7/6","cost":"55","range":"775"},"W":{"name":"Kingslayer","desc":"Active: Sylas dashes to the front of the target enemy's location then strikes them to deal magic damage. If this damages a champion, Sylas is also healed, increased by 0%–100% (based on his missing health).","img":"SylasW.png","cd":"12/10.5/9/7.5/6","cost":"50/60/70/80/90","range":"400"},"E":{"name":"Abscond / Abduct","desc":"Active: Sylas dashes to the target location. Within 3.5 seconds, he can cast Abduct after a 0.2-second delay from casting Abscond. Kingslayer can be cast during the dash. Abscond will cast at max range if cast beyond that.","img":"SylasE.png","cd":"13/12/11/10/9","cost":"65","range":"400"},"R":{"name":"Hijack","desc":"Active: Sylas launches his chains at the target enemy champion, gaining a copy of their ultimate ability and revealing them for 0.825 seconds at the start of the cast time. Sylas cannot select the same champion again for a set duration, and can hold the hijacked ultimate for up to 90 seconds, during which he can recast Hijack.","img":"SylasR.png","cd":"80/55/30","cost":"75","range":"950"}},"Syndra":{"title":"the Dark Sovereign","passive":{"name":"Transcendent","desc":"Innate: Syndra collects Splinters of Wrath that enhance each of her abilities based on the number of them collected, stacking up to 120 times. She gains Splinters of Wrath from the following: Dealing two instances of ability damage to an enemy champion within 4 seconds grants 1 / 2 / 3 (based on level) Splinters. This cannot occur on the same target more than once every 8 seconds. Ranking up an ability with any skill points beyond level 1 grants 5 Splinters, up to 85. Killing a large minion grants 1 Splinter.","img":"SyndraPassive.png"},"Q":{"name":"Dark Sphere","desc":"Active: Syndra conjures a Dark Sphere at the target location that appears after a 0.6-second delay, dealing magic damage to nearby enemies. The Dark Sphere then remains on the ground for 6 seconds. Transcendent Bonus: Collecting 40 Splinters of Wrath causes Syndra to periodically stock a Dark Sphere charge, up to a maximum of 2. Dark Sphere will cast at max range if cast beyond that.","img":"SyndraQ.png","cd":"7","cost":"40/45/50/55/60","range":"800"},"W":{"name":"Force of Will","desc":"Active: Syndra grabs the nearest Dark Sphere, enemy minion or non-epic monster within 500 units from the target location, and holds the target for 5 seconds. If a Dark Sphere is grabbed, its duration is refreshed; if a minion or monster is grabbed, it is put in stasis. She prioritizes grabbing the nearest unit, then Dark Spheres. Force of Will can be recast while the target is being held.","img":"SyndraW.png","cd":"12/11/10/9/8","cost":"60/70/80/90/100","range":"925"},"E":{"name":"Scatter the Weak","desc":"Active: Syndra propels a wave of force in a cone in the target direction that deals magic damage to enemies hit and knocks them back for 400 units and up to 800 units away from Syndra based on proximity, though not through terrain.","img":"SyndraE.png","cd":"15","cost":"50","range":"650"},"R":{"name":"Unleashed Power","desc":"Passive: Dark Sphere gains ability haste. Active: Syndra enters a 0.264 seconds cast time, creating 3 Dark Spheres and grabbing up to 4 nearby Dark Spheres that were last spawned. Afterwards, the collected Dark Spheres are barraged at the target enemy champion, each dealing magic damage upon hit. The Dark Spheres will then remain on the ground for 6 seconds.","img":"SyndraR.png","cd":"120/100/80","cost":"100","range":"675"}},"TahmKench":{"title":"The River King","passive":{"name":"An Acquired Taste","desc":"Innate: Tahm Kench's basic attacks on-hit and Tongue Lash are empowered to deal 6–48 (based on level) (+ 1.5% AP per 100 bonus health) (+ 4% of his bonus health) bonus magic damage and apply a stack of An Acquired Taste against enemy champions for 5 seconds, refreshing on subsequent hits and stacking up to 3 times. Stacks expire by one every 0.67 seconds when the duration ends.","img":"TahmKenchP.png"},"Q":{"name":"Tongue Lash","desc":"Active: Tahm Kench lashes his tongue in the target direction that deals magic damage to the first enemy hit and slows them by 50% for 2 seconds. If this hits an enemy champion, Tahm Kench also heals himself. An Acquired Taste Bonus: The target is stunned for 1.5 seconds. Devour can be cast during Tongue Lash at no cost to pull the target to Tahm Kench before swallowing them.","img":"TahmKenchQ.png","cd":"7/6.5/6/5.5/5","cost":"50/46/42/38/34","range":"900"},"W":{"name":"Abyssal Dive","desc":"Active: Tahm Kench channels for 1.35 seconds as he dives into the waters, then blinks to the target location after a 0.15-second delay and remains unable to act for 0.65 seconds after the channel completes. Abyssal Dive grants sight of the area during the channel.","img":"TahmKenchW.png","cd":"21/20/19/18/17","cost":"60/75/90/105/120","range":"1000/1050/1100/1150/1200"},"E":{"name":"Thick Skin","desc":"Passive: Tahm Kench stores a portion of the post-mitigation damage he takes as grey health on his health bar, increased while there are at least 2 nearby visible enemy champions either dead or alive. He can store up to 300% of his maximum health.","img":"TahmKenchE.png","cd":"3","cost":"0","range":"2400"},"R":{"name":"Devour","desc":"Active: Tahm Kench abducts the target champion, pulling them to him over the cast time and then swallowing them to carry them in his belly for up to 3 seconds. While inside, the target is attached to Tahm Kench and is rendered untargetable and displacement immune. Devour can be cast on enemies only with 3 stacks of An Acquired Taste.","img":"TahmKenchRWrapper.png","cd":"0","cost":"100","range":"25000"}},"Taliyah":{"title":"the Stoneweaver","passive":{"name":"Rock Surfing","desc":"Innate: While near terrain, Taliyah gains 10 / 15 / 25 / 40% (based on level) bonus movement speed, which builds up over 1 second while in range for at least 0.4 seconds, and decays at the same rate once out of range for at least 3 seconds. If Taliyah is casting an ability or enters champion combat, Rock Surfing cannot occur again for a few seconds.","img":"Taliyah_Passive.png"},"Q":{"name":"Threaded Volley","desc":"Active: Taliyah barrages 5 Stone Shards in the target direction over 1.5 seconds that each shatter upon the first enemy hit, dealing magic damage to nearby enemies and revealing them for 0.5 seconds. Subsequent hits deal 40% damage. Taliyah can move and cast other abilities while launching Stone Shards, and is unable to basic attack until she launches the third Stone Shard.","img":"TaliyahQ.png","cd":"7/6/5/4/3","cost":"55/60/65/70/75","range":"1000"},"W":{"name":"Seismic Shove","desc":"Active: Taliyah marks the target location and selects a direction. After 0.792 seconds, a ledge erupts from the area that knocks enemies hit 400 units in the target direction over 1 second.","img":"TaliyahWVC.png","cd":"14/12.5/11/9.5/8","cost":"40/30/20/10/0","range":"900"},"E":{"name":"Unraveled Earth","desc":"Active: Taliyah scatters a field of 22 stones across the ground in the target direction that deals magic damage to enemies hit while they erupt. The stones then remain for 4 seconds and slow enemies within the area by 20%. Enemies that dash or are knocked over a stone will detonate it, taking magic damage and becoming stunned for 0.75 seconds, increased to 2 seconds if they are a monster. The stun is applied once the displacement ends.","img":"TaliyahE.png","cd":"14","cost":"90","range":"950"},"R":{"name":"Weaver's Wall","desc":"Active: Taliyah summons a torrent of spiraling rocks that cascades in the target direction, knocking aside champions hit and erecting a wall of terrain in its wake. The wall lasts for 4 seconds after completion, then slowly disintegrates from its starting point. Taliyah also channels for 1 second, during which Weaver's Wall can be recast and she reveals herself.","img":"TaliyahR.png","cd":"180/150/120","cost":"100","range":"2500/4500/6500"}},"Talon":{"title":"the Blade's Shadow","passive":{"name":"Blade's End","desc":"Innate: Talon's abilities apply a stack of Wound to enemy champions and large monsters hit for 6 seconds, refreshing on basic attacks and subsequent applications and stacking up to 3 times.","img":"TalonP.png"},"Q":{"name":"Noxian Diplomacy","desc":"Active: Talon dashes toward the target enemy, stabbing the target upon arrival to deal physical damage. If cast within close range, Talon dashes to the target over the cast time instead and Noxian Diplomacy critically strikes for (150% + 40%) damage, as well as grants him 75 bonus attack range on his next basic attack within 1 second.","img":"TalonQ.png","cd":"8/7.5/7/6.5/6","cost":"40","range":"575"},"W":{"name":"Rake","desc":"Active: Talon throws a fan of daggers in a cone in the target direction that deals physical damage to enemies hit. At maximum range, the daggers linger for 0.7 seconds before homing back to Talon, dealing physical damage to enemies hit and slowing them for 1 second. Enemies can be hit only once per pass.","img":"TalonW.png","cd":"9/8.5/8/7.5/7","cost":"50/55/60/65/70","range":"650"},"E":{"name":"Assassin's Path","desc":"Active: Talon dashes up to 800 units over the target area of terrain, during which he gains unobstructed vision. Talon cannot cast Assassin's Path on the same area of terrain for a set duration. Shadow Assault can be cast during the dash.","img":"TalonE.png","cd":"0","cost":"0","range":"725"},"R":{"name":"Shadow Assault","desc":"Active: Talon disperses a ring of blades around him that deals physical damage to enemies hit and lingers at maximum range for up to 2.5 seconds, during which he gains invisibility and bonus movement speed. Shadow Assault can be recast after 1 second within the duration, and does so automatically after the duration or if Talon breaks stealth.","img":"TalonR.png","cd":"100/80/60","cost":"100","range":"550"}},"Taric":{"title":"the Shield of Valoran","passive":{"name":"Bravado","desc":"Innate: After casting an ability, Taric empowers his next two basic attacks within 5 seconds to each gain 100% total attack speed, deal 25–93 (based on level) (+ 15% bonus armor) bonus magic damage, and reduce the remaining cooldowns of his basic abilities by 1–2 (based on ability haste) seconds.","img":"Taric_Passive.png"},"Q":{"name":"Starlight's Touch","desc":"Active: Taric heals himself and nearby allied champions for 25 (+ 15% AP) (+ 1% of his maximum health) per charge of Starlight's Touch that he periodically stocks, up to a maximum amount. Bravado's empowered attacks each grant one charge. Starlight's Touch can heal up to a maximum of 125 (+ 75% AP) (+ 5% of Taric's maximum health) at 5 charges.","img":"TaricQ.png","cd":"3","cost":"60","range":"325"},"W":{"name":"Bastion","desc":"Passive: Taric gains bonus armor and forms a tether between him and the ally bound by Bastion. While the tether persists, the ally also gains the bonus armor and Taric's abilities are mimicked to them, though the effects do not stack. Active: Taric grants himself and the target allied champion a shield for 2.5 seconds, binding them with Bastion.","img":"TaricW.png","cd":"15","cost":"60","range":"800"},"E":{"name":"Dazzle","desc":"Active: Taric winds up over 1 second, granting ghosting to nearby units, then projects a beam of starlight in the target direction that deals magic damage to enemies hit and stuns them for 1.5 seconds. Taric can move during Dazzle.","img":"TaricE.png","cd":"16/15/14/13/12","cost":"40","range":"610"},"R":{"name":"Cosmic Radiance","desc":"Active: Taric calls down a star from above that descends to him over 2.5 seconds. Afterwards, he and nearby allied champions become invulnerable for 2.5 seconds.","img":"TaricR.png","cd":"180/150/120","cost":"100","range":"400"}},"Teemo":{"title":"the Swift Scout","passive":{"name":"Guerrilla Warfare","desc":"Innate: Teemo gains invisibility after 1.5 seconds without moving, taking damage, performing actions that break stealth, channeling, or being in stasis. Teemo will maintain stealth so long as he remains idle and is not displaced. While in brush, Teemo gains the stealth even while moving and can move without breaking stealth.","img":"TeemoPassive.png"},"Q":{"name":"Blinding Dart","desc":"Active: Teemo shoots a dart at the target enemy that deals magic damage and blinds them for a duration. The duration of the blind is doubled against minions and monsters.","img":"TeemoQ.png","cd":"7","cost":"70/75/80/85/90","range":"680"},"W":{"name":"Move Quick","desc":"Passive: Teemo gains bonus movement speed after 5 seconds without taking damage from enemy champions or turrets. Active: Teemo doubles the bonus movement speed for 3 seconds, preventing it from being removed for the duration. Casting Move Quick does not interrupt Guerrilla Warfare.","img":"TeemoW.png","cd":"14","cost":"40","range":"20"},"E":{"name":"Toxic Shot","desc":"Passive: Teemo's basic attacks are empowered to deal bonus magic damage on-hit and inflict poison. poison: The target takes magic damage every second over 4 seconds. Subsequent inflictions refresh the duration. Toxic Shot deals 145% damage against monsters.","img":"TeemoE.png","cd":"0","cost":"0","range":"680"},"R":{"name":"Noxious Trap","desc":"Active: Teemo tosses a poisonous mushroom to the target location that becomes stealthed after arming over 1 second, lasting for up to 5 minutes and granting sight of its surroundings. If the mushroom lands on an already-placed one, it will bounce forward again for its cast distance, up to a cap, which can happen repeatedly. Teemo periodically stocks a Noxious Trap charge, up to a maximum amount.","img":"TeemoR.png","cd":"0.25","cost":"75/55/35","range":"600/750/900"}},"Thresh":{"title":"the Chain Warden","passive":{"name":"Damnation","desc":"Innate: Thresh's armor does not increase through growth (per level). Innate: Enemy champions, large minions and large monsters that die near Thresh drop a Soul for 8 seconds. Epic monsters drop 2 Souls while lesser minions and monsters have a 33.3% chance to drop a Soul. Thresh automatically collects Souls near him or a placed Dark Passage. Soul: For each stack, Thresh gains 1 ability power and 1 bonus armor.","img":"Thresh_Passive.png"},"Q":{"name":"Death Sentence","desc":"Active: Thresh throws out his scythe in the target direction, becoming unable to move or attack while it is in flight.","img":"ThreshQ.png","cd":"19/16.5/14/11.5/9","cost":"70","range":"1075"},"W":{"name":"Dark Passage","desc":"Active: Thresh throws his lantern to the target location over 0.5 seconds, lasting for 6 seconds while he remains nearby and granting sight of its surroundings. If Thresh moves too far away from the lantern, it returns back to him immediately. Thresh and the first allied champion to come near the lantern are granted a shield for 4 seconds. An ally can select the lantern while in proximity of it, dashing to Thresh and gaining the shield.","img":"ThreshW.png","cd":"21/20/19/18/17","cost":"50/55/60/65/70","range":"950"},"E":{"name":"Flay","desc":"Passive: Thresh's basic attacks are empowered to deal bonus magic damage, with the AD ratio increasing over 10 seconds without basic attacking enemies. Active: Thresh sweeps his chain across the ground in a broad line and a radius around him, starting behind him and towards the target direction. Enemies hit are dealt magic damage and knocked 200 units in the target direction, and then are slowed for 1 second.","img":"ThreshE.png","cd":"13/12.25/11.5/10.75/10","cost":"60/65/70/75/80","range":"500"},"R":{"name":"The Box","desc":"Active: Thresh erects a pentagon of spectral walls around him that each last for 5 seconds. A wall will break upon enemy champion contact, dealing magic damage and slowing them by 99% for 2 seconds. After the first wall breaks, the rest will deal no damage and slow for only 1 second. Enemies that break a wall cannot do so again for 1 second.","img":"ThreshRPenta.png","cd":"120/100/80","cost":"100","range":"450"}},"Tristana":{"title":"the Yordle Gunner","passive":{"name":"Draw a Bead","desc":"Innate: Tristana's basic attacks, Explosive Charge and Buster Shot gain 0–150 (based on level) bonus range, for a total of 550–700 (based on level).","img":"Tristana_Passive.png"},"Q":{"name":"Rapid Fire","desc":"Active: Tristana empowers her cannon, gaining bonus attack speed for 7 seconds.","img":"TristanaQ.png","cd":"20/19/18/17/16","cost":"15/20/25/30/35","range":"20"},"W":{"name":"Rocket Jump","desc":"Active: Tristana jumps to the target location. Upon landing, she deals magic damage to nearby enemies and slows them by 40% for 2 seconds. Scoring an enemy champion takedown or detonating Explosive Charge at maximum stacks on a champion will reset Rocket Jump's cooldown. Tristana can cast any of her abilities during the dash. Rocket Jump will cast at max range if cast beyond that.","img":"TristanaW.png","cd":"22/20/18/16/14","cost":"30/35/40/45/50","range":"900"},"E":{"name":"Explosive Charge","desc":"Passive: Tristana's basic attacks are empowered to trigger an explosion when they kill the target, dealing magic damage to nearby enemies. Active: Tristana tosses an explosive charge at the target enemy that attaches to them for 4 seconds. The charge then detonates, dealing physical damage to nearby enemies. Explosive Charge can target and damage turrets, and explodes in a larger radius on a turret.","img":"TristanaE.png","cd":"16/15.5/15/14.5/14","cost":"50/55/60/65/70","range":"550"},"R":{"name":"Buster Shot","desc":"Active: Tristana fires a massive cannonball at the target enemy that deals magic damage. They and surrounding enemies are also knocked back and stunned for a duration, during which all targets are revealed.","img":"TristanaR.png","cd":"100","cost":"100","range":"550"}},"Trundle":{"title":"the Troll King","passive":{"name":"King's Tribute","desc":"Innate: Whenever a nearby enemy dies, Trundle heals himself for 1.8%–5.5% (based on level) of the target's maximum health.","img":"Trundle_Passive.png"},"Q":{"name":"Chomp","desc":"Active: Trundle empowers his next basic attack within 7 seconds to have an uncancellable windup, gain 25 bonus range, deal bonus physical damage and slow the target by 75% for 0.1 seconds. After using the empowered attack, Trundle gains bonus attack damage for 5 seconds and reduces the target's bonus attack damage by half that amount for the same duration. Chomp resets Trundle's basic attack timer.","img":"TrundleTrollSmash.png","cd":"3.5","cost":"20","range":"300"},"W":{"name":"Frozen Domain","desc":"Active: Trundle coats the target location in ice for 8 seconds. While he is within the area, he gains bonus attack speed, bonus movement speed, and 25% increased healing from all sources. Frozen Domain will cast at max range if cast beyond that.","img":"trundledesecrate.png","cd":"18/17/16/15/14","cost":"40","range":"750"},"E":{"name":"Pillar of Ice","desc":"Active: Trundle erects a pillar of ice at the target location for 6 seconds, which knocks back units hit to 225 units from its center. The pillar acts as terrain and slows nearby enemies.","img":"TrundleCircle.png","cd":"21/19.5/18/16.5/15","cost":"75","range":"1000"},"R":{"name":"Subjugate","desc":"Active: Trundle drains the life force out of the target enemy champion, dealing magic damage and healing himself for the same amount. He also steals 40% of their current bonus armor and magic resistance, and increases in size by 18% while reducing the target's size by 9.9%.","img":"TrundlePain.png","cd":"120/100/80","cost":"100","range":"650"}},"Tryndamere":{"title":"the Barbarian King","passive":{"name":"Battle Fury","desc":"Innate: Tryndamere generates 5 Fury on his basic attacks, and 10 Fury on critical strikes and each time he kills an enemy. After 8 seconds without dealing or taking damage, Tryndamere loses 5 Fury per second. Tryndamere gains 0%–50% (based on Fury) critical strike chance.","img":"Tryndamere_Passive.png"},"Q":{"name":"Bloodlust","desc":"Passive: Tryndamere gains bonus attack damage, plus an additional amount based on his missing health. Active: Tryndamere consumes all of his Fury to heal himself, increased for every point of Fury consumed.","img":"TryndamereQ.png","cd":"12","cost":"0","range":"400"},"W":{"name":"Mocking Shout","desc":"Active: Tryndamere reduces the bonus attack damage of nearby enemy champions for 4 seconds. Targets facing in the opposite direction of Tryndamere are also slowed for the duration. A nearby enemy champion is required to cast this ability. The target does not have to be visible to be targeted by this ability.","img":"TryndamereW.png","cd":"14","cost":"0","range":"850"},"E":{"name":"Spinning Slash","desc":"Active: Tryndamere dashes to the target location, dealing physical damage to enemies hit and generating 2 Fury per enemy hit, increased to 5 Fury against champions. Critical strikes on-hit reduce Spinning Slash's current cooldown by 0.75 seconds, doubled to 1.5 seconds against champions. Bloodlust and Undying Rage can be cast during the dash. Spinning Slash will cast at max range if cast beyond that.","img":"TryndamereE.png","cd":"12/11/10/9/8","cost":"0","range":"650"},"R":{"name":"Undying Rage","desc":"Active: Tryndamere becomes enraged, instantly gaining Fury and a minimum health threshold for 5 seconds. Undying Rage can be used while affected by cast-inhibiting crowd control.","img":"UndyingRage.png","cd":"120/100/80","cost":"0","range":"400"}},"TwistedFate":{"title":"the Card Master","passive":{"name":"Loaded Dice","desc":"Innate: Whenever Twisted Fate kills an enemy, he generates 1–6 (based on probability). He also has a chance equal to his critical strike chance to generate an additional 1–6 (based on probability). As you'd expect, Twisted Fate plays with loaded dice. His initial dice roll is weighted to have an increased chance of granting 6, while his critical dice roll is weighted against him and has an increased chance of granting 1.","img":"Cardmaster_SealFate.png"},"Q":{"name":"Wild Cards","desc":"Active: Twisted Fate throws a fan of three cards in a cone in the target direction that each deal magic damage to enemies hit. Enemies can be damaged only once per pass.","img":"WildCards.png","cd":"6/5.75/5.5/5.25/5","cost":"60/70/80/90/100","range":"10000"},"W":{"name":"Pick a Card","desc":"Active: Twisted Fate cycles through three cards for 6 seconds, hovering each for 0.5 seconds at a time. Pick a Card can be recast within the duration, which selects the current card hovered.","img":"PickACard.png","cd":"6","cost":"50/55/60/65/70","range":"200"},"E":{"name":"Stacked Deck","desc":"Passive: Twisted Fate gains bonus attack speed. His basic attacks on-hit generate a stack of Stacked Deck, stacking up to 3 times. At 3 stacks, his next basic attack is empowered to consume them all to deal bonus magic damage, reduced to 50% against structures.Twisted Fate gains maximum stacks of Stacked Deck upon respawning.","img":"CardmasterStack.png","cd":"0","cost":"0","range":"0"},"R":{"name":"Destiny","desc":"Active: Twisted Fate marks all targetable enemy champions, revealing them for a duration. Destiny can be recast after 0.5 seconds within the duration. Recast - Gate: Twisted Fate channels for 1.5 seconds before blinking to the target location, destroying all projectiles targeting him in the process.","img":"Destiny.png","cd":"170/140/110","cost":"100","range":"5500"}},"Twitch":{"title":"the Plague Rat","passive":{"name":"Deadly Venom","desc":"Innate: Twitch's basic attacks on-hit apply a stack of Deadly Venom for 6 seconds, refreshing on subsequent applications and stacking up to 6 times.","img":"Twitch_Passive.png"},"Q":{"name":"Ambush","desc":"Active: After a 1-second delay, Twitch becomes camouflaged for a duration. Attacking or casting Venom Cask or Contaminate ends Ambush immediately. During this time, Twitch gains 10% bonus movement speed, increased to 30% while facing enemy champions within a 1000-unit radius who cannot see him. Upon breaking stealth, Twitch gains bonus attack speed for 6 seconds.","img":"TwitchHideInShadows.png","cd":"16","cost":"40","range":"20"},"W":{"name":"Venom Cask","desc":"Active: Twitch hurls a cask of venom that explodes at the target location, applying Deadly Venom to enemies hit and granting sight of the area. The area then becomes contaminated for 3 seconds, applying a Deadly Venom stack each second to enemies within and slowing them.","img":"TwitchVenomCask.png","cd":"13/12/11/10/9","cost":"70","range":"950"},"E":{"name":"Contaminate","desc":"Active: Twitch sends out a lethal toxin to each nearby enemy afflicted by Deadly Venom, dealing them physical damage. Contaminate deals additional physical damage and 30% AP magic damage for each stack of Deadly Venom on the target. A nearby enemy with Deadly Venom is required to cast this ability. The target does not have to be visible to be targeted by this ability.","img":"TwitchExpunge.png","cd":"12/11/10/9/8","cost":"50/60/70/80/90","range":"1200"},"R":{"name":"Spray and Pray","desc":"Active: Twitch gains bonus attack damage and 300 bonus attack range for 6 seconds, during which his basic attacks are replaced by bolts that travel slightly further than his attack range in a straight line, dealing damage to every enemy unit hit. The bolts deal 100%–60% (based on enemies hit) of the triggering attack's damage, apply on-hit effects, and can critically strike for (175% + 40%) damage.","img":"TwitchFullAutomatic.png","cd":"90","cost":"100","range":"1200"}},"Udyr":{"title":"the Spirit Walker","passive":{"name":"Bridge Between","desc":"Innate - Awakened Spirit: Udyr has no ultimate ability and instead has 4 basic abilities that each incur a 1.5-second global cooldown when cast. Each ability grants a Stance that empowers his next two basic attacks, and switching Stances will replace the empowered attacks from the previous Stance.","img":"Udyr_P.png"},"Q":{"name":"Wilding Claw","desc":"Active - Stance: Udyr enters Claw Stance, empowering his next two basic attacks to gain 50 bonus range and deal bonus physical damage. Additionally, Udyr gains bonus attack speed and deals bonus physical damage on-hit for 4 seconds.","img":"UdyrQ.png","cd":"6","cost":"20","range":"600"},"W":{"name":"Iron Mantle","desc":"Active - Stance: Udyr enters Mantle Stance, empowering his next two basic attacks to gain life steal and heal him for 1.2% of his maximum health (+ 8% AP) on-hit. Additionally, Udyr grants himself a shield for 4 seconds.","img":"UdyrW.png","cd":"6","cost":"40","range":"0"},"E":{"name":"Blazing Stampede","desc":"Active - Stance: Udyr enters Stampede Stance, empowering his basic attacks to have an uncancellable windup and pounce on the target to stun them for 0.75 seconds. This cannot affect the same target more than once every few seconds. Additionally, Udyr becomes ghosted and gains bonus movement speed for 4 seconds, which decays to 30% effectiveness over 1.5 seconds.","img":"UdyrE.png","cd":"6","cost":"40","range":"600"},"R":{"name":"Wingborne Storm","desc":"Active - Stance: Udyr enters Storm Stance, empowering his next two basic attacks to deal 10–30 (based on level) (+ 30% AP) magic damage to nearby enemies. Additionally, Udyr summons a blizzard around himself for 4 seconds that deals magic damage every 0.5 seconds to nearby enemies and slows them. Minions take 50 / 60 / 70 / 80% (based on level) damage.","img":"UdyrR.png","cd":"6","cost":"40","range":"370"}},"Urgot":{"title":"the Dreadnought","passive":{"name":"Echoing Flames","desc":"Innate: Urgot's six legs each conceal a shotgun that covers an arc, together forming a full circle of cover around him. Each shotgun can fire once before incurring a unique cooldown.","img":"Urgot_Passive.png"},"Q":{"name":"Corrosive Charge","desc":"Active: Urgot launches a canister at the target location. Upon landing, it explodes after 0.3 seconds to deal physical damage to enemies hit and slow them for 1.25 seconds.","img":"UrgotQ.png","cd":"10/9.5/9/8.5/8","cost":"70","range":"800"},"W":{"name":"Purge","desc":"Passive: Urgot's other abilities mark enemy champions hit for 5 seconds. Only one enemy can be marked at a time. Additionally, at maximum rank, Purge lasts indefinitely and becomes a toggled ability.","img":"UrgotW.png","cd":"12/9/6/3/0","cost":"40/30/20/10/0","range":"490"},"E":{"name":"Disdain","desc":"Active: Urgot grants himself a shield for 4 seconds. After the cast time, Urgot dashes in the target direction, though not through terrain, dealing physical damage to enemies he passes through, knocking them aside and stunning them for 1 second. Urgot will stop upon hitting an enemy champion, stunning them for 1.5 seconds and, after 0.25 seconds, also flinging them to the location 100 units behind him, though not through terrain.","img":"UrgotE.png","cd":"16/15.5/15/14.5/14","cost":"60/70/80/90/100","range":"475"},"R":{"name":"Fear Beyond Death","desc":"Active: Urgot fires a chem-drill in the target direction that impales the first enemy champion hit, dealing physical damage and leashing the target for 4 seconds, during which they are revealed and slowed by 0%–75% (based on target's missing health).","img":"UrgotR.png","cd":"100/85/70","cost":"100","range":"2500"}},"Varus":{"title":"the Arrow of Retribution","passive":{"name":"Living Vengeance","desc":"Innate: When Varus kills an enemy, he gains 10 / 15 / 20% (based on level) bonus attack speed as well as bonus attack damage and ability power equal to 10% bonus attack speed for 5 / 7 / 9 / 11 (based on level) seconds. This is increased to 50% bonus attack speed and bonus attack damage and ability power equal to 25% bonus attack speed upon scoring a champion takedown.","img":"VarusPassive.png"},"Q":{"name":"Piercing Arrow","desc":"Active: Varus charges while being slowed by 20% for up to 4 seconds to increase Piercing Arrow's range over the first 1.5 seconds and its effects over the first 1.25 seconds of the channel. Piercing Arrow can be recast within the duration. If the charge completes without reactivation, Piercing Arrow is cancelled and refunds 50% of the mana cost.","img":"VarusQ.png","cd":"16/15/14/13/12","cost":"50/55/60/65/70","range":"925"},"W":{"name":"Blighted Quiver","desc":"Passive: Varus' basic attacks are empowered to deal bonus magic damage and apply a stack of Blight on-hit for 6 seconds, refreshing on subsequent applications and stacking up to 3 times. Varus' abilities detonate all Blight stacks on enemies hit.","img":"VarusW.png","cd":"40","cost":"0","range":"750"},"E":{"name":"Hail of Arrows","desc":"Active: Varus fires a hail of arrows at the target location that land after 0.5 seconds, dealing physical damage to enemies hit. The area then becomes desecrated for 4 seconds, slowing enemies within and inflicting them with Grievous Wounds. Hail of Arrows will cast at max range if cast beyond that.","img":"VarusE.png","cd":"18/16/14/12/10","cost":"90","range":"925"},"R":{"name":"Chain of Corruption","desc":"Active: Varus unleashes a tendril of corruption in the target direction that infects the first enemy champion hit, dealing magic damage and rooting them for 2 seconds, during which they are revealed. Over the first 1.5 seconds of the root, they are also inflicted with maximum stacks of Blight.","img":"VarusR.png","cd":"100/80/60","cost":"100","range":"1300"}},"Vayne":{"title":"the Night Hunter","passive":{"name":"Night Hunter","desc":"Innate: Vayne gains 30 bonus movement speed while facing a nearby visible enemy champion, increased to 90 while under the effects of Final Hour.","img":"Vayne_NightHunter.png"},"Q":{"name":"Tumble","desc":"Active: Vayne dashes a fixed distance in the target direction, though not through terrain, and empowers her next basic attack within 3 seconds to have an uncancelable windup and deal bonus physical damage. Tumble resets Vayne's basic attack timer.","img":"VayneTumble.png","cd":"6/5/4/3/2","cost":"46/42/38/34/30","range":"300"},"W":{"name":"Silver Bolts","desc":"Passive: Vayne's basic attacks on-hit and Condemn apply a stack of Silver Bolts for 3.5 seconds, refreshing on subsequent applications, expiring upon attacking a new enemy, and stacking up to 3 times. The third stack consumes them all to deal bonus true damage, with a minimum threshold. This damage is capped at 200 against monsters.","img":"VayneSilveredBolts.png","cd":"0","cost":"0","range":"750"},"E":{"name":"Condemn","desc":"Active: Vayne fires a heavy bolt at the target enemy that deals physical damage and knocks them back 475 units, though not through terrain. If the target collides with terrain, they take bonus physical damage and become stunned for 1.5 seconds.","img":"VayneCondemn.png","cd":"20/18/16/14/12","cost":"90","range":"550"},"R":{"name":"Final Hour","desc":"Active: Vayne equips her crossbow, gaining bonus attack damage for a duration. While active, Final Hour empowers Night Hunter to have tripled bonus movement speed and Tumble to have a reduced cooldown. Additionally, Tumble's cast grants Vayne invisibility for 1 second. Attacking or casting abilities ends the stealth immediately.","img":"VayneInquisition.png","cd":"100/85/70","cost":"80","range":"1"}},"Veigar":{"title":"the Tiny Master of Evil","passive":{"name":"Phenomenal Evil Power","desc":"Innate: Veigar generates a stack of Phenomenal Evil for each enemy champion hit by his abilities, and 5 stacks whenever he scores an enemy champion takedown. Phenomenal Evil: For each stack, Veigar gains 1 ability power.","img":"VeigarEntropy.png"},"Q":{"name":"Baleful Strike","desc":"Active: Veigar blasts a dark bolt in the target direction that deals magic damage to the first two enemies hit. If this kills an enemy, it generates 1 stack of Phenomenal Evil, tripled against large minions and monsters.","img":"VeigarBalefulStrike.png","cd":"6/5.5/5/4.5/4","cost":"30/35/40/45/50","range":"1000"},"W":{"name":"Dark Matter","desc":"Active: Veigar casts down a mass of dark matter that strikes the target location after a 1.221 seconds delay, dealing magic damage to enemies hit. Dark Matter's cooldown is reduced based on stacks of Phenomenal Evil.","img":"VeigarDarkMatter.png","cd":"0","cost":"60/65/70/75/80","range":"950"},"E":{"name":"Event Horizon","desc":"Active: Veigar forms a cage at the target location that erects after a 0.5 second delay, remaining there for 3 seconds. Enemies that collide with the edges of the cage are knocked down and stunned for a duration. Event Horizon can affect enemies only once per cast.","img":"VeigarEventHorizon.png","cd":"20/18.5/17/15.5/14","cost":"70/75/80/85/90","range":"725"},"R":{"name":"Primordial Burst","desc":"Active: Veigar sends a primordial burst at the target enemy champion that deals magic damage, increased by 0%–100% (based on target's missing health).","img":"VeigarR.png","cd":"120/90/60","cost":"100","range":"650"}},"Velkoz":{"title":"the Eye of the Void","passive":{"name":"Organic Deconstruction","desc":"Innate: Vel'Koz's abilities apply a stack of Deconstruction to enemies hit for 7 seconds, refreshing on basic attacks and subsequent applications and stacking up to 3 times. The third stack consumes them all to deal 35–180 (based on level) (+ 60% AP) bonus true damage.","img":"VelKoz_Passive.png"},"Q":{"name":"Plasma Fission","desc":"Active: Vel'Koz fires a plasma bolt in the target direction that deals magic damage to the first enemy hit and slows them by 70% decaying over a duration. Plasma Fission can be recast after 0.25 seconds while the bolt is in flight, and does so automatically upon hitting an enemy or reaching maximum range.","img":"VelkozQ.png","cd":"7","cost":"40/45/50/55/60","range":"1050"},"W":{"name":"Void Rift","desc":"Active: Vel'Koz cracks a rift in the target direction that opens after a 0.25-second delay, cascading through the area over 0.65 seconds to deal magic damage to enemies within. After 0.75 seconds, the rift violently collapses, dealing magic damage to enemies within and granting sight of the surrounding area for 0.25 seconds. Vel'Koz periodically stocks a Void Rift charge, up to a maximum of 2.","img":"VelkozW.png","cd":"1.5","cost":"50/55/60/65/70","range":"1050"},"E":{"name":"Tectonic Disruption","desc":"Active: Vel'Koz hurls a disruptive anomaly that lands to the target location after 0.25–0.55 (based on cast distance) seconds, dealing magic damage to enemies hit and knocking them up and stunning them for 0.75 seconds, as well as granting sight of the area briefly. If Tectonic Disruption is cast in close proximity of Vel'Koz, the anomaly will also slightly knock back enemies hit in the direction of the cast.","img":"VelkozE.png","cd":"12/11.5/11/10.5/10","cost":"50/55/60/65/70","range":"810"},"R":{"name":"Life Form Disintegration Ray","desc":"Passive - Researched: Applying 3 Deconstruction stacks to an enemy champion marks them as Researched for 7 seconds, refreshing on basic attacks and ability hits against them.","img":"VelkozR.png","cd":"100/90/80","cost":"100","range":"1575"}},"Vex":{"title":"the Gloomist","passive":{"name":"Doom 'n Gloom","desc":"Passive - Doom: Periodically, Vex empowers her next basic ability to knock down and fear enemies hit for 0.75 / 1 / 1.25 / 1.5 (based on level) seconds, during which they are slowed by 60%–99% (based on distance from Vex). If Looming Darkness triggers Doom, enemies hit will flee from the epicenter instead.Doom's cooldown resets upon respawning.","img":"Icons_Vex_Passive.png"},"Q":{"name":"Mistral Bolt","desc":"Active: Vex launches a wave of mist in the target direction that deals magic damage to enemies hit. After travelling 500 units, the wave accelerates but also narrows itself.","img":"VexQ.png","cd":"8/7/6/5/4","cost":"45/50/55/60/65","range":"1200"},"W":{"name":"Personal Space","desc":"Active: Vex emits a shockwave around her before the cast time, dealing magic damage to nearby enemies and granting herself a shield for 2.5 seconds.","img":"VexW.png","cd":"16/15/14/13/12","cost":"75","range":"475"},"E":{"name":"Looming Darkness","desc":"Active: Vex tosses her Shadow to explode at the target location, dealing magic damage to enemies hit and slowing them for 2 seconds. The explosion's radius increases based on cast distance. Killing an enemy with Looming Darkness refunds 10% of Doom's cooldown, increased to 25% for champion kills. Looming Darkness will cast at max range if cast beyond that.","img":"VexE.png","cd":"12","cost":"70/80/90/100/110","range":"800"},"R":{"name":"Shadow Surge","desc":"Active: Vex sends her Shadow in the target direction that grants sight around its trajectory and deals magic damage to enemies hit. Shadow stops upon hitting an enemy champion to mark them for 4 seconds, during which they are revealed. Shadow Surge can be recast while the target is marked. Recast: Vex dashes towards the marked target with displacement immunity. Upon arrival, she consumes their mark and deals magic damage.","img":"VexR.png","cd":"140/120/100","cost":"100","range":"2000/2500/3000"}},"Vi":{"title":"the Piltover Enforcer","passive":{"name":"Blast Shield","desc":"Innate: Periodically, Vi's next ability hit grants her a shield equal to 14% of her maximum health for 3 seconds. Blast Shield's cooldown is reduced by 4 seconds each time Denting Blows is consumed.","img":"ViPassive.png"},"Q":{"name":"Vault Breaker","desc":"Active: Vi charges while being slowed by 15% for up to 4 seconds to increase Vault Breaker's range, speed, and damage over the first 1.25 seconds of the channel. Vault Breaker can be recast within the duration. If the charge completes without reactivation, Vault Breaker is cancelled and put on full cooldown. If the charge is interrupted, it will be put on a 3-second cooldown.","img":"ViQ.png","cd":"12/10.5/9/7.5/6","cost":"50/60/70/80/90","range":"250"},"W":{"name":"Denting Blows","desc":"Passive: Vi's basic attacks on-hit and Vault Breaker apply a stack of Denting Blows to enemies hit for 4 seconds, refreshing on subsequent applications and stacking up to 3 times. The third stack consumes them all to deal bonus physical damage, capped at 300 against non-champions, and inflict 20% armor reduction for 4 seconds.","img":"ViW.png","cd":"0","cost":"0","range":"750"},"E":{"name":"Relentless Force","desc":"Active: Vi empowers her next basic attack within 6 seconds to have an uncancellable windup, gain 50 bonus range and trigger a blast in the target's direction that deals modified physical damage to enemies hit in a cone.Relentless Force can critically strike for (100% + 40%) AD bonus physical damage against the primary target. Secondary targets take the same damage but do not count as being critically struck.","img":"ViE.png","cd":"1","cost":"26/32/38/44/50","range":"400"},"R":{"name":"Cease and Desist","desc":"Active: Vi singles out the target enemy champion, dashing with displacement immunity towards them and revealing them. Upon approaching within 300 units of the target, she dashes through and grabs them over 1.05 seconds, knocking them up for 1.3 seconds and dealing physical damage after 0.75 seconds into the grab duration.","img":"ViR.png","cd":"140/115/90","cost":"100","range":"800"}},"Viego":{"title":"The Ruined King","passive":{"name":"Sovereign's Domination","desc":"Innate: Whenever Viego scores an enemy champion takedown while alive and within 3 seconds of damaging them, a Mist Wraith spawns from that champion's corpse for 8 seconds. Viego can basic attack a Mist Wraith to consume it: causing him to blink to its location after winding up for 1 second, during which he is untargetable (except to turrets) and unable to act. He then gains Possession and heals himself for 2% (+ 2.5% per 100 bonus AD) (+ 2% per 100 AP) (+ 5% per 100% bonus attack speed) of the target's maximum health.","img":"Viego_Passive.png"},"Q":{"name":"Blade of the Ruined King","desc":"Passive: Viego's basic attacks are empowered to deal bonus physical damage on-hit. This damage is affected by critical strike modifiers, has a minimum threshold and is capped at 80 against monsters.","img":"ViegoQ.png","cd":"5/4.5/4/3.5/3","cost":"0","range":"600"},"W":{"name":"Spectral Maw","desc":"Active: Viego charges while being slowed by 10% for up to 3 seconds to increase Spectral Maw's missile range and stun duration over the first second of the channel. Spectral Maw can be recast within the duration. If the charge completes without reactivation, Spectral Maw is cancelled and placed on full cooldown. If the charge is interrupted, it will be placed on a 3-second cooldown.","img":"ViegoW.png","cd":"8","cost":"0","range":"400"},"E":{"name":"Harrowed Path","desc":"Active: Viego sends a spectre in the target direction that creates a trail of mist in its wake which lasts 8 seconds. If it hits terrain, the mist will spread further around either side. While inside the mist, Viego gains bonus attack speed. If he does not attack or cast abilities, he also gains bonus movement speed and camouflage.","img":"ViegoE.png","cd":"14/12/10/8/6","cost":"0","range":"750"},"R":{"name":"Heartbreaker","desc":"Active: Viego gains displacement immunity over the cast time, then blinks to the target location. Upon arrival, he strikes the most wounded enemy champion nearby, dealing physical damage, slowing them by 99% for 0.25 seconds, and applying on-hit effects. Other nearby enemies are knocked back up to 400-units away based on proximity, though not through terrain.","img":"ViegoR.png","cd":"120/100/80","cost":"0","range":"500"}},"Viktor":{"title":"the Herald of the Arcane","passive":{"name":"Glorious Evolution","desc":"Innate: Viktor can augment each of his abilities at the cost of 100 Hex Fragments, which he gains from killing enemies: Minions and monsters generate 1 Hex Fragment. Siege minions, super minions, and epic monsters generate 10 Hex Fragments. Enemy champion takedowns generate 20 Hex Fragments. Arcane Storm can be augmented after all of Viktor's basic abilities have been augmented.","img":"Viktor_Passive.png"},"Q":{"name":"Siphon Power","desc":"Active: Viktor throws a draining device at the target enemy that deals magic damage. He also grants himself a shield for 40–115 (based on level) (+ 18% AP) for 2.5 seconds and gains Discharge for 3.5 seconds. Discharge: Viktor's next basic attack is empowered to become non-projectile and deal modified magic damage.","img":"ViktorQ.png","cd":"9/8/7/6/5","cost":"45/50/55/60/65","range":"600"},"W":{"name":"Gravity Field","desc":"Active: Viktor deploys a gravity field at the target location for 4.5 seconds. After a 0.75-second delay, it activates to slow enemies within for 1 second, refreshing every 0.25 seconds while they remain inside.","img":"ViktorW.png","cd":"17/16/15/14/13","cost":"65","range":"800"},"E":{"name":"Hextech Ray","desc":"Active: Viktor fires an energy beam along the target path that deals magic damage to enemies hit and briefly grants sight of the area. Augment: Aftershock — The path explodes along the beam's wake after 1 second, dealing magic damage to enemies hit.","img":"ViktorE.png","cd":"12/11/10/9/8","cost":"60/70/80/90/100","range":"525"},"R":{"name":"Arcane Storm","desc":"Active: Viktor conjures an arcane singularity at the target location, dealing magic damage to enemies within the area and disrupting their channeled abilities.","img":"ViktorR.png","cd":"120/100/80","cost":"100","range":"700"}},"Vladimir":{"title":"the Crimson Reaper","passive":{"name":"Crimson Pact","desc":"Innate: Vladimir gains (3.3% bonus health) as ability power and (160% AP) as bonus health. These two bonuses do not stack with each other.","img":"VladimirP.png"},"Q":{"name":"Transfusion","desc":"Active: Vladimir drains blood from the target enemy, dealing magic damage and healing himself. He then generates 1 point of Crimson Rush over the cooldown. At 2 points of Crimson Rush, Vladimir surges, gaining 10% / 20% / 30% / 40% (based on level) bonus movement speed for 0.5 seconds while the Crimson Rush depletes over 2.5 seconds. Crimson Rush depletes 75% slower during Sanguine Pool, Tides of Blood, or stasis.","img":"VladimirQ.png","cd":"9/7.9/6.8/5.7/4.6","cost":"0","range":"600"},"W":{"name":"Sanguine Pool","desc":"Active: Vladimir sinks into a pool of blood, becoming untargetable and ghosted for 2 seconds. He also gains 37.5% bonus movement speed that decays exponentially over 1 second. Enemies within the pool are dealt magic damage every 0.5 seconds over the duration and are slowed by 40%. Vladimir heals himself for 30% of the pre-mitigation damage dealt, reduced to 18% against minions.","img":"VladimirSanguinePool.png","cd":"28/25/22/19/16","cost":"0","range":"350"},"E":{"name":"Tides of Blood","desc":"Active: Vladimir charges for up to 1.5 seconds, during which he increases Tides of Blood's damage over the first second of the channel, and becomes slowed by 20% afterwards for the remaining duration. Tides of Blood can be recast within the duration, and does so automatically afterwards or if it is interrupted.","img":"VladimirE.png","cd":"13/11/9/7/5","cost":"0","range":"600"},"R":{"name":"Hemoplague","desc":"Active: Vladimir spreads a virulent plague at the target location that infects enemies hit for 4 seconds, increasing the damage they take from all sources by 10%. After the duration, the infection bursts to deal magic damage to all affected targets and, after a 0.4-second delay, heal Vladimir for each infected champion, reduced by 40% for champions beyond the first.","img":"VladimirHemoplague.png","cd":"120","cost":"0","range":"625"}},"Volibear":{"title":"the Relentless Storm","passive":{"name":"The Relentless Storm","desc":"Innate: Whenever Volibear damages at least one enemy with a basic attack or ability, he generates a stack of The Relentless Storm for 6 seconds, refreshing on subsequent damage and stacking up to 5 times. At 5 stacks, Volibear gains Lightning Claws. The Relentless Storm: For each stack, Volibear gains 5% (+ 4% per 100 AP) bonus attack speed, up to 25% (+ 20% per 100 AP).","img":"Volibear_Icon_P.png"},"Q":{"name":"Thundering Smash","desc":"Active: Volibear drops on all fours, becoming ghosted and gaining bonus movement speed for 4 seconds, doubled while facing a visible enemy champion within 2000 units. During this time, Volibear's next basic attack is empowered to have an uncancellable windup, gain 25 bonus range, and pounce on the target, dealing bonus physical damage and stunning them for 1 second. This damage applies life steal at 100% effectiveness.","img":"VolibearQ.png","cd":"12/11.5/11/10.5/10","cost":"50","range":"300"},"W":{"name":"Frenzied Maul","desc":"Active: Volibear slashes the target enemy with his claws to deal physical damage, apply on-hit effects, trigger on-attack effects, and mark the target Wounded for 8 seconds. Wounded Bonus: If the target is already Wounded, Volibear takes a bite out of them instead, dealing 50% (+ 15% per 100 bonus AD) increased damage and healing himself. The heal is halved against minions. Frenzied Maul applies life steal at 100% effectiveness.","img":"VolibearW.png","cd":"5","cost":"20/25/30/35/40","range":"325"},"E":{"name":"Sky Splitter","desc":"Active: Volibear summons a lightning bolt to strike at the target location after a 2-second delay, granting sight of the area for 1 second after the first second of the delay. If Volibear is within the strike, he gains a shield equal to 14% of his maximum health (+ 75% AP) for 3 seconds. The bolt deals magic damage to enemies hit, capped at 650 against non-champions, and slows them by 40% for 2 seconds.","img":"VolibearE.png","cd":"16","cost":"50","range":"1200"},"R":{"name":"Stormbringer","desc":"Active: Volibear gains Stormbringer for 12 seconds and leaps to the target location with displacement immunity, granting sight of the area in a 500 radius during the travel. Stormbringer: Volibear gains ghosting, bonus health, 50 bonus attack range, 25 increased range on Frenzied Maul, and 35% increased size.","img":"VolibearR.png","cd":"160/135/110","cost":"100","range":"550"}},"Warwick":{"title":"the Uncaged Wrath of Zaun","passive":{"name":"Eternal Hunger","desc":"Innate: Warwick deals 12–46 (based on level) (+ 15% bonus AD) (+ 10% AP) bonus magic damage on-hit. While below 50% maximum health, Warwick also heals for 100% of the post-mitigation damage dealt by Eternal Hunger, increased to 250% while below 25% maximum health.","img":"WarwickP.png"},"Q":{"name":"Jaws of the Beast","desc":"Active: Warwick lunges at the target enemy over 0.264 seconds and bites them, dealing magic damage, healing himself for a percentage of the post-mitigation damage dealt, applying on-hit effects and life steal at 100% effectiveness, and triggering on-attack effects. The damage based on the target's health ratio is capped against monsters.","img":"WarwickQ.png","cd":"8/7.5/7/6.5/6","cost":"80/85/90/95/100","range":"365"},"W":{"name":"Blood Hunt","desc":"Passive: Warwick gains bonus attack speed for 1.25 seconds upon damaging a target to or while they are below 50% of their maximum health with a basic attack or ability damage, refreshing with subsequent damaging basic attacks or ability damage to enemies below the threshold. If Warwick does not have the bonus attack speed already, he also gains it upon initiating an attack windup against an enemy below the threshold.","img":"WarwickW.png","cd":"80/70/60/50/40","cost":"55","range":"4000"},"E":{"name":"Primal Howl","desc":"Active: Warwick gains damage reduction for up to 2.5 seconds. Primal Howl can be recast after 1 second, and does so automatically after the duration. Recast: Warwick howls, ending Primal Howl's effects and fearing nearby enemies for 1 second, slowing them by 90%. Starting Infinite Duress' channel while Primal Howl is active will initiate the recast without ending the damage reduction buff prematurely.","img":"WarwickE.png","cd":"15/14/13/12/11","cost":"40","range":"375"},"R":{"name":"Infinite Duress","desc":"Active: Warwick leaps in the target direction with crowd control immunity, stopping upon hitting an enemy champion. He then knocks them down and channels for up to 1.5 seconds to suppress, reveal, and deal magic damage every 0.25 seconds, revealing himself in the process. Warwick heals for 100% of all post-mitigation damage he deals to the target during Infinite Duress.","img":"WarwickR.png","cd":"110/90/70","cost":"100","range":"25000"}},"Xayah":{"title":"the Rebel","passive":{"name":"Clean Cuts","desc":"Innate: Feathers shot by Xayah will linger in the ground at maximum range for 6 seconds.","img":"XayahPassive.png"},"Q":{"name":"Double Daggers","desc":"Active: Xayah barrages two Feathers in the target direction that each deal physical damage to enemies hit. Targets hit after the first take 50% reduced damage.","img":"XayahQ.png","cd":"10/9.5/9/8.5/8","cost":"35","range":"400"},"W":{"name":"Deadly Plumage","desc":"Active: Xayah enters a frenzy for 4 seconds, gaining bonus attack speed and empowering her basic attacks to fire an additional smaller feather at the target on-hit that deals 25% damage of the triggering attack's damage. Whenever Xayah hits an enemy champion with the strike, she gains 30% bonus movement speed for 1.5 seconds.","img":"XayahW.png","cd":"18/17/16/15/14","cost":"60/55/50/45/40","range":"1000"},"E":{"name":"Bladecaller","desc":"Active: Xayah recalls all planted Feathers to shoot back to her, each dealing physical damage to enemies hit, increased by 0%–75% (based on critical strike chance). Bladecaller deals 50% damage to minions. An enemy takes 100%–10% (based on previous feathers hit) damage from a Feather. A target hit by at least three Feathers is rooted for 1.25 seconds. Enemies can be hit by an individual Feather only once per pass.","img":"XayahE.png","cd":"12/11/10/9/8","cost":"20","range":"2000"},"R":{"name":"Featherstorm","desc":"Active: Xayah leaps into the air, becoming ghosted and untargetable for 1.5 seconds. After 1 second, she shoots 5 Feathers in a cone in the target direction that deal physical damage to enemies hit. Xayah is unable to basic attack or cast abilities during Featherstorm, but can still move.","img":"XayahR.png","cd":"140/120/100","cost":"100","range":"450"}},"Xerath":{"title":"the Magus Ascendant","passive":{"name":"Mana Surge","desc":"Innate: Periodically, Xerath empowers his next basic attack to restore 30–195 (based on level) mana, doubled to 60–390 (based on level) against enemy champions. Mana Surge's cooldown is reduced by 3.5 seconds whenever Xerath kills an enemy. Mana Surge does not trigger if Xerath would restore above his maximum mana.","img":"Xerath_Passive1.png"},"Q":{"name":"Arcanopulse","desc":"Active: Xerath charges while being slowed by 0%–40% (based on channel time) for up to 3 seconds to increase Arcanopulse's range over the first 1.5 to 1.75 seconds of the channel. Arcanopulse can be recast within the duration. If the charge is interrupted or completes without reactivation, Arcanopulse is cancelled and refunds half the mana cost.","img":"XerathArcanopulseChargeUp.png","cd":"9/8/7/6/5","cost":"80/90/100/110/120","range":"750"},"W":{"name":"Eye of Destruction","desc":"Active: Xerath casts down a blast of arcane energy that strikes the target location after 0.528 seconds, briefly granting sight of the area and dealing magic damage to enemies hit and slowing them by 25% for 2.5 seconds. Enemies in the epicenter take 66.7% increased damage and are slowed by a greater amount, decaying to 25% over the duration.","img":"XerathArcaneBarrage2.png","cd":"14/13/12/11/10","cost":"80/90/100/110/120","range":"1000"},"E":{"name":"Shocking Orb","desc":"Active: Xerath fires an orb of energy in the target direction that deals magic damage to the first enemy hit and stuns them for 0.75–2.25 (based on orb travel distance) seconds.","img":"XerathMageSpear.png","cd":"13/12.5/12/11.5/11","cost":"60/65/70/75/80","range":"1050"},"R":{"name":"Rite of the Arcane","desc":"Active: Xerath channels for up to 10 seconds, gaining the ability to recast Rite of the Arcane multiple times after 0.5 seconds within the duration. If Rite of the Arcane ends without any of the recasts being used, half of its cooldown is refunded.","img":"XerathLocusOfPower2.png","cd":"130/115/100","cost":"100","range":"5000"}},"XinZhao":{"title":"the Seneschal of Demacia","passive":{"name":"Determination","desc":"Innate: Xin Zhao's basic attacks on-hit and Wind Becomes Lightning strikes generate a stack of Determination, stacking up to 3 times. The third stack consumes them all to deal 15 / 30 / 45 / 60% (based on level) AD bonus physical damage on-attack and heal Xin Zhao for 3 / 3.5 / 4% (based on level) of his maximum health (+ 65% AP) on-hit.","img":"XinZhaoReworkP.png"},"Q":{"name":"Three Talon Strike","desc":"Active: Xin Zhao empowers his next three basic attacks on-attack within 5 seconds to each have an uncancellable windup, deal bonus physical damage and reduce his other abilities' current cooldowns by 1 second. Each attack refreshes the duration. The third attack knocks up the target for 0.75 seconds. Three Talon Strike's bonus damage is affected by critical strike modifiers. Three Talon Strike resets Xin Zhao's basic attack timer.","img":"XinZhaoQ.png","cd":"7/6.5/6/5.5/5","cost":"30","range":"375"},"W":{"name":"Wind Becomes Lightning","desc":"Active: Xin Zhao slashes in an arc and, after the cast time, thrusts his spear in a line in the target direction. Each strike deals physical damage to enemies hit, modified to 50%–100% (based on level) against minions. The thrust deals increased damage, further by 0%–33.3% (based on critical strike chance), and slows enemies hit by 50% for 1.5 seconds. Enemy champions and monsters hit are also marked Challenged for 3 seconds, during which they are revealed.","img":"XinZhaoW.png","cd":"12/11/10/9/8","cost":"60","range":"1000"},"E":{"name":"Audacious Charge","desc":"Active: Xin Zhao dashes to the target enemy's location, dealing magic damage to enemies near them and slowing them by 30% for 0.5 seconds. Audacious Charge's range is increased against Challenged targets. Xin Zhao then gains bonus attack speed for 5 seconds. Three Talon Strike and Crescent Guard can be cast during the dash.","img":"XinZhaoE.png","cd":"11","cost":"60","range":"650"},"R":{"name":"Crescent Guard","desc":"Passive - Challenge: The last enemy champion hit by Xin Zhao's basic attacks or Audacious Charge is marked Challenged for 3 seconds. Active: Xin Zhao sweeps his spear around him, dealing physical damage to nearby enemies, capped at 600 against monsters, and knocking back all non-Challenged targets hit up-to 700 units over 0.75 seconds, as well as stunning them for the same duration.","img":"XinZhaoR.png","cd":"120/110/100","cost":"100","range":"500"}},"Yasuo":{"title":"the Unforgiven","passive":{"name":"Way of the Wanderer","desc":"Innate - Intent: Yasuo's total critical strike chance is doubled from all other sources. Additionally,[ every 1% critical strike chance in excess of 100% is converted into 0.5 bonus attack damage. ][ every 50% critical strike chance in excess of 100% is converted into 25 bonus attack damage. ]","img":"Yasuo_Passive.png"},"Q":{"name":"Steel Tempest","desc":"Active: Yasuo thrusts his sword in a line in the target direction that deals physical damage to enemies hit, applies on-hit effects to the first enemy hit, and triggers on-attack effects once. Steel Tempest's damage based on its AD ratio can critically strike for (175% + 40%) damage.","img":"YasuoQ1Wrapper.png","cd":"4","cost":"0","range":"475"},"W":{"name":"Wind Wall","desc":"Active: Yasuo raises a wall of wind that travels in the target direction over 0.25 seconds. It then drifts another 50 units over 3.75 seconds, blocking all hostile non-turret projectiles that hit it and granting sight of its surroundings.","img":"YasuoW.png","cd":"25/23/21/19/17","cost":"0","range":"400"},"E":{"name":"Sweeping Blade","desc":"Active: Yasuo dashes a fixed distance in the direction of the target enemy and becomes ghosted for 2 seconds, refreshing on subsequent casts. Upon impact, he deals magic damage to the target and generates a stack of Ride the Wind for 5 seconds, which refreshes on subsequent hits and stacks up to 4 times. Ride the Wind: Sweeping Blade's damage is increased by 25% per stack, up to 100% at maximum stacks.","img":"YasuoE.png","cd":"0.5/0.4/0.3/0.2/0.1","cost":"0","range":"475"},"R":{"name":"Last Breath","desc":"Active: Yasuo blinks to the other side of a visible airborne enemy champion nearest to the cursor, instantly generating maximum Flow while resetting Gathering Storm stacks.","img":"YasuoR.png","cd":"70/50/30","cost":"0","range":"1400"}},"Yone":{"title":"the Unforgotten","passive":{"name":"Way of the Hunter","desc":"Innate - Intent: Yone's total critical strike chance is doubled from all other sources. Additionally,[ every 1% critical strike chance in excess of 100% is converted into 0.5 bonus attack damage. ][ every 50% critical strike chance in excess of 100% is converted into 25 bonus attack damage. ]","img":"YonePassive.png"},"Q":{"name":"Mortal Steel","desc":"Active: Yone thrusts his Steel Sword in a line in the target direction that deals physical damage to enemies hit, applies on-hit effects to the first enemy hit, and triggers on-attack effects once. Mortal Steel's damage based on its AD ratio can critically strike for (175% + 40%) damage.","img":"YoneQ.png","cd":"4","cost":"0","range":"450"},"W":{"name":"Spirit Cleave","desc":"Active: Yone cleaves his Azakana Sword in a cone in the target direction, dealing equal parts physical and magic damage to enemies hit. The total mixed damage has a minimum threshold of 40–410 (based on level) against minions and a maximum threshold of 150–320 (based on level) against monsters.","img":"YoneW.png","cd":"14","cost":"0","range":"700"},"E":{"name":"Soul Unbound","desc":"Active: Yone dashes a fixed distance in the target direction, including through terrain, discarding his body and entering Spirit Form for 5 seconds. Yone's body is untargetable and is sent the same distance behind the cast location, though not through terrain, and is reclaimed when Soul Unbound ends.","img":"YoneE.png","cd":"22/19/16/13/10","cost":"0","range":"25000"},"R":{"name":"Fate Sealed","desc":"Active: Yone prepares a strike over the cast time, then marks all enemies within an area in the target direction, knocking them down and stunning them for 1 second. He blinks 200 units beyond the center of the last enemy champion struck, or else to maximum range instead.","img":"YoneR.png","cd":"120/100/80","cost":"0","range":"1000"}},"Yorick":{"title":"Shepherd of Souls","passive":{"name":"Shepherd of Souls","desc":"Innate - Final Service: Whenever Yorick uses Last Rites to score the killing blow on any enemy or damage an enemy champion or large monster, he raises a grave at their location. Additionally, a grave is passively raised for every 8th: 2nd (based on level) enemy that dies otherwise near him. Up to 4 graves can exist at once, lasting until Yorick exits the general area or dies, with the furthest one always being replaced by the newest upon raising one over the limit.","img":"Yorick_P.png"},"Q":{"name":"Last Rites","desc":"Active: Yorick empowers his next basic attack within 5 seconds to have an uncancellable windup, gain 50 bonus range, deal bonus physical damage, and heal him. The heal is reduced by 50% against non-champions. While there are at least 3 graves nearby and Last Rites is active or on cooldown, Yorick can cast Awakening. Last Rites resets Yorick's basic attack timer.","img":"YorickQ.png","cd":"6/5.5/5/4.5/4","cost":"20","range":"0"},"W":{"name":"Dark Procession","desc":"Active: Yorick summons a ring of spirits around the target location that arises after a 0.75-second delay, knocking aside enemies hit over 0.25 seconds, though not through terrain. Within 210-units, they are pulled inside; otherwise they are pushed away. The ring remains for 4 seconds as impassible terrain against enemies, granting sight inside the ring.","img":"YorickW.png","cd":"20/18/16/14/12","cost":"70","range":"600"},"E":{"name":"Mourning Mist","desc":"Active: Yorick hurls a globule of Black Mist that splashes across an area at the target location, dealing magic damage to enemies hit, down to a minimum threshold against minions, and capped against monsters. Enemy champions and monsters hit are slowed by 30% for 1.5 seconds and marked as Cursed for 4 seconds.","img":"YorickE.png","cd":"12/11/10/9/8","cost":"50/55/60/65/70","range":"700"},"R":{"name":"Eulogy of the Isles","desc":"Active: Yorick summons the Maiden of the Mist over 1.5 seconds, along with a number of Mist Walkers surrounding her at the target location, which remain on the battlefield until she or Yorick dies. Eulogy of the Isles can be recast once while the Maiden is alive after 10 seconds of the activation. Recast: Yorick sets the Maiden free, allowing her to push the nearest lane until she dies.","img":"YorickR.png","cd":"160/130/100","cost":"100","range":"600"}},"Yunara":{"title":"the Unbroken Faith","passive":{"name":"Vow of the First Lands","desc":"Yunara's Critical Strikes deal bonus magic damage.","img":"Yunara_Passive.png"},"Q":{"name":"Cultivation of Spirit","desc":"Passive: Yunara deal magic damage %i:OnHit% On-Hit and attacking grants Unleash ( Unleash for champions). Active: Yunara consumes Unleash and for a short time gains Attack Speed and deals an additional magic damage %i:OnHit% On-Hit. During this time, her Attacks spread to nearby enemies dealing them physical damage. Transcendent State: This Ability is instantly activated for a short time.","img":"YunaraQ.png","cd":"0","cost":"30","range":"0"},"W":{"name":"Arc of Judgment | Arc of Ruin","desc":"Yunara lets rip a prayer bead that deals magic damage and Slows by decaying over seconds. It deals an additional magic damage per second. Transcendent State - Arc of Ruin: Yunara fires a laser that deals magic damage and Slows by decaying over second.","img":"YunaraW.png","cd":"10","cost":"60","range":"1150"},"E":{"name":"Kanmei's Steps | Untouchable Shadow","desc":"Yunara gains Move Speed, increased to Move Speed when moving toward an enemy champion, for a short time. Transcendent State - Untouchable Shadow: Yunara dashes in a direction.","img":"YunaraE.png","cd":"9","cost":"40","range":"0"},"R":{"name":"Transcend One's Self","desc":"Yunara enters a Transcendent State for a short time upgrading her basic Abilities for the duration.","img":"YunaraR.png","cd":"100/90/80","cost":"100","range":"0"}},"Yuumi":{"title":"the Magical Cat","passive":{"name":"Feline Friendship","desc":"Innate: Periodically, Yuumi's next basic attack, which has an uncancelable windup and gains 50 bonus range, ability hit against enemy champions, or Final Chapter hit on ally champions while attached, will heal her for 20–110 (based on level) (+ 25% AP). If she is attached to an ally or does so within 4 seconds, they are healed for the same amount.","img":"YuumiP2.png"},"Q":{"name":"Prowling Projectile","desc":"Active: Yuumi fires an errant missile in the target direction that deals magic damage to the first enemy hit. If the target is a champion, they are also revealed and slowed by 20% for 1 second.","img":"YuumiQ.png","cd":"6.5","cost":"50/55/60/65/70/75","range":"25000"},"W":{"name":"You and Me!","desc":"Passive: While Yuumi is attached, she is untargetable (except by turrets and inbound projectiles) and casts her abilities from the Anchor's position, empowering them with additional effects. Active: Yuumi channels for 0.25 seconds, then upon completion dashes to the target allied champion and attaches to them upon arrival, designating them as her Anchor. You and Me! can be recast after 0.5 seconds of the attachment.","img":"YuumiW.png","cd":"0","cost":"0","range":"25000"},"E":{"name":"Zoomies","desc":"Active: Yuumi grants herself a shield and gains bonus attack speed for 3 seconds. She also gains 20% bonus movement speed while the shield holds. Attached Bonus: Zoomies affects the Anchor instead of Yuumi and additionally restores mana to the Anchor, increased by 0%–100% (based on Anchor's missing mana).","img":"YuumiE.png","cd":"10","cost":"80/90/100/110/120","range":"25000"},"R":{"name":"Final Chapter","desc":"Active: Yuumi and Book channel for up to 3.5 seconds, during which they are ghosted, to launch 5 magical waves in the target direction. Allied champions hit by the waves are healed, with each heal instance beyond maximum health being converted into a shield that lasts for 1.5 seconds plus the remaining channel duration instead.","img":"YuumiR.png","cd":"120/110/100","cost":"100","range":"1100"}},"Zaahen":{"title":"The Unsundered","passive":{"name":"Cultivation of War","desc":"Zaahen's attacks and abilities against enemy champions grant him stacks of Determination, gaining bonus Attack Damage per stack. When filled with Determination, Zaahen gains increased Attack Damage and can revive.","img":"ZaahenP.png"},"Q":{"name":"The Darkin Glaive","desc":"Zaahen slashes twice on his next Attack, dealing bonus physical damage and restoring of his max Health. Recast: Zaahen's next Attack deals bonus physical damage and Knocks the target Up for a short time.","img":"ZaahenQ.png","cd":"10/9/8/7/6","cost":"25","range":"25000"},"W":{"name":"Dreaded Return","desc":"Zaahen stabs in a direction, dealing physical damage to enemies hit, then Pulls them toward him, dealing physical damage.","img":"ZaahenW.png","cd":"14/13.5/13/12.5/12","cost":"50","range":"850"},"E":{"name":"Aureate Rush","desc":"Zaahen dashes then slices around himself, dealing physical damage to nearby enemies. Enemies at the edge of the slice take physical damage + of their maximum Health as magic damage instead.","img":"ZaahenE.png","cd":"10/9.5/9/8.5/8","cost":"40","range":"25000"},"R":{"name":"Grim Deliverance","desc":"Passive: Zaahen gains %i:scaleAPen% Armor Penetration. Active: Zaahen rises, gaining Damage Reduction while casting. Zaahen then stabs downward, dealing physical damage and restoring of the damage dealt to enemy champions as Health.","img":"ZaahenR.png","cd":"110/95/80","cost":"100","range":"600"}},"Zac":{"title":"the Secret Weapon","passive":{"name":"Cell Division","desc":"Innate - The Secret Weapon: Zac gains increased percentage size equal to 1.5% of his bonus health, capped at 35% increased size at 2333.33 bonus health. Zac's size also reduces based on his missing health, down to 70% total size while at 0% health.","img":"ZacPassive.png"},"Q":{"name":"Stretching Strikes","desc":"Active: Zac stretches his left arm in the target direction that catches the first enemy hit, dealing magic damage, slowing them by 40% for 0.5 seconds, and forming a tether between Zac and the target for 2 seconds, during which they are revealed.","img":"ZacQ.png","cd":"14/12.5/11/9.5/8","cost":"0","range":"800"},"W":{"name":"Unstable Matter","desc":"Active: Zac explodes to deal magic damage to nearby enemies, capped against minions and monsters. Zac grants ghosting to aggroed monsters hit for 5 seconds. Unstable Matter's current cooldown is reduced by 1 second whenever Zac collects a Cell Division chunk.","img":"ZacW.png","cd":"5","cost":"0","range":"350"},"E":{"name":"Elastic Slingshot","desc":"Active: Zac charges for up to 4.5 seconds to increase Elastic Slingshot's range over a cone in the target direction. Elastic Slingshot can be recast within the duration. If Zac cancels the channel himself, or the charge completes without reactivation, 50% of Elastic Slingshot's health cost and cooldown are refunded.","img":"ZacE.png","cd":"21/18/15/12/9","cost":"0","range":"300"},"R":{"name":"Let's Bounce!","desc":"Active: Zac bounces after the cast time, then bounces 3 additional times each second over 3 seconds, during which he also gains 20%–50% (based on duration) bonus movement speed but becomes unable to declare basic attacks and cast Stretching Strikes and Elastic Slingshot. Each bounce deals magic damage to enemies hit, knocks them back over 1 second, and slows them by 20% for the same duration.","img":"ZacR.png","cd":"120/105/90","cost":"0","range":"300"}},"Zed":{"title":"the Master of Shadows","passive":{"name":"Contempt for the Weak","desc":"Innate: Zed's basic attacks against targets below 50% maximum health are empowered to deal 6 / 8 / 10% (based on level) of the target's maximum health as bonus magic damage. Against monsters, Contempt for the Weak deals 200% damage, capped at 300. Contempt for the Weak cannot occur on the same champion more than once every few seconds.","img":"ZedP.png"},"Q":{"name":"Razor Shuriken","desc":"Active: Zed throws a shuriken in the target direction that deals physical damage to enemies hit, reduced to 60% against targets beyond the first.","img":"ZedQ.png","cd":"6","cost":"75/70/65/60/55","range":"900"},"W":{"name":"Living Shadow","desc":"Passive: Zed restores energy whenever he and his Shadows or multiple Shadows hit an ability on the same target. This may only occur once per cast ability. Active: Zed creates a Shadow that dashes to the target location and remains there for 5.25 seconds, being able to mimic Razor Shuriken and Shadow Slash regardless of range. Living Shadow can be recast while within range of the Shadow.","img":"ZedW.png","cd":"20/19/18/17/16","cost":"40/35/30/25/20","range":"650"},"E":{"name":"Shadow Slash","desc":"Active: Zed slashes to deal physical damage to nearby enemies. Enemies hit by a Shadow's slash are slowed for 1.5 seconds, with multiple slashes dealing no additional damage but the slow's effectiveness being increased by 50%. Living Shadow's current cooldown is reduced by 3 seconds for each enemy champion hit by Zed's slash.","img":"ZedE.png","cd":"5/4.5/4/3.5/3","cost":"40","range":"290"},"R":{"name":"Death Mark","desc":"Active: Zed becomes untargetable and, after a 0.6-second delay, he dashes to 125 units beyond the target enemy champion from his position at the end of the delay over 0.35 seconds. Afterwards, he becomes targetable again, renders the target Marked for Death for 3 seconds, and gains ghosting for the same duration.","img":"ZedR.png","cd":"120/110/100","cost":"0","range":"625"}},"Zeri":{"title":"The Spark of Zaun","passive":{"name":"Living Battery","desc":"Innate: Zeri generates 1 charge for every 40 units she travels by any means and 10 charge every time she casts Burst Fire, up to a maximum of 100 charge. Her basic attacks consume charge to deal modified damage.Zeri gains maximum charge when the game starts and upon respawning.","img":"ZeriP.png"},"Q":{"name":"Burst Fire","desc":"Active: Zeri fires a burst of 7 rounds in the target direction that each deal physical damage to the first enemy hit.","img":"ZeriQ.png","cd":"0","cost":"0","range":"700"},"W":{"name":"Ultrashock Laser","desc":"Active: Zeri fires an electric pulse in the target direction that deals physical damage to the first enemy hit and slows them for 2 seconds.If the pulse hits terrain, it transforms into a laser in a line that grants sight of the area for 1.75 seconds and fires after 0.85 seconds, applying the same effects to enemies hit and critically striking for (175% + 40%) damage against champions and monsters.","img":"ZeriW.png","cd":"12/11/10/9/8","cost":"50/60/70/80/90","range":"1150"},"E":{"name":"Spark Surge","desc":"Active: Zeri dashes in the target direction. She will dash farther across terrain if Spark Surge was cast within 50 units of any, gaining unobstructed vision of the surrounding 800 units and revealing herself while there are enemy champions within 1500 units of her.","img":"ZeriE.png","cd":"24/22.5/21/19.5/18","cost":"90/85/80/75/70","range":"25000"},"R":{"name":"Lightning Crash","desc":"Active: Zeri discharges an electric nova that deals magic damage to nearby enemies. If this hits at least one enemy champion, she enters Overcharged for 5 seconds. Hitting an enemy champion with an ability or charged basic attack will extend the duration by 1.5 seconds, up to its original duration.","img":"ZeriR.png","cd":"80/75/70","cost":"100","range":"800"}},"Ziggs":{"title":"the Hexplosives Expert","passive":{"name":"Short Fuse","desc":"Innate: Periodically, Ziggs empowers his next basic attack to deal 20–160 (based on level) (+ 50% AP) bonus magic damage,[ increased by 75% against structures. ][ increased to 35–280 (based on level) (+ 87.5% AP) against structures. ] Short Fuse's cooldown is reduced by 4 / 5 / 6 (based on level) seconds whenever Ziggs casts an ability.","img":"ZiggsPassiveReady.png"},"Q":{"name":"Bouncing Bomb","desc":"Active: Ziggs throws a bomb to the target location that bounces forward up to two times, with the distance traveled each time being based on how far it was originally thrown. The bomb explodes upon landing near an enemy, within terrain, or the final bounce, dealing magic damage to nearby enemies. Bouncing Bomb will cast at max range if cast beyond that.","img":"ZiggsQ.png","cd":"6/5.5/5/4.5/4","cost":"50/55/60/65/70","range":"850"},"W":{"name":"Satchel Charge","desc":"Active: Ziggs hurls a charge to the target location, remaining there for 4 seconds and granting sight of the area. Satchel Charge can be recast within the duration, and does so automatically afterwards. If recast while in flight, the charge will explode immediately upon landing.","img":"ZiggsW.png","cd":"20/18/16/14/12","cost":"80","range":"1000"},"E":{"name":"Hexplosive Minefield","desc":"Active: Ziggs scatters a cluster of 11 proximity mines over the target location that grant sight of the area for 2 seconds, arming after 0.5 seconds and lasting for up to 10 seconds. Each mine within the area explodes upon contact with terrain or an enemy, dealing magic damage and slowing them for 1.5 seconds, as well as granting sight of the area around the explosion for 2 seconds. An enemy takes 40% damage from subsequent mines.","img":"ZiggsE.png","cd":"16","cost":"70/80/90/100/110","range":"900"},"R":{"name":"Mega Inferno Bomb","desc":"Active: Ziggs catapults the Mega Inferno Bomb to the target location, granting sight within a 600 radius around its destination for 4 seconds. The bomb explodes upon arrival to deal magic damage to enemies hit, increased by 50% against those in the epicenter.","img":"ZiggsR.png","cd":"120/95/70","cost":"100","range":"5000"}},"Zilean":{"title":"the Chronokeeper","passive":{"name":"Time In A Bottle","desc":"Innate: Zilean generates 2 / 3.5 / 5 / 6 / 12 (based on level) experience (does not count towards his own level up) every 5 seconds. Time in a Bottle is on cooldown when the game starts and becomes disabled when everyone on Zilean's team including himself has reached level 18.","img":"Zilean_Passive.png"},"Q":{"name":"Time Bomb","desc":"Active: Zilean throws a ticking time bomb to the target location that grants sight of its surroundings. The bomb will attach itself to units that move within the epicenter, or those hit directly, revealing them. After 3 seconds, or when the attached unit dies, the bomb explodes to deal magic damage to nearby enemies. The bomb detonates immediately if another bomb attaches itself to the same unit, stunning nearby enemies for a duration.","img":"ZileanQ.png","cd":"10/9.5/9/8.5/8","cost":"60/65/70/75/80","range":"900"},"W":{"name":"Rewind","desc":"Active: Zilean reduces the remaining cooldowns of Time Bomb and Time Warp by 10 seconds each. Either Time Bomb or Time Warp must be on cooldown to cast this ability.","img":"ZileanW.png","cd":"14/12/10/8/6","cost":"35","range":"600"},"E":{"name":"Time Warp","desc":"Active: Zilean applies Time Warp to the target champion which lasts for 2.5 seconds. Time Warp: If the target is an ally, they gain bonus movement speed. If the target is an enemy, they are slowed.","img":"TimeWarp.png","cd":"15","cost":"50","range":"550"},"R":{"name":"Chronoshift","desc":"Active: Zilean places a protective time rune on the target allied champion or himself for 5 seconds. If the target takes fatal damage within the duration, they enter resurrection for 3 seconds, becoming invulnerable, untargetable, and unable to act. Afterwards, they revive while being healed.","img":"ChronoShift.png","cd":"120/90/60","cost":"125/150/175","range":"900"}},"Zoe":{"title":"the Aspect of Twilight","passive":{"name":"More Sparkles!","desc":"Innate: After casting an ability, Zoe empowers her next basic attack or Spell Thief bolt within 5 seconds to become non-projectile and deal 16–130 (based on level) (+ 20% AP) bonus magic damage.","img":"Zoe_P.png"},"Q":{"name":"Paddle Star!","desc":"Active: Zoe shoots a star in the target direction that explodes upon hitting an enemy, dealing magic damage to nearby enemies hit. The total damage is increased by 0%–150% (based on distance traveled). The star lingers at maximum range for 1 second, during which Paddle Star can be recast after 0.25 seconds in the duration.","img":"ZoeQ.png","cd":"8.5/8/7.5/7/6.5","cost":"40/45/50/55/60","range":"800"},"W":{"name":"Spell Thief","desc":"Passive - Wheeeee: Whenever Zoe casts Spell Thief or a summoner spell, she gains bonus movement speed for a duration, and summons three bolts that orbit her for the next 10 seconds. If Zoe is not affected by complete crowd control, she shoots one bolt at a time at the nearest non-sleeping enemy in range, prioritizing her attack target, dealing magic damage with each bolt.","img":"ZoeW.png","cd":"0.25","cost":"0","range":"3000/4500/6000/3000/3000"},"E":{"name":"Sleepy Trouble Bubble","desc":"Active: Zoe kicks a bubble in the target direction that bursts upon the first enemy hit, otherwise lingering at maximum range over 1 second, then becoming a trap for 5 seconds that bursts upon contact with an enemy. The bubble can move through terrain only once, but travels the entire distance as bonus range, and will fall short if it would enter terrain again.","img":"ZoeE.png","cd":"18/17/16/15/14","cost":"80","range":"800"},"R":{"name":"Portal Jump","desc":"Active: After a 0.15-second delay, Zoe blinks in the target direction and remains there for 0.95 seconds to 1.25 seconds, during which she sets her movement speed to a static 0 and has unobstructed vision. Afterwards, she blinks back to her casting position. Portal Jump resets Zoe's basic attack timer. Zoe briefly becomes unable to act after casting Portal Jump as well as after blinking back.","img":"ZoeR.png","cd":"11/8/5","cost":"40","range":"575"}},"Zyra":{"title":"Rise of the Thorns","passive":{"name":"Garden of Thorns","desc":"Innate: Periodically, Zyra spawns one or two Seeds nearby that last for 30 seconds, granting sight over the surrounding area for 1 second. After 1 second, enemy champions can destroy Seeds by stepping on them. Zyra can only have a total of 8 Seeds planted at a time, preserving Seeds spawned by Rampant Growth over Seeds spawned by Garden of Thorns.","img":"ZyraP.png"},"Q":{"name":"Deadly Spines","desc":"Active: Zyra sprouts thorny spines at the target location that appear after a 0.625-seconds delay, dealing magic damage to enemies hit. If Deadly Spine hits a Seed, it sprouts into a Thorn Spitter that remains for 8 seconds.","img":"ZyraQ.png","cd":"7/6.5/6/5.5/5","cost":"55","range":"800"},"W":{"name":"Rampant Growth","desc":"Active: Zyra plants a Seed at the target location that remains for 60 seconds and grants sight over the surrounding area, though decreasing in radius after 1 second. After 1.5 seconds, enemy champions can destroy the Seed by stepping on it, which reveals them for 2 seconds.","img":"ZyraW.png","cd":"0","cost":"0","range":"850"},"E":{"name":"Grasping Roots","desc":"Active: Zyra shoots a surge of vines in the target direction that deals magic damage to enemies hit and roots them for a duration. If Grasping Roots hits a Seed, it sprouts into a Vine Lasher, which remains on the battlefield for 8 seconds.","img":"ZyraE.png","cd":"11","cost":"70/75/80/85/90","range":"1100"},"R":{"name":"Stranglethorns","desc":"Active: Zyra summons a monstrous thicket at the target location that deals magic damage to enemies hit as it expands. After 2 seconds, the thicket snaps upward to knock up enemies within for 1 second.","img":"ZyraR.png","cd":"110/100/90","cost":"100","range":"700"}}};

export const abilitiesOf = (dd) => ABILITIES[dd] || null;
